INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shimo4228/claude-code-learned-skills/swift-actor-persistence', 'community', 'shimo4228', 'claude-code-learned-skills', 'shimo4228/claude-code-learned-skills', 'swift-actor-persistence', 0, 0, 53, '2026-03-08T01:57:15.661Z', '2026-03-08T02:14:06.016Z', '69c4c1a2a18b5caccb66715faf60c1882b1afdeee1262a9e4a5c5475eceb01e8', '{"id":"shimo4228/claude-code-learned-skills/swift-actor-persistence","name":"swift-actor-persistence","description":{"en":"swift-actor-persistence provides practical patterns for thread-safe data persistence in iOS/Swift apps, helping developers avoid race conditions and ensure reliable data storage","zh":"Swift Actor Persistence 是一个用于实现线程安全数据持久化的实用模式和最佳实践集合","ja":"Swift Actor Persistence は、スレッドセーフなデータ永続化のための実践的なパターンとベストプラクティスのコレクションです","ko":"Swift Actor Persistence는 스레드 안전한 데이터 지속성을 위한 실제 패턴 및 최고의 관행을 수집","es":"swift-actor-persistence es una colección de patrones prácticos para la persistencia de datos segura en iOS/Swift, aprendidos a través del uso real de Claude Code.","fr":"swift-actor-persistence est une collection de modèles pratiques pour une persistence de données sécurisée dans les applications iOS/Swift, appris à travers l''utilisation réelle de Claude Code.","de":"swift-actor-persistence ist eine Sammlung von praktischen Mustern für die sichere Datenspeicherung in iOS/Swift-Apps, die durch die reale Verwendung von Claude Code erlernt wurden.","pt":"O Swift Actor Persistence fornece padrões práticos para persistência de dados thread-safe em apps iOS/Swift","ru":"Персистенция акторов Swift обеспечивает практические шаблоны для потокобезопасного хранения данных в приложениях iOS/Swift","ar":"التماسك السريع لموالية Swift يوفر قوالب عملية لتخزين البيانات آمنة للخيط في تطبيقات iOS/Swift"},"seo":{"title":{"en":"swift-actor-persistence: Thread-Safe Data Persistence Set...","zh":"Swift Actor Persistence Setup Guide - AI工具","ja":"Swift Actor Persistence ベストプラクティス - AIエージェント","ko":"Swift Actor Persistence 구현 가이드 - AI 에이전트","es":"Guía de configuración de swift-actor-persistence para per...","fr":"Guide de mise en place de swift-actor-persistence pour un...","de":"Einrichtungsleitfaden für swift-actor-persistence zur sic...","pt":"Guia de Configuração do Swift Actor Persistence","ru":"Настройка персистенции акторов Swift: лучшие практики","ar":"إعداد مرشد للتماسك السريع لموالية Swift"},"description":{"en":"Discover how to implement thread-safe data persistence in iOS/Swift apps using swift-actor-persistence - get started with our expert guide and tutorials","zh":"使用 Swift Actor 实现线程安全的数据持久化，了解实用模式和最佳实践","ja":"Swift Actor を使用してスレッドセーフなデータ永続化を実現し、実践的なパターンとベストプラクティスを学ぶ","ko":"Swift Actor를 사용하여 스레드 안전한 데이터 지속성을 구현하고 실제 패턴 및 최고의 관행을 학습","es":"Aprende a implementar patrones prácticos y mejores prácticas para la persistencia de datos segura en iOS/Swift con swift-actor-persistence, Herramientas de I...","fr":"Découvrez comment mettre en œuvre des modèles pratiques et des meilleures pratiques pour une persistence de données sécurisée dans les applications iOS/Swift...","de":"Erfahren Sie, wie Sie praktische Muster und Best Practices für die sichere Datenspeicherung in iOS/Swift-Apps mit swift-actor-persistence umsetzen, KI-Tools","pt":"Aprenda a implementar a persistência de dados thread-safe em apps iOS/Swift com os atores Swift e async/await","ru":"Изучите, как реализовать потокобезопасное хранение данных в приложениях iOS/Swift с помощью акторов Swift и async/await","ar":"تعلم كيفية تنفيذ التخزين الآمن للخيط في تطبيقات iOS/Swift باستخدام ممثلي Swift و async/await"},"definition":{"en":"swift-actor-persistence is a collection of patterns and best practices for achieving thread-safe data persistence in iOS/Swift apps using async/await","zh":"Swift Actor Persistence 是一种使用 Swift Actor 实现线程安全的数据持久化技术","ja":"Swift Actor Persistence は、Swift Actor を使用してスレッドセーフなデータ永続化を実現する技術です","ko":"Swift Actor Persistence는 Swift Actor를 사용하여 스레드 안전한 데이터 지속성을 구현하는 기술","es":"swift-actor-persistence es un conjunto de patrones y prácticas para la persistencia de datos segura en iOS/Swift.","fr":"swift-actor-persistence est un ensemble de modèles et de pratiques pour une persistence de données sécurisée dans les applications iOS/Swift.","de":"swift-actor-persistence ist ein Satz von Mustern und Praktiken für die sichere Datenspeicherung in iOS/Swift-Apps.","pt":"O que é Swift Actor Persistence? É uma coleção de padrões para persistência de dados thread-safe em apps iOS/Swift","ru":"Что такое персистенция акторов Swift? Это коллекция шаблонов для потокобезопасного хранения данных в приложениях iOS/Swift","ar":"ما هو التماسك السريع لموالية Swift؟ هو مجموعة من القوالب لتخزين البيانات آمنة للخيط في تطبيقات iOS/Swift"},"features":{"en":["Utilizes Swift Actors for thread-safe data access","Supports async/await for non-blocking data persistence","Provides solutions to common race condition problems","Offers best practices for iOS/Swift app data storage","Helps developers avoid traditional error-prone approaches like DispatchQueues and locks","Enables reliable data persistence in concurrent programming environments"],"zh":["使用 Swift Actor 实现线程安全的数据持久化","支持 async/await 异步编程","提供实用模式和最佳实践","适用于 iOS/Swift 应用","解决数据持久化层的竞态条件问题","替代传统的DispatchQueues和锁机制"],"ja":["Swift Actor を使用してスレッドセーフなデータ永続化を実現","async/await を使用した非同期プログラミングをサポート","実践的なパターンとベストプラクティスを提供","iOS/Swift アプリ向け","データ永続化レイヤーのレースコンディション問題を解決","従来の DispatchQueues とロックメカニズムの代替"],"ko":["Swift Actor를 사용하여 스레드 안전한 데이터 지속성을 구현","async/await를 사용한 비동기 프로그래밍 지원","실제 패턴 및 최고의 관행 제공","iOS/Swift 애플리케이션용","데이터 지속성 레이어의 경쟁 조건 문제 해결","従来의 DispatchQueues 및 잠금 메커니즘의 대체"],"es":["Patrones prácticos para la persistencia de datos segura","Uso de Swift Actors para la gestión de datos","Compatibilidad con async/await para la programación asíncrona","Solución de problemas de concurrencia en la capa de persistencia de datos","Mejores prácticas para la implementación de la persistencia de datos en iOS/Swift"],"fr":["Modèles pratiques pour une persistence de données sécurisée","Utilisation de Swift Actors pour la gestion des données","Compatibilité avec async/await pour la programmation asynchrone","Résolution de problèmes de concurrence dans la couche de persistence de données","Meilleures pratiques pour la mise en œuvre de la persistence de données dans les applications iOS/Swift"],"de":["Praktische Muster für die sichere Datenspeicherung","Verwendung von Swift Actors für die Datenverwaltung","Kompatibilität mit async/await für die asynchrone Programmierung","Lösung von Konkurrenzproblemen in der Datenspeicherschicht","Best Practices für die Implementierung der Datenspeicherung in iOS/Swift-Apps"],"pt":["Padrões práticos para persistência de dados thread-safe","Uso de atores Swift para evitar condições de corrida","Integração com async/await para operações de leitura e gravação","Implementação de camadas de persistência de dados em apps iOS/Swift","Uso de DispatchQueues e locks para controle de threads"],"ru":["Практические шаблоны для потокобезопасного хранения данных","Использование акторов Swift для предотвращения гонок","Интеграция с async/await для операций чтения и записи","Реализация слоев хранения данных в приложениях iOS/Swift","Использование DispatchQueues и блокировок для контроля потоков"],"ar":["قوالب عملية لتخزين البيانات آمنة للخيط","استخدام ممثلي Swift لتجنب ظروف السباق","التكامل مع async/await للعمليات القراءة والكتابة","تنفيذ طبقات تخزين البيانات في تطبيقات iOS/Swift","استخدام DispatchQueues والقفل للتحكم في الخيط"]},"keywords":{"en":["how to use swift-actor-persistence","swift-actor-persistence alternative","swift-actor-persistence setup guide","what is swift-actor-persistence","swift-actor-persistence vs DispatchQueues","swift-actor-persistence install","thread-safe data persistence in iOS","async/await in Swift","swift-actor-persistence tutorial","ios data storage best practices"],"zh":["Swift Actor Persistence","AI工具","线程安全","数据持久化","async/await","iOS/Swift","实用模式","最佳实践","竞态条件"],"ja":["Swift Actor Persistence","AIエージェント","スレッドセーフ","データ永続化","async/await","iOS/Swift","実践的なパターン","ベストプラクティス","レースコンディション"],"ko":["Swift Actor Persistence","AI 에이전트","스레드 안전","데이터 지속성","async/await","iOS/Swift","실제 패턴","최고의 관행","경쟁 조건"],"es":["swift-actor-persistence","persistencia de datos segura","iOS/Swift","Swift Actors","async/await","Herramientas de Inteligencia Artificial","desarrollo de aplicaciones móviles","programación asíncrona"],"fr":["swift-actor-persistence","persistence de données sécurisée","iOS/Swift","Swift Actors","async/await","Outils d''Intelligence Artificielle","développement d''applications mobiles","programmation asynchrone"],"de":["swift-actor-persistence","sichere Datenspeicherung","iOS/Swift","Swift Actors","async/await","KI-Tools","Entwicklung von mobilen Anwendungen","asynchrone Programmierung"],"pt":["Swift Actor Persistence","persistência de dados thread-safe","aplicativos iOS/Swift","atores Swift","async/await","DispatchQueues","locks","padrões de projeto","desenvolvimento de aplicativos móveis"],"ru":["персистенция акторов Swift","потокобезопасное хранение данных","приложения iOS/Swift","акторы Swift","async/await","DispatchQueues","блокировки","шаблоны проектирования","разработка мобильных приложений"],"ar":["التماسك السريع لموالية Swift","تخزين البيانات آمنة للخيط","تطبيقات iOS/Swift","ممثلي Swift","async/await","DispatchQueues","القفل","قوالب التصميم","تطوير التطبيقات المتنقلة"]}},"owner":"shimo4228","repo":"claude-code-learned-skills","repoPath":"shimo4228/claude-code-learned-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.661Z","topics":[],"category":"community","skillMd":{"name":"swift-actor-persistence","description":"Use when building a thread-safe data persistence layer in Swift using actors with in-memory cache and file storage.","version":"1.0","bodyPreview":"# Swift Actors for Thread-Safe Persistence\n# スレッドセーフな永続化のためのSwift Actor\n\n**Extracted / 抽出日:** 2026-02-05\n**Context / コンテキスト:** iOS/Swift apps requiring thread-safe data persistence with async/await\nasync/awaitを使用したスレッドセーフなデータ永続化が必要なiOS/Swiftアプリ\n\n---\n\n## Problem / 課題\n\nData persistence layers often face race conditions when multiple parts of an app read/write simultaneously. Traditional approaches (DispatchQueues, locks) are error-prone and verbose.\n\nデータ永続化レイヤーは、アプリの複数の部分が同時に読み書きする際にレースコンディションに直面す","body":"# Swift Actors for Thread-Safe Persistence\n# スレッドセーフな永続化のためのSwift Actor\n\n**Extracted / 抽出日:** 2026-02-05\n**Context / コンテキスト:** iOS/Swift apps requiring thread-safe data persistence with async/await\nasync/awaitを使用したスレッドセーフなデータ永続化が必要なiOS/Swiftアプリ\n\n---\n\n## Problem / 課題\n\nData persistence layers often face race conditions when multiple parts of an app read/write simultaneously. Traditional approaches (DispatchQueues, locks) are error-prone and verbose.\n\nデータ永続化レイヤーは、アプリの複数の部分が同時に読み書きする際にレースコンディションに直面することが多い。従来のアプローチ（DispatchQueues、ロック）はエラーが発生しやすく、冗長になりがち。\n\n---\n\n## Solution / 解決策\n\nUse Swift actors to isolate all persistence state and operations. The actor model guarantees:\n- No data races (compiler-enforced)\n- Automatic serialization of access\n- Async-first API that integrates with structured concurrency\n\nSwift actorを使用して、すべての永続化状態と操作を分離する。actorモデルは以下を保証：\n- データ競合なし（コンパイラによる強制）\n- アクセスの自動シリアライズ\n- 構造化並行性と統合されたasyncファーストAPI\n\n```swift\npublic actor LocalRepository {\n    private var cache: [String: Record] = [:]\n    private let cacheFileURL: URL\n\n    public init(directory: URL = .documentsDirectory) {\n        self.cacheFileURL = directory.appendingPathComponent(\"cache.json\")\n        // Synchronous cache load during init (actor isolation not yet active)\n        // init中の同期キャッシュ読み込み（actor分離がまだアクティブでないため）\n        self.cache = Self.loadCacheSynchronously(from: cacheFileURL)\n    }\n\n    public func save(_ record: Record) throws {\n        cache[record.id] = record\n        try persistToFile()\n    }\n\n    public func loadAll() -> [Record] {\n        Array(cache.values)\n    }\n\n    public func find(by id: String) -> Record? {\n        cache[id]\n    }\n\n    private func persistToFile() throws {\n        let data = try JSONEncoder().encode(Array(cache.values))\n        try data.write(to: cacheFileURL)\n    }\n\n    private static func loadCacheSynchronously(from url: URL) -> [String: Record] {\n        guard let data = try? Data(contentsOf: url),\n              let records = try? JSONDecoder().decode([Record].self, from: data) else {\n            return [:]\n        }\n        return Dictionary(uniqueKeysWithValues: records.map { ($0.id, $0) })\n    }\n}\n```\n\n---\n\n## Key Patterns / 主要パターン\n\n1. **In-memory cache + file persistence / インメモリキャッシュ + ファイル永続化**: Fast reads from cache, durable writes to disk / キャッシュからの高速読み取り、ディスクへの永続書き込み\n2. **Synchronous init loading / 同期的な初期化読み込み**: Avoids async initialization complexity / 非同期初期化の複雑さを回避\n3. **Dictionary keying / Dictionary型によるキー管理**: O(1) lookups by ID / IDによるO(1)の検索\n4. **Private persistence / プライベートな永続化**: External callers only see domain operations / 外部呼び出し元はドメイン操作のみを参照\n\n---\n\n## Usage / 使用方法\n\n```swift\nlet repository = LocalRepository()\n\n// All calls are async due to actor isolation\n// actor分離により、すべての呼び出しは非同期\nlet records = await repository.loadAll()\ntry await repository.save(newRecord)\nlet found = await repository.find(by: \"question-1\")\n```\n\n---\n\n## When to Use / 使用すべき場面\n\n- Building a data persistence layer in Swift 5.5+ / Swift 5.5以降でデータ永続化レイヤーを構築する場合\n- Need thread-safe access to shared state / 共有状態へのスレッドセーフなアクセスが必要な場合\n- Want to avoid manual synchronization (locks, queues) / 手動同期（ロック、キュー）を避けたい場合\n- Building offline-first apps with local storage / ローカルストレージを使用したオフラインファーストアプリを構築する場合\n\n---\n\n## Related Patterns / 関連パターン\n\n- Combine with `@Observable` ViewModels for UI binding / UIバインディング用に`@Observable` ViewModelと組み合わせる\n- Use `Sendable` types for data crossing actor boundaries / actor境界を越えるデータには`Sendable`型を使用\n- Consider `FileBasedSyncManager` actor for cloud sync operations / クラウド同期操作には`FileBasedSyncManager` actorを検討\n"},"lastSynced":"2026-03-08T02:14:06.016Z","agentAnalysis":{"suitability":{"en":"Perfect for iOS/Swift Agents needing thread-safe data persistence with async/await capabilities.","zh":"非常适合需要线程安全数据持久性和异步/等待功能的iOS/Swift代理。","ja":"iOS/Swiftエージェントがスレッドセーフなデータ永続化とasync/await機能を必要とする場合に最適です。","ko":"iOS/Swift 에이전트가 스레드 세이프 데이터 지속성 및 async/await 기능을 필요로 할 때 적합합니다.","es":"Perfecto para agentes iOS/Swift que necesitan persistencia de datos segura en hilos con capacidades async/await.","fr":"Parfait pour les agents iOS/Swift nécessitant une persistence de données sécurisée dans les threads avec des capacités async/await.","de":"Perfekt für iOS/Swift-Agents, die threadsichere Datenspeicherung mit async/await-Fähigkeiten benötigen.","pt":"Perfeito para Agents iOS/Swift que necessitam de persistência de dados segura contra threads com capacidades async/await.","ru":"Идеально для агентов iOS/Swift, которым необходима потокобезопасная постоянная память с возможностями async/await.","ar":"مثالي لعميل iOS/Swift الذين يحتاجون إلى استمرارية البيانات آمنة للخيط مع القدرات async/await."},"recommendation":{"en":"Empowers agents to implement reliable data storage using Swift Actors, avoiding race conditions and ensuring seamless async/await integration with iOS/Swift apps, leveraging DispatchQueues and locks alternatives.","zh":"赋予代理实现可靠的数据存储功能，使用Swift Actors，避免竞争条件，确保与iOS/Swift应用程序的无缝async/await集成，利用DispatchQueues和锁定替代品。","ja":"Swift Actorsを使用して、エージェントが信頼性の高いデータストレージを実装し、レースコンディションを回避し、iOS/Swiftアプリとのシームレスなasync/await統合を確実にし、DispatchQueuesとロックの代替品を利用します。","ko":"에이전트가 스레드 세이프 데이터 지속성을 구현하고 경쟁 조건을 피하며 iOS/Swift 애플리케이션과 무결점 async/await 통합을 보장할 수 있도록 Swift Actors를 사용하여 DispatchQueues 및 잠금 대안을 활용합니다.","es":"Permite a los agentes implementar un almacenamiento de datos confiable utilizando Swift Actors, evitando condiciones de carrera y asegurando una integración fluida de async/await con aplicaciones iOS/Swift, aprovechando DispatchQueues y alternativas a bloqueos.","fr":"Permet aux agents de mettre en œuvre un stockage de données fiable en utilisant Swift Actors, en évitant les conditions de course et en assurant une intégration fluide de async/await avec des applications iOS/Swift, en exploitant DispatchQueues et des alternatives à des verrous.","de":"Ermöglicht es Agents, zuverlässigen Datenspeicher mithilfe von Swift Actors zu implementieren, Rennbedingungen zu vermeiden und eine nahtlose Integration von async/await mit iOS/Swift-Apps sicherzustellen, indem DispatchQueues und Alternativen zu Sperren genutzt werden.","pt":"Habilita os agentes a implementar armazenamento de dados confiáveis usando Swift Actors, evitando condições de corrida e garantindo integração perfeita async/await com aplicativos iOS/Swift, aproveitando DispatchQueues e alternativas de bloqueio.","ru":"Наделяет агентов возможностью реализовывать надежное хранение данных с помощью Swift Actors, избегая гонок и обеспечивая бесшовную интеграцию async/await с приложениями iOS/Swift, используя DispatchQueues и альтернативы блокировок.","ar":"تمكين الوكيل من تنفيذ تخزين البيانات الموثوق به باستخدام Swift Actors ، وتجنب ظروف السباق وضمان دمج async/await السلس مع تطبيقات iOS/Swift ، واستخدام DispatchQueues وبدائل القفل."},"useCases":{"en":["Implementing thread-safe data persistence in iOS apps","Avoiding race conditions in concurrent data access scenarios","Ensuring reliable data storage with async/await in Swift"],"zh":["在iOS应用程序中实现线程安全的数据持久性","在并发数据访问场景中避免竞争条件","使用async/await在Swift中确保可靠的数据存储"],"ja":["iOSアプリケーションでスレッドセーフなデータ永続化を実装する","並行データアクセスのシナリオでレースコンディションを回避する","Swiftでasync/awaitを使用して信頼性の高いデータストレージを確実にする"],"ko":["iOS 애플리케이션에서 스레드 세이프 데이터 지속성을 구현하는 것","병렬 데이터 액세스 시나리오에서 경쟁 조건을 피하는 것","Swift에서 async/await를 사용하여 안정적인 데이터 저장을 보장하는 것"],"es":["Implementar persistencia de datos segura en hilos en aplicaciones iOS","Evitar condiciones de carrera en escenarios de acceso concurrente a datos","Asegurar un almacenamiento de datos confiable con async/await en Swift"],"fr":["Mettre en œuvre une persistence de données sécurisée dans les threads dans les applications iOS","Éviter les conditions de course dans les scénarios d''accès concurrent aux données","Assurer un stockage de données fiable avec async/await dans Swift"],"de":["Threadsichere Datenspeicherung in iOS-Apps implementieren","Rennbedingungen in Szenarien mit gleichzeitigen Datenzugriffen vermeiden","Zuverlässigen Datenspeicher mit async/await in Swift sicherstellen"],"pt":["Implementar persistência de dados segura contra threads em aplicativos iOS","Evitar condições de corrida em cenários de acesso a dados concorrentes","Garantir armazenamento de dados confiável com async/await em Swift"],"ru":["Реализация потокобезопасной постоянной памяти в приложениях iOS","Избежание гонок при параллельном доступе к данным","Обеспечение надежного хранения данных с async/await в Swift"],"ar":["تنفيذ استمرارية البيانات آمنة للخيط في تطبيقات iOS","تجنب ظروف السباق في سيناريوهات الوصول المتزامن إلى البيانات","ضمان تخزين البيانات الموثوق به مع async/await في Swift"]},"limitations":{"en":["Requires iOS/Swift development environment","Swift Actors support needed","Async/await compatibility necessary"],"zh":["需要iOS/Swift开发环境","需要Swift Actors支持","需要async/await兼容性"],"ja":["iOS/Swift開発環境が必要","Swift Actorsのサポートが必要","async/awaitの互換性が必要"],"ko":["iOS/Swift 개발 환경이 필요합니다.","Swift Actors 지원이 필요합니다.","async/await 호환성이 필요합니다."],"es":["Requiere entorno de desarrollo iOS/Swift","Se necesita soporte para Swift Actors","Compatibilidad con async/await necesaria"],"fr":["Nécessite un environnement de développement iOS/Swift","Prise en charge de Swift Actors nécessaire","Compatibilité avec async/await nécessaire"],"de":["Benötigt iOS/Swift-Entwicklungsumgebung","Swift Actors-Unterstützung erforderlich","Async/await-Kompatibilität erforderlich"],"pt":["Requer ambiente de desenvolvimento iOS/Swift","Suporte a Swift Actors necessário","Compatibilidade async/await necessária"],"ru":["Требуется среда разработки iOS/Swift","Необходима поддержка Swift Actors","Необходима совместимость async/await"],"ar":["يتطلب بيئة تطوير iOS/Swift","دعم Swift Actors ضروري","التوافق async/await ضروري"]},"version":4},"contentHash":"69c4c1a2a18b5caccb66715faf60c1882b1afdeee1262a9e4a5c5475eceb01e8","qualityScore":53}');
