INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ERP-CORE-DEV/eagles-claude-config/semantic-release', 'semantic-release', 'ERP-CORE-DEV', 'eagles-claude-config', 'community', 'semantic-release ERP-CORE-DEV eagles-claude-config community semantic-release AI智能工具是一种用于简化RH-OptimERP项目开发的工具，具有15个代理、35个技能、10个规则、5个钩子和6个MCP服务器 semantic-release AIエージェントは、RH-OptimERPプロジェクトの開発を簡素化するために使用されるツールです。15個のエージェント、35個のスキル、10個のルール、5個のフック、6個のMCPサーバーを備えています semantic-release AI 에이전트는 RH-OptimERP 프로젝트 개발을 간소화하기 위한 도구로, 15개의 에이전트, 35개의 스킬, 10개의 규칙, 5개의 후크 및 6개의 MCP 서버를 제공합니다 Semantic-release es una herramienta de AI que mejora la configuración de Claude Code para proyectos de desarrollo como RH-OptimERP Semantic-release est un outil d''IA qui améliore la configuration de Claude Code pour les projets de développement comme RH-OptimERP Semantic-release ist ein KI-Tool, das die Konfiguration von Claude Code für Entwicklungsvorhaben wie RH-OptimERP verbessert semantic-release é uma ferramenta de AI que automatiza lançamentos de software, permitindo que os desenvolvedores se concentrem em escrever código. semantic-release - это инструмент ИИ, который автоматизирует выпуски программного обеспечения, позволяя разработчикам сосредоточиться на написании кода. semantic-release هي أداة ذكاء اصطناعي تautomatiza إصدارات البرمجيات، مما يسمح للمطورين بالتركيز على كتابة الشفرة. EAGLES Team - Shared Claude Code configuration (15 agents, 35 skills, 10 rules, 5 hooks, 6 MCP servers) for RH-OptimERP project semantic-release 安装 如何使用 semantic-release semantic-release 教程 RH-OptimERP 项目开发 AI 智能工具 版本发布自动化 EAGLES Team - Shared Claude Code configuration (15 agents, 35 skills, 10 rules, 5 hooks, 6 MCP servers) for RH-OptimERP project');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Dillind/sprout-expo/native-data-fetching', 'community', 'Dillind', 'sprout-expo', 'Dillind/sprout-expo', 'native-data-fetching', 0, 0, 53, '2026-03-07T01:49:01.515Z', '2026-03-07T01:59:39.329Z', 'b4e72ed9215cac46f40a461e816acd634797512d97e39477925087eccc6220be', '{"id":"Dillind/sprout-expo/native-data-fetching","name":"native-data-fetching","description":{"en":"The native-data-fetching skill enables developers to handle networking tasks, including API requests and data fetching, for Expo apps. It supports React Query and SWR for efficient data management.","zh":"Native 数据抓取是一种用于 Expo 应用的数据抓取和缓存机制，支持 React Query 和 SWR","ja":"ネイティブデータフェッチングは、Expo アプリケーション用のデータフェッチングとキャッシングメカニズムであり、React Query と SWR をサポート","ko":"네이티브 데이터 패칭은 Expo 애플리케이션을 위한 데이터 패칭 및 캐싱 메커니즘으로, React Query 및 SWR를 지원","es":"Native-data-fetching es una habilidad para Expo que permite implementar solicitudes de API y fetching de datos de manera eficiente","fr":"Native-data-fetching est une compétence pour Expo qui permet de mettre en œuvre des requêtes API et un fetching de données de manière efficace","de":"Native-data-fetching ist eine Fähigkeit für Expo, die die Implementierung von API-Anfragen und Datenabruf auf effiziente Weise ermöglicht","pt":"O native-data-fetching é uma habilidade essencial para desenvolvedores que precisam fazer requisições de API e busca de dados de forma eficiente","ru":"native-data-fetching - это важнейший навык для разработчиков, которым необходимы запросы API и извлечение данных эффективно для ИИ Агентов","ar":"native-data-fetching هي مهارة أساسية للمطورين الذين يحتاجون إلى إجراء طلبات API وانتشال البيانات بفعالية لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"native-data-fetching: Expo Networking Setup Guide | AI Ag...","zh":"Native 数据抓取 Setup Guide - AIエージェント","ja":"ネイティブデータフェッチングのベストプラクティス - AIエージェント","ko":"네이티브 데이터 패칭 설정 가이드 - AI 에이전트","es":"Guía de configuración de native-data-fetching para Expo","fr":"Configurer le native-data-fetching pour les applications ...","de":"Native-Data-Fetching-Setup-Anleitung für Expo-Entwickler","pt":"Guia de Configuração do native-data-fetching para Desenvo...","ru":"Настройка native-data-fetching: Руководство для разработч...","ar":"دليل إعداد native-data-fetching للاستخدام مع أدوات الذكاء..."},"description":{"en":"Unlock efficient data fetching with native-data-fetching! Learn how to implement API requests, caching, and network debugging for your Expo app. Get started ...","zh":"了解 Native 数据抓取的使用场景、配置和调试方法，优化您的应用性能","ja":"ネイティブデータフェッチングの使用シーン、設定、デバッグ方法をマスターして、アプリケーションのパフォーマンスを最適化","ko":"네이티브 데이터 패칭의 사용 사례, 설정 및 디버깅 방법을 익히고, 애플리케이션의 성능을 최적화","es":"Aprende a implementar solicitudes de API, fetching de datos y estrategias de caché con native-data-fetching en Expo","fr":"Découvrez comment mettre en œuvre des requêtes API, un fetching de données et des stratégies de cache avec native-data-fetching sur Expo","de":"Erfahren Sie, wie Sie API-Anfragen, Datenabruf und Cachestrategien mit native-data-fetching in Expo umsetzen","pt":"Aprenda a usar o native-data-fetching para fazer requisições de API, busca de dados e depuração de rede com React Query e SWR","ru":"Узнайте, как использовать native-data-fetching для запросов API, извлечения данных и отладки сети с React Query и SWR для ИИ Агентов","ar":"تعرف على كيفية استخدام native-data-fetching لإجراء طلبات API وانتشال البيانات وتصحيح الأخطاء الشبكية مع React Query و SWR لأدوات الذكاء الاصطناعي"},"definition":{"en":"native-data-fetching is a skill for handling Expo app networking tasks, including API requests, data fetching, caching, and network debugging.","zh":"Native 数据抓取是一种用于抓取和缓存数据的机制，用于 Expo 应用","ja":"ネイティブデータフェッチングは、データをフェッチしてキャッシュするメカニズムであり、Expo アプリケーションで使用","ko":"네이티브 데이터 패칭은 데이터를 패칭하고 캐싱하는 메커니즘으로, Expo 애플리케이션에서 사용","es":"Native-data-fetching es una habilidad que permite a los desarrolladores de Expo implementar solicitudes de API y fetching de datos de manera nativa","fr":"Native-data-fetching est une compétence qui permet aux développeurs Expo de mettre en œuvre des requêtes API et un fetching de données de manière native","de":"Native-data-fetching ist eine Fähigkeit, die es Entwicklern von Expo ermöglicht, API-Anfragen und Datenabruf auf native Weise umzusetzen","pt":"O que é native-data-fetching? É uma habilidade que permite fazer requisições de API e busca de dados de forma nativa","ru":"Что такое native-data-fetching? Это навык, который позволяет делать запросы API и извлечение данных в родной форме для ИИ Агентов","ar":"ما هي native-data-fetching؟ هي مهارة تتيح إجراء طلبات API وانتشال البيانات بالشكل الأصلي لأدوات الذكاء الاصطناعي"},"features":{"en":["Implements API requests using expo/fetch","Supports data fetching with React Query and SWR","Enables network debugging and caching strategies","Handles offline scenarios and authentication/token management","Configures API URLs and environment variables"],"zh":["支持 React Query 和 SWR","实现 API 请求和数据抓取","支持缓存策略和离线场景","支持身份验证和令牌管理","配置 API URL 和环境变量"],"ja":["React Query と SWR をサポート","API リクエストとデータフェッチングの実装","キャッシング戦略とオフラインシナリオのサポート","認証とトークン管理のサポート","API URL と環境変数の設定"],"ko":["React Query 및 SWR 지원","API 요청 및 데이터 패칭 구현","캐싱 전략 및 오프라인 시나리오 지원","인증 및 토큰 관리 지원","API URL 및 환경 변수 설정"],"es":["Implementación de solicitudes de API con Expo","Fetching de datos con React Query y SWR","Depuración de fallos de red","Implementación de estrategias de caché","Gestión de autenticación y tokens","Configuración de URLs de API y variables de entorno"],"fr":["Mise en œuvre de requêtes API avec Expo","Fetching de données avec React Query et SWR","Débogage des échecs de réseau","Mise en œuvre de stratégies de cache","Gestion de l''authentification et des jetons","Configuration des URL d''API et des variables d''environnement"],"de":["Implementierung von API-Anfragen mit Expo","Datenabruf mit React Query und SWR","Fehlerbehebung bei Netzwerkfehlern","Implementierung von Cachestrategien","Authentifizierungs- und Tokenverwaltung","Konfiguration von API-URLs und Umgebungsvariablen"],"pt":["Implementação de requisições de API com React Query","Configuração de busca de dados com SWR","Depuração de falhas de rede","Implementação de estratégias de cache","Gerenciamento de autenticação e tokens"],"ru":["Реализация запросов API с React Query для ИИ Агентов","Настройка извлечения данных с SWR","Отладка сетевых неисправностей","Реализация стратегий кэширования","Управление аутентификацией и токенами"],"ar":["تنفيذ طلبات API مع React Query","تكوين انتشال البيانات مع SWR","تصحيح الأخطاء الشبكية","تنفيذ استراتيجيات التخزين المؤقت","إدارة المصادقة والأشكال"]},"keywords":{"en":["how to use native-data-fetching","native-data-fetching vs axios","native-data-fetching setup guide","expo networking tutorial","react query data fetching","native-data-fetching install","what is native-data-fetching","native-data-fetching alternative","native-data-fetching expo"],"zh":["Native 数据抓取","Expo 应用","React Query","SWR","数据抓取","缓存策略","API 请求","身份验证","AIエージェント"],"ja":["ネイティブデータフェッチング","Expo アプリケーション","React Query","SWR","データフェッチング","キャッシング戦略","API リクエスト","認証","AIエージェント"],"ko":["네이티브 데이터 패칭","Expo 애플리케이션","React Query","SWR","데이터 패칭","캐싱 전략","API 요청","인증","AI 에이전트"],"es":["native-data-fetching","Expo","solicitudes de API","fetching de datos","React Query","SWR","caché","autenticación","tokens","variables de entorno"],"fr":["native-data-fetching","Expo","requêtes API","fetching de données","React Query","SWR","cache","authentification","jetons","variables d''environnement"],"de":["native-data-fetching","Expo","API-Anfragen","Datenabruf","React Query","SWR","Cachestrategien","Authentifizierung","Tokenverwaltung","Umgebungsvariablen"],"pt":["native-data-fetching","react query","SWR","requisições de API","busca de dados","depuração de rede","cache","autenticação","tokens"],"ru":["native-data-fetching","react query","SWR","запросы API","извлечение данных","отладка сети","кэш","аутентификация","токены","ИИ Агенты"],"ar":["native-data-fetching","react query","SWR","طلبات API","انتشال البيانات","تصحيح الأخطاء الشبكية","التخزين المؤقت","المصادقة","الأشكال","أدوات الذكاء الاصطناعي"]}},"owner":"Dillind","repo":"sprout-expo","repoPath":"Dillind/sprout-expo","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.515Z","topics":[],"category":"community","skillMd":{"name":"native-data-fetching","description":"Use when implementing or debugging ANY network request, API call, or data fetching. Covers fetch API, axios, React Query, SWR, error handling, caching strategies, offline support.","version":"1.0.0","bodyPreview":"# Expo Networking\n\n**You MUST use this skill for ANY networking work including API requests, data fetching, caching, or network debugging.**\n\n## When to Use\n\nUse this router when:\n\n- Implementing API requests\n- Setting up data fetching (React Query, SWR)\n- Debugging network failures\n- Implementing caching strategies\n- Handling offline scenarios\n- Authentication/token management\n- Configuring API URLs and environment variables\n\n## Preferences\n\n- Avoid axios, prefer expo/fetch\n\n## Common Issues &","body":"# Expo Networking\n\n**You MUST use this skill for ANY networking work including API requests, data fetching, caching, or network debugging.**\n\n## When to Use\n\nUse this router when:\n\n- Implementing API requests\n- Setting up data fetching (React Query, SWR)\n- Debugging network failures\n- Implementing caching strategies\n- Handling offline scenarios\n- Authentication/token management\n- Configuring API URLs and environment variables\n\n## Preferences\n\n- Avoid axios, prefer expo/fetch\n\n## Common Issues & Solutions\n\n### 1. Basic Fetch Usage\n\n**Simple GET request**:\n\n```tsx\nconst fetchUser = async (userId: string) => {\n  const response = await fetch(`https://api.example.com/users/${userId}`);\n\n  if (!response.ok) {\n    throw new Error(`HTTP error! status: ${response.status}`);\n  }\n\n  return response.json();\n};\n```\n\n**POST request with body**:\n\n```tsx\nconst createUser = async (userData: UserData) => {\n  const response = await fetch(\"https://api.example.com/users\", {\n    method: \"POST\",\n    headers: {\n      \"Content-Type\": \"application/json\",\n      Authorization: `Bearer ${token}`,\n    },\n    body: JSON.stringify(userData),\n  });\n\n  if (!response.ok) {\n    const error = await response.json();\n    throw new Error(error.message);\n  }\n\n  return response.json();\n};\n```\n\n---\n\n### 2. React Query (TanStack Query)\n\n**Setup**:\n\n```tsx\n// app/_layout.tsx\nimport { QueryClient, QueryClientProvider } from \"@tanstack/react-query\";\n\nconst queryClient = new QueryClient({\n  defaultOptions: {\n    queries: {\n      staleTime: 1000 * 60 * 5, // 5 minutes\n      retry: 2,\n    },\n  },\n});\n\nexport default function RootLayout() {\n  return (\n    <QueryClientProvider client={queryClient}>\n      <Stack />\n    </QueryClientProvider>\n  );\n}\n```\n\n**Fetching data**:\n\n```tsx\nimport { useQuery } from \"@tanstack/react-query\";\n\nfunction UserProfile({ userId }: { userId: string }) {\n  const { data, isLoading, error, refetch } = useQuery({\n    queryKey: [\"user\", userId],\n    queryFn: () => fetchUser(userId),\n  });\n\n  if (isLoading) return <Loading />;\n  if (error) return <Error message={error.message} />;\n\n  return <Profile user={data} />;\n}\n```\n\n**Mutations**:\n\n```tsx\nimport { useMutation, useQueryClient } from \"@tanstack/react-query\";\n\nfunction CreateUserForm() {\n  const queryClient = useQueryClient();\n\n  const mutation = useMutation({\n    mutationFn: createUser,\n    onSuccess: () => {\n      // Invalidate and refetch\n      queryClient.invalidateQueries({ queryKey: [\"users\"] });\n    },\n  });\n\n  const handleSubmit = (data: UserData) => {\n    mutation.mutate(data);\n  };\n\n  return <Form onSubmit={handleSubmit} isLoading={mutation.isPending} />;\n}\n```\n\n---\n\n### 3. Error Handling\n\n**Comprehensive error handling**:\n\n```tsx\nclass ApiError extends Error {\n  constructor(message: string, public status: number, public code?: string) {\n    super(message);\n    this.name = \"ApiError\";\n  }\n}\n\nconst fetchWithErrorHandling = async (url: string, options?: RequestInit) => {\n  try {\n    const response = await fetch(url, options);\n\n    if (!response.ok) {\n      const error = await response.json().catch(() => ({}));\n      throw new ApiError(\n        error.message || \"Request failed\",\n        response.status,\n        error.code\n      );\n    }\n\n    return response.json();\n  } catch (error) {\n    if (error instanceof ApiError) {\n      throw error;\n    }\n    // Network error (no internet, timeout, etc.)\n    throw new ApiError(\"Network error\", 0, \"NETWORK_ERROR\");\n  }\n};\n```\n\n**Retry logic**:\n\n```tsx\nconst fetchWithRetry = async (\n  url: string,\n  options?: RequestInit,\n  retries = 3\n) => {\n  for (let i = 0; i < retries; i++) {\n    try {\n      return await fetchWithErrorHandling(url, options);\n    } catch (error) {\n      if (i === retries - 1) throw error;\n      // Exponential backoff\n      await new Promise((r) => setTimeout(r, Math.pow(2, i) * 1000));\n    }\n  }\n};\n```\n\n---\n\n### 4. Authentication\n\n**Token management**:\n\n```tsx\nimport * as SecureStore from \"expo-secure-store\";\n\nconst TOKEN_KEY = \"auth_token\";\n\nexport const auth = {\n  getToken: () => SecureStore.getItemAsync(TOKEN_KEY),\n  setToken: (token: string) => SecureStore.setItemAsync(TOKEN_KEY, token),\n  removeToken: () => SecureStore.deleteItemAsync(TOKEN_KEY),\n};\n\n// Authenticated fetch wrapper\nconst authFetch = async (url: string, options: RequestInit = {}) => {\n  const token = await auth.getToken();\n\n  return fetch(url, {\n    ...options,\n    headers: {\n      ...options.headers,\n      Authorization: token ? `Bearer ${token}` : \"\",\n    },\n  });\n};\n```\n\n**Token refresh**:\n\n```tsx\nlet isRefreshing = false;\nlet refreshPromise: Promise<string> | null = null;\n\nconst getValidToken = async (): Promise<string> => {\n  const token = await auth.getToken();\n\n  if (!token || isTokenExpired(token)) {\n    if (!isRefreshing) {\n      isRefreshing = true;\n      refreshPromise = refreshToken().finally(() => {\n        isRefreshing = false;\n        refreshPromise = null;\n      });\n    }\n    return refreshPromise!;\n  }\n\n  return token;\n};\n```\n\n---\n\n### 5. Offline Support\n\n**Check network status**:\n\n```tsx\nimport NetInfo from \"@react-native-community/netinfo\";\n\n// Hook for network status\nfunction useNetworkStatus() {\n  const [isOnline, setIsOnline] = useState(true);\n\n  useEffect(() => {\n    return NetInfo.addEventListener((state) => {\n      setIsOnline(state.isConnected ?? true);\n    });\n  }, []);\n\n  return isOnline;\n}\n```\n\n**Offline-first with React Query**:\n\n```tsx\nimport { onlineManager } from \"@tanstack/react-query\";\nimport NetInfo from \"@react-native-community/netinfo\";\n\n// Sync React Query with network status\nonlineManager.setEventListener((setOnline) => {\n  return NetInfo.addEventListener((state) => {\n    setOnline(state.isConnected ?? true);\n  });\n});\n\n// Queries will pause when offline and resume when online\n```\n\n---\n\n### 6. Environment Variables\n\n**Using environment variables for API configuration**:\n\nExpo supports environment variables with the `EXPO_PUBLIC_` prefix. These are inlined at build time and available in your JavaScript code.\n\n```tsx\n// .env\nEXPO_PUBLIC_API_URL=https://api.example.com\nEXPO_PUBLIC_API_VERSION=v1\n\n// Usage in code\nconst API_URL = process.env.EXPO_PUBLIC_API_URL;\n\nconst fetchUsers = async () => {\n  const response = await fetch(`${API_URL}/users`);\n  return response.json();\n};\n```\n\n**Environment-specific configuration**:\n\n```tsx\n// .env.development\nEXPO_PUBLIC_API_URL=http://localhost:3000\n\n// .env.production\nEXPO_PUBLIC_API_URL=https://api.production.com\n```\n\n**Creating an API client with environment config**:\n\n```tsx\n// api/client.ts\nconst BASE_URL = process.env.EXPO_PUBLIC_API_URL;\n\nif (!BASE_URL) {\n  throw new Error(\"EXPO_PUBLIC_API_URL is not defined\");\n}\n\nexport const apiClient = {\n  get: async <T,>(path: string): Promise<T> => {\n    const response = await fetch(`${BASE_URL}${path}`);\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    return response.json();\n  },\n\n  post: async <T,>(path: string, body: unknown): Promise<T> => {\n    const response = await fetch(`${BASE_URL}${path}`, {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify(body),\n    });\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    return response.json();\n  },\n};\n```\n\n**Important notes**:\n\n- Only variables prefixed with `EXPO_PUBLIC_` are exposed to the client bundle\n- Never put secrets (API keys with write access, database passwords) in `EXPO_PUBLIC_` variables—they''re visible in the built app\n- Environment variables are inlined at **build time**, not runtime\n- Restart the dev server after changing `.env` files\n- For server-side secrets in API routes, use variables without the `EXPO_PUBLIC_` prefix\n\n**TypeScript support**:\n\n```tsx\n// types/env.d.ts\ndeclare global {\n  namespace NodeJS {\n    interface ProcessEnv {\n      EXPO_PUBLIC_API_URL: string;\n      EXPO_PUBLIC_API_VERSION?: string;\n    }\n  }\n}\n\nexport {};\n```\n\n---\n\n### 7. Request Cancellation\n\n**Cancel on unmount**:\n\n```tsx\nuseEffect(() => {\n  const controller = new AbortController();\n\n  fetch(url, { signal: controller.signal })\n    .then((response) => response.json())\n    .then(setData)\n    .catch((error) => {\n      if (error.name !== \"AbortError\") {\n        setError(error);\n      }\n    });\n\n  return () => controller.abort();\n}, [url]);\n```\n\n**With React Query** (automatic):\n\n```tsx\n// React Query automatically cancels requests when queries are invalidated\n// or components unmount\n```\n\n---\n\n## Decision Tree\n\n```\nUser asks about networking\n  |-- Basic fetch?\n  |   \\-- Use fetch API with error handling\n  |\n  |-- Need caching/state management?\n  |   |-- Complex app -> React Query (TanStack Query)\n  |   \\-- Simpler needs -> SWR or custom hooks\n  |\n  |-- Authentication?\n  |   |-- Token storage -> expo-secure-store\n  |   \\-- Token refresh -> Implement refresh flow\n  |\n  |-- Error handling?\n  |   |-- Network errors -> Check connectivity first\n  |   |-- HTTP errors -> Parse response, throw typed errors\n  |   \\-- Retries -> Exponential backoff\n  |\n  |-- Offline support?\n  |   |-- Check status -> NetInfo\n  |   \\-- Queue requests -> React Query persistence\n  |\n  |-- Environment/API config?\n  |   |-- Client-side URLs -> EXPO_PUBLIC_ prefix in .env\n  |   |-- Server secrets -> Non-prefixed env vars (API routes only)\n  |   \\-- Multiple environments -> .env.development, .env.production\n  |\n  \\-- Performance?\n      |-- Caching -> React Query with staleTime\n      |-- Deduplication -> React Query handles this\n      \\-- Cancellation -> AbortController or React Query\n```\n\n## Common Mistakes\n\n**Wrong: No error handling**\n\n```tsx\nconst data = await fetch(url).then((r) => r.json());\n```\n\n**Right: Check response status**\n\n```tsx\nconst response = await fetch(url);\nif (!response.ok) throw new Error(`HTTP ${response.status}`);\nconst data = await response.json();\n```\n\n**Wrong: Storing tokens in AsyncStorage**\n\n```tsx\nawait AsyncStorage.setItem(\"token\", token); // Not secure!\n```\n\n**Right: Use SecureStore for sensitive data**\n\n```tsx\nawait SecureStore.setItemAsync(\"token\", token);\n```\n\n## Example Invocations\n\nUser: \"How do I make API calls in React Native?\"\n-> Use fetch, wrap with error handling\n\nUser: \"Should I use React Query or SWR?\"\n-> React Query for complex apps, SWR for simpler needs\n\nUser: \"My app needs to work offline\"\n-> Use NetInfo for status, React Query persistence for caching\n\nUser: \"How do I handle authentication tokens?\"\n-> Store in expo-secure-store, implement refresh flow\n\nUser: \"API calls are slow\"\n-> Check caching strategy, use React Query staleTime\n\nUser: \"How do I configure different API URLs for dev and prod?\"\n-> Use EXPO*PUBLIC* env vars with .env.development and .env.production files\n\nUser: \"Where should I put my API key?\"\n-> Client-safe keys: EXPO*PUBLIC* in .env. Secret keys: non-prefixed env vars in API routes only\n"},"lastSynced":"2026-03-07T01:59:39.329Z","agentAnalysis":{"suitability":{"en":"Ideal for Mobile Agents requiring efficient data management for Expo apps, particularly those leveraging React Query and SWR for networking tasks.","zh":"适用于需要高效数据管理的移动代理，特别是那些利用 React Query 和 SWR 进行网络任务的 Expo 应用。","ja":"Expo アプリ、特に React Query と SWR を使用してネットワーク タスクを実行するための効率的なデータ管理が必要なモバイル エージェントに最適です。","ko":"효율적인 데이터 관리가 필요한 모바일 에이전트에 적합하며, 특히 React Query와 SWR을 사용하여 네트워킹 작업을 수행하는 Expo 애플리케이션에 적합합니다.","es":"Ideal para Agentes Móviles que requieren una gestión de datos eficiente para aplicaciones Expo, particularmente aquellos que aprovechan React Query y SWR para tareas de networking.","fr":"Idéal pour les agents mobiles nécessitant une gestion de données efficace pour les applications Expo, en particulier ceux qui utilisent React Query et SWR pour les tâches de networking.","de":"Ideal für Mobile Agenten, die eine effiziente Datenverwaltung für Expo-Apps benötigen, insbesondere für solche, die React Query und SWR für Networking-Aufgaben nutzen.","pt":"Ideal para agentes móveis que exigem gerenciamento de dados eficiente para aplicativos Expo, particularmente aqueles que utilizam React Query e SWR para tarefas de rede.","ru":"Идеально подходит для мобильных агентов, требующих эффективного управления данными для приложений Expo, особенно тех, которые используют React Query и SWR для сетевых задач.","ar":"مثالي لعمليات الوكيل المحمول التي تتطلب إدارة بيانات فعالة لتطبيقات Expo، ولا سيما تلك التي تستخدم React Query و SWR لمهام الشبكة."},"recommendation":{"en":"Empowers agents to handle API requests, data fetching, and caching using expo/fetch, while avoiding axios, and supports debugging network failures and implementing caching strategies with React Query and SWR.","zh":"赋予代理处理 API 请求、数据获取和缓存使用 expo/fetch 的能力，同时避免使用 axios，并支持使用 React Query 和 SWR 进行网络故障调试和缓存策略实现。","ja":"エージェントに、expo/fetch を使用して API リクエスト、データ取得、キャッシュを実行する能力を与え、axios の使用を避け、React Query と SWR を使用してネットワーク障害のデバッグとキャッシュ戦略の実装をサポートします。","ko":"에이전트가 expo/fetch를 사용하여 API 요청, 데이터 가져오기, 캐싱을 처리할 수 있도록 하며, axios를 피하고, React Query 및 SWR을 사용하여 네트워크 오류를 디버깅하고 캐싱 전략을 구현하는 것을 지원합니다.","es":"Habilita a los agentes a manejar solicitudes de API, recuperación de datos y almacenamiento en caché utilizando expo/fetch, evitando axios, y admite la depuración de fallos de red y la implementación de estrategias de almacenamiento en caché con React Query y SWR.","fr":"Permet aux agents de gérer les requêtes API, la récupération de données et la mise en cache en utilisant expo/fetch, tout en évitant axios, et prend en charge le débogage des défaillances réseau et la mise en œuvre de stratégies de mise en cache avec React Query et SWR.","de":"Ermächtigt die Agenten, API-Anfragen, Datenabruf und Caching mithilfe von expo/fetch zu verwalten, während axios vermieden wird, und unterstützt das Debuggen von Netzwerkfehlern und die Implementierung von Caching-Strategien mit React Query und SWR.","pt":"Habilita os agentes a lidar com solicitações de API, busca de dados e cache usando expo/fetch, evitando axios, e suporta depuração de falhas de rede e implementação de estratégias de cache com React Query e SWR.","ru":"Наделяет агентов возможностью обрабатывать запросы API, получать данные и кэшировать их с помощью expo/fetch, избегая axios, и поддерживает отладку сетевых сбоев и реализацию стратегий кэширования с помощью React Query и SWR.","ar":"يمنح الوكلاء القدرة على التعامل مع طلبات API و استرجاع البيانات و التخزين المؤقت باستخدام expo/fetch، وتجنب axios، ودعم تصحيح أخطاء الشبكة وتنفيذ استراتيجيات التخزين المؤقت مع React Query و SWR."},"useCases":{"en":["Implementing API requests with expo/fetch","Setting up efficient data fetching with React Query and SWR","Debugging network failures in Expo apps","Implementing caching strategies for offline scenarios"],"zh":["使用 expo/fetch 实现 API 请求","使用 React Query 和 SWR 设置高效的数据获取","在 Expo 应用中调试网络故障","实现离线场景的缓存策略"],"ja":["expo/fetch を使用して API リクエストを実装する","React Query と SWR を使用して効率的なデータ取得を設定する","Expo アプリのネットワーク障害をデバッグする","オフライン シナリオのキャッシュ戦略を実装する"],"ko":["expo/fetch를 사용하여 API 요청 구현","React Query 및 SWR을 사용하여 효율적인 데이터 가져오기 설정","Expo 애플리케이션의 네트워크 오류 디버깅","오프라인 시나리오의 캐싱 전략 구현"],"es":["Implementar solicitudes de API con expo/fetch","Configurar una recuperación de datos eficiente con React Query y SWR","Depurar fallos de red en aplicaciones Expo","Implementar estrategias de almacenamiento en caché para escenarios sin conexión"],"fr":["Mettre en œuvre des requêtes API avec expo/fetch","Configurer une récupération de données efficace avec React Query et SWR","Déboguer les défaillances réseau dans les applications Expo","Mettre en œuvre des stratégies de mise en cache pour les scénarios hors ligne"],"de":["Implementierung von API-Anfragen mit expo/fetch","Einrichtung einer effizienten Datenabruf mit React Query und SWR","Debuggen von Netzwerkfehlern in Expo-Apps","Implementierung von Caching-Strategien für Offline-Szenarien"],"pt":["Implementação de solicitações de API com expo/fetch","Configuração de busca de dados eficiente com React Query e SWR","Depuração de falhas de rede em aplicativos Expo","Implementação de estratégias de cache para cenários offline"],"ru":["Реализация запросов API с помощью expo/fetch","Настройка эффективной загрузки данных с помощью React Query и SWR","Отладка сетевых сбоев в приложениях Expo","Реализация стратегий кэширования для автономных сценариев"],"ar":["تنفيذ طلبات API باستخدام expo/fetch","تكوين استرجاع بيانات فعال باستخدام React Query و SWR","تصحيح أخطاء الشبكة في تطبيقات Expo","تنفيذ استراتيجيات التخزين المؤقت للسيناريوهات غير المتصل"]},"limitations":{"en":["Expo environment required","Avoid using axios, prefer expo/fetch"],"zh":["需要 Expo 环境","避免使用 axios，推荐使用 expo/fetch"],"ja":["Expo 環境が必要","axios の使用を避け、expo/fetch を使用することをお勧め"],"ko":["Expo 환경이 필요","axios 사용을 피하고, expo/fetch를 사용할 것"],"es":["Entorno Expo requerido","Evitar el uso de axios, preferir expo/fetch"],"fr":["Environnement Expo requis","Éviter d''utiliser axios, préférer expo/fetch"],"de":["Expo-Umgebung erforderlich","Vermeidung der Verwendung von axios, Vorzug für expo/fetch"],"pt":["Ambiente Expo necessário","Evite usar axios, prefira expo/fetch"],"ru":["Требуется окружение Expo","Избегайте использования axios, предпочитайте expo/fetch"],"ar":["بيئة Expo مطلوبة","تجنب استخدام axios، افضل استخدام expo/fetch"]},"version":4},"contentHash":"b4e72ed9215cac46f40a461e816acd634797512d97e39477925087eccc6220be","qualityScore":53}');
