INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Dillind/sprout-expo/native-data-fetching', 'native-data-fetching', 'Dillind', 'sprout-expo', 'community', 'native-data-fetching Dillind sprout-expo community The native-data-fetching skill enables developers to handle networking tasks, including API requests and data fetching, for Expo apps. It supports React Query and SWR for efficient data management. Native 数据抓取是一种用于 Expo 应用的数据抓取和缓存机制，支持 React Query 和 SWR ネイティブデータフェッチングは、Expo アプリケーション用のデータフェッチングとキャッシングメカニズムであり、React Query と SWR をサポート 네이티브 데이터 패칭은 Expo 애플리케이션을 위한 데이터 패칭 및 캐싱 메커니즘으로, React Query 및 SWR를 지원 Native-data-fetching es una habilidad para Expo que permite implementar solicitudes de API y fetching de datos de manera eficiente Native-data-fetching est une compétence pour Expo qui permet de mettre en œuvre des requêtes API et un fetching de données de manière efficace Native-data-fetching ist eine Fähigkeit für Expo, die die Implementierung von API-Anfragen und Datenabruf auf effiziente Weise ermöglicht O native-data-fetching é uma habilidade essencial para desenvolvedores que precisam fazer requisições de API e busca de dados de forma eficiente native-data-fetching - это важнейший навык для разработчиков, которым необходимы запросы API и извлечение данных эффективно для ИИ Агентов native-data-fetching هي مهارة أساسية للمطورين الذين يحتاجون إلى إجراء طلبات API وانتشال البيانات بفعالية لأدوات الذكاء الاصطناعي how to use native-data-fetching native-data-fetching vs axios native-data-fetching setup guide expo networking tutorial react query data fetching native-data-fetching install what is native-data-fetching native-data-fetching alternative native-data-fetching expo Native 数据抓取 Expo 应用 React Query SWR 数据抓取 缓存策略 API 请求 身份验证 AIエージェント Implements API requests using expo/fetch Supports data fetching with React Query and SWR Enables network debugging and caching strategies Handles offline scenarios and authentication/token management Configures API URLs and environment variables native-data-fetching is a skill for handling Expo app networking tasks, including API requests, data fetching, caching, and network debugging.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dannyhw/demo-design-system/native-data-fetching', 'community', 'dannyhw', 'demo-design-system', 'dannyhw/demo-design-system', 'native-data-fetching', 0, 0, 53, '2026-03-07T01:49:01.515Z', '2026-03-07T01:59:47.037Z', 'b4e72ed9215cac46f40a461e816acd634797512d97e39477925087eccc6220be', '{"id":"dannyhw/demo-design-system/native-data-fetching","name":"native-data-fetching","description":{"en":"The native-data-fetching skill enables developers to handle Expo networking tasks, including API requests, data fetching, and caching. It benefits developers working with React Query, SWR, and Expo.","zh":"Native 数据抓取是 Expo Networking 中用于处理 API 请求、数据抓取和缓存的技能","ja":"ネイティブデータフェッチングは、Expo Networking で API リクエスト、データフェッチ、キャッシュを処理するスキルです","ko":"네이티브 데이터 패칭은 Expo Networking에서 API 요청, 데이터 패칭, 캐싱을 처리하는 스킬입니다","es":"Native-data-fetching es una habilidad para Expo que permite realizar solicitudes de API, depuración de errores de red y estrategias de caché de manera eficiente.","fr":"Native-data-fetching est une compétence pour Expo qui permet d''exécuter des requêtes API, de déboguer les erreurs de réseau et de mettre en œuvre des stratégies de cache de manière efficace.","de":"Native-data-fetching ist eine Fähigkeit für Expo, die es ermöglicht, API-Anfragen, Netzwerksfehlerbehebung und Cachestrategien effizient durchzuführen.","pt":"O native-data-fetching é uma habilidade essencial para solicitações de API e fetch de dados em aplicativos móveis","ru":"Native-data-fetching - это необходимый навык для запросов API и извлечения данных в мобильных приложениях","ar":"أداة FETCH الأصلية هي مهارة أساسية لطلبات API و FETCH البيانات في التطبيقات المتنقلة"},"seo":{"title":{"en":"native-data-fetching: Expo Networking Setup Guide | AI Ag...","zh":"Native 数据抓取 Setup 指南","ja":"ネイティブデータフェッチングのベストプラクティス","ko":"네이티브 데이터 패칭 설정 가이드","es":"Guía de con