INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dannyhw/demo-design-system/native-data-fetching', 'native-data-fetching', 'dannyhw', 'demo-design-system', 'community', 'native-data-fetching dannyhw demo-design-system community The native-data-fetching skill enables developers to handle Expo networking tasks, including API requests, data fetching, and caching. It benefits developers working with React Query, SWR, and Expo. Native 数据抓取是 Expo Networking 中用于处理 API 请求、数据抓取和缓存的技能 ネイティブデータフェッチングは、Expo Networking で API リクエスト、データフェッチ、キャッシュを処理するスキルです 네이티브 데이터 패칭은 Expo Networking에서 API 요청, 데이터 패칭, 캐싱을 처리하는 스킬입니다 Native-data-fetching es una habilidad para Expo que permite realizar solicitudes de API, depuración de errores de red y estrategias de caché de manera eficiente. Native-data-fetching est une compétence pour Expo qui permet d''exécuter des requêtes API, de déboguer les erreurs de réseau et de mettre en œuvre des stratégies de cache de manière efficace. Native-data-fetching ist eine Fähigkeit für Expo, die es ermöglicht, API-Anfragen, Netzwerksfehlerbehebung und Cachestrategien effizient durchzuführen. O native-data-fetching é uma habilidade essencial para solicitações de API e fetch de dados em aplicativos móveis Native-data-fetching - это необходимый навык для запросов API и извлечения данных в мобильных приложениях أداة FETCH الأصلية هي مهارة أساسية لطلبات API و FETCH البيانات في التطبيقات المتنقلة how to use native-data-fetching native-data-fetching vs axios native-data-fetching install guide expo networking setup react query data fetching native-data-fetching alternative native-data-fetching setup guide expo fetch api requests native-data-fetching debugging Native 数据抓取 Expo Networking API 请求 数据抓取 缓存 React Query SWR 网络调试 AIエージェント Implements API requests using expo/fetch Sets up data fetching with React Query and SWR Handles offline scenarios and network debugging Implement caching strategies for optimized performance Manages authentication and token management for secure API interactions native-data-fetching is a skill that facilitates Expo networking, including API requests, data fetching, caching, and network debugging, using technologies like expo/fetch.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/sentry/setup-dev', 'community', 'getsentry', 'sentry', 'getsentry/sentry', 'setup-dev', 43241, 4615, 52, '2026-03-01T00:30:12Z', '2026-03-06T06:24:05.664Z', '16d70bdcb50f227d358a1fbdb503a020844223b1922040c0f1451b1d0cd075b5', '{"id":"getsentry/sentry/setup-dev","name":"setup-dev","description":{"en":"setup-dev provides developer-first error tracking and performance monitoring, ideal for devops and development teams. It enables local Sentry development environment setup.","zh":"setup-dev Skill 提供开发者错误跟踪和性能监控，使用 Sentry 和 Docker 实现高效的开发环境","ja":"setup-dev スキルは、開発者向けエラートラッキングとパフォーマンスモニタリングを提供し、Sentry と Docker で効率的な開発環境を実現します","ko":"setup-dev 스킬은 개발자용 오류 추적 및 성능 모니터링을 제공하며, Sentry 및 Docker로 효율적인 개발 환경을 구축합니다","es":"Configuración de entorno de desarrollo de Sentry para seguimiento de errores y monitoreo de rendimiento","fr":"Configuration de l''environnement de développement Sentry pour le suivi des erreurs et la surveillance des performances","de":"Einrichtung der Sentry-Entwicklungsumgebung für Fehlerverfolgung und Leistungsüberwachung","pt":"O setup-dev é uma ferramenta de rastreamento de erros e monitoramento de desempenho para desenvolvedores, com integração com Sentry e Django","ru":"Setup-dev - это инструмент для отслеживания ошибок и мониторинга производительности для разработчиков, с интеграцией с Sentry и Django","ar":"setup-dev هي أداة لتتبع الأخطاء ومراقبة الأداء للمطورين، مع دمج Sentry و Django"},"seo":{"title":{"en":"setup-dev: Local Development Setup Guide | AI Agent Skill","zh":"setup-dev 安装指南：开发者错误跟踪和性能监控","ja":"setup-dev セットアップガイド：開発者向けエラートラッキングとパフォーマンスモニタリング","ko":"setup-dev 설정 가이드: 개발자용 오류 추적 및 성능 모니터링","es":"Configuración de Entorno de Desarrollo de Sentry: Guía de...","fr":"Configurer l''Environnement de Développement Sentry: Meill...","de":"Sentry-Entwicklungsumgebung einrichten: Schritt-für-Schri...","pt":"Configuração de Desenvolvimento de setup-dev: Guia de Ins...","ru":"Настройка среды разработки setup-dev: Руководство по уста...","ar":"إعداد بيئة التطوير setup-dev: دليل التثبيت"},"description":{"en":"Get started with setup-dev, a developer-first error tracking and performance monitoring tool. Learn how to set up a local Sentry development environment in 3...","zh":"使用 setup-dev Skill 进行开发者错误跟踪和性能监控，利用 Sentry 和 Docker 实现高效的开发环境","ja":"setup-dev スキルを使用して開発者向けエラートラッキングとパフォーマンスモニタリングを行い、Sentry と Docker で効率的な開発環境を実現します","ko":"setup-dev 스킬을 사용하여 개발자용 오류 추적 및 성능 모니터링을 수행하고, Sentry 및 Docker로 효율적인 개발 환경을 구축합니다","es":"Aprende a configurar el entorno de desarrollo de Sentry en 30-45 minutos con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment configurer l''environnement de développement Sentry en 30-45 minutes avec notre guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie die Sentry-Entwicklungsumgebung in 30-45 Minuten mit unserer Schritt-für-Schritt-Anleitung für Entwickler einrichten","pt":"Aprenda a configurar o setup-dev para monitorar erros e desempenho com Sentry, Django e Python","ru":"Узнайте, как настроить setup-dev для отслеживания ошибок и производительности с помощью Sentry, Django и Python","ar":"تعلم كيفية إعداد setup-dev لمراقبة الأخطاء والأداء مع Sentry و Django و Python"},"definition":{"en":"setup-dev is a skill for setting up a local development environment for error tracking and performance monitoring using Sentry.","zh":"setup-dev 是一个开发者错误跟踪和性能监控的 AI 工具","ja":"setup-dev は、開発者向けエラートラッキングとパフォーマンスモニタリングの AI エージェントです","ko":"setup-dev는 개발자용 오류 추적 및 성능 모니터링의 AI 에이전트입니다","es":"Setup-dev es una herramienta de seguimiento de errores y monitoreo de rendimiento para desarrolladores","fr":"Setup-dev est un outil de suivi des erreurs et de surveillance des performances pour les développeurs","de":"Setup-dev ist ein Tool für die Fehlerverfolgung und Leistungsüberwachung für Entwickler","pt":"O setup-dev é uma ferramenta de desenvolvimento que fornece rastreamento de erros e monitoramento de desempenho","ru":"Setup-dev - это инструмент разработки, который обеспечивает отслеживание ошибок и мониторинг производительности","ar":"setup-dev هي أداة تطوير توفر تتبع الأخطاء ومراقبة الأداء"},"features":{"en":["Sets up a local Sentry development environment","Utilizes Docker images for efficient setup","Supports detailed troubleshooting with al_search_docs and al_read_doc","Compatible with Python and Django","Enables error logging and monitoring"],"zh":["使用 Sentry 进行错误跟踪和性能监控","支持 Docker 环境","提供详细的故障排除文档","支持 Python 和 Django 开发","集成 AL MCP 服务器进行高级故障排除"],"ja":["Sentry を使用したエラートラッキングとパフォーマンスモニタリング","Docker 環境のサポート","詳細なトラブルシューティング ドキュメントの提供","Python と Django 開発のサポート","AL MCP サーバーとの統合による高度なトラブルシューティング"],"ko":["Sentry를 사용한 오류 추적 및 성능 모니터링","Docker 환경 지원","상세한 문제 해결 문서 제공","Python 및 Django 개발 지원","AL MCP 서버와의 통합을 통한 고급 문제 해결"],"es":["Integración con Sentry para seguimiento de errores","Monitoreo de rendimiento con Django y Python","Compatibilidad con Docker para una configuración rápida","Acceso a documentación detallada con AL MCP","Soporte para hacktoberfest y fair-source"," Informes de errores y monitoreo de producción"],"fr":["Intégration avec Sentry pour le suivi des erreurs","Surveillance des performances avec Django et Python","Compatibilité avec Docker pour une configuration rapide","Accès à la documentation détaillée avec AL MCP","Support pour hacktoberfest et fair-source","Rapports d''erreurs et surveillance de production"],"de":["Integration mit Sentry für Fehlerverfolgung","Leistungsüberwachung mit Django und Python","Kompatibilität mit Docker für eine schnelle Konfiguration","Zugriff auf detaillierte Dokumentation mit AL MCP","Unterstützung für hacktoberfest und fair-source","Fehlerberichte und Produktionsüberwachung"],"pt":["Integração com Sentry para rastreamento de erros","Suporte a Django e Python","Monitoramento de desempenho com APM","Relatórios de crash e logs de erro","Integração com devinfra-mcp"],"ru":["Интеграция с Sentry для отслеживания ошибок","Поддержка Django и Python","Мониторинг производительности с APM","Отчеты о крахе и журналы ошибок","Интеграция с devinfra-mcp"],"ar":["دمج مع Sentry لتتبع الأخطاء","دعم Django و Python","مراقبة الأداء مع APM","تقارير الأعطال وسجلات الأخطاء","دمج مع devinfra-mcp"]},"keywords":{"en":["how to use setup-dev","setup-dev vs sentry","setup-dev install guide","what is setup-dev","setup-dev alternative","setup-dev setup tutorial","error tracking with setup-dev","performance monitoring using setup-dev"],"zh":["setup-dev","Sentry","Docker","错误跟踪","性能监控","开发者工具","AI 工具","Python","Django"],"ja":["setup-dev","Sentry","Docker","エラートラッキング","パフォーマンスモニタリング","開発者ツール","AI エージェント","Python","Django"],"ko":["setup-dev","Sentry","Docker","오류 추적","성능 모니터링","개발자 도구","AI 에이전트","Python","Django"],"es":["setup-dev","sentry","seguimiento de errores","monitoreo de rendimiento","django","python","docker","AL MCP","hacktoberfest","fair-source"],"fr":["setup-dev","sentry","suivi des erreurs","surveillance des performances","django","python","docker","AL MCP","hacktoberfest","fair-source"],"de":["setup-dev","sentry","fehlerverfolgung","leistungsüberwachung","django","python","docker","AL MCP","hacktoberfest","fair-source"],"pt":["setup-dev","Sentry","Django","Python","APM","rastreamento de erros","monitoramento de desempenho","devinfra-mcp","desenvolvimento de software"],"ru":["setup-dev","Sentry","Django","Python","APM","отслеживание ошибок","мониторинг производительности","devinfra-mcp","разработка программного обеспечения"],"ar":["setup-dev","Sentry","Django","Python","APM","تتبع الأخطاء","مراقبة الأداء","devinfra-mcp","تطوير البرمجيات"]}},"owner":"getsentry","repo":"sentry","repoPath":"getsentry/sentry","stars":43241,"forks":4615,"updatedAt":"2026-03-01T00:30:12Z","topics":["apm","crash-reporting","crash-reports","csp-report","devops","django","error-logging","error-monitoring","fair-source","hacktoberfest","monitor","monitoring","python","sentry","tag-production"],"category":"community","skillMd":{"name":"setup-dev","description":"Set up and manage the Sentry development environment using devenv. Handles fresh setup, updating existing environments, starting dev services, and troubleshooting. Use when asked to set up sentry, setup dev environment, get sentry running, start dev server, devenv setup, devservices not working, sentry wont start, or any development environment issue.","bodyPreview":"# Set Up Sentry Development Environment\n\nWalk the user through getting Sentry running locally. The full process from a bare machine takes **30-45 minutes** — most of that is downloading dependencies and Docker images. Set expectations clearly at each step.\n\n**AL MCP**: If the `al` MCP server is available, use `al_search_docs` and `al_read_doc` for detailed troubleshooting. The AL docs cover devenv, devservices, and common issues in depth. The AL server is part of the [devinfra-mcp](https://githu","body":"# Set Up Sentry Development Environment\n\nWalk the user through getting Sentry running locally. The full process from a bare machine takes **30-45 minutes** — most of that is downloading dependencies and Docker images. Set expectations clearly at each step.\n\n**AL MCP**: If the `al` MCP server is available, use `al_search_docs` and `al_read_doc` for detailed troubleshooting. The AL docs cover devenv, devservices, and common issues in depth. The AL server is part of the [devinfra-mcp](https://github.com/getsentry/devinfra-mcp) project — see that repo for setup instructions if the server isn''t configured yet. The SSE endpoint is configured in `.pi/mcp.json` (pi) or `.mcp.json` / `.cursor/mcp.json` (Claude Code / Cursor).\n\n## Step 1: Detect Current State\n\nBefore doing anything, assess what''s already installed. Run all of these:\n\n```bash\n# Check OS\nuname -s && uname -m\n\n# Check shell\necho $SHELL\n\n# Check if devenv exists\nwhich devenv 2>/dev/null || ls ~/.local/share/sentry-devenv/bin/devenv 2>/dev/null\n\n# Check devenv version (outdated versions cause failures)\ndevenv --version 2>/dev/null || ~/.local/share/sentry-devenv/bin/devenv --version 2>/dev/null\n\n# Check Docker runtime\ndocker context ls 2>/dev/null\ndocker info --format ''{{.Name}}'' 2>/dev/null\n\n# Check OrbStack\nwhich orbctl 2>/dev/null && orbctl status 2>/dev/null\n\n# Check Colima\nwhich colima 2>/dev/null && colima status 2>/dev/null\n\n# Check direnv\nwhich direnv 2>/dev/null\n\n# Check if repo is already set up\nls .venv/bin/sentry 2>/dev/null && ls node_modules/.bin 2>/dev/null\n```\n\nBased on results, skip to the appropriate step. If everything is installed, jump to Step 6.\n\n## Step 2: Install Prerequisites (macOS)\n\n### Xcode Command Line Tools\n\n```bash\nxcode-select -p 2>/dev/null || xcode-select --install\n```\n\nIf not installed, the user must complete the interactive install dialog (~10 min). Wait for it.\n\n### Homebrew\n\n```bash\nwhich brew || /bin/bash -c \"$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)\"\n```\n\n### Docker Runtime — OrbStack or Colima\n\nAsk the user which they prefer. Explain the tradeoffs:\n\n| Runtime      | Pros                                                   | Cons                                                     |\n| ------------ | ------------------------------------------------------ | -------------------------------------------------------- |\n| **Colima**   | Official Sentry recommendation, all scripts support it | Can have DNS issues on WiFi changes                      |\n| **OrbStack** | Faster, lower resource usage, better UI                | Some Sentry scripts assume Colima — may need workarounds |\n\n**If choosing OrbStack:**\n\n```bash\nbrew install --cask orbstack\n```\n\nThen start OrbStack from Applications. Verify: `docker info`\n\n**If choosing Colima:**\nColima gets installed by `devenv bootstrap` — no separate step needed.\n\n**Important**: Do NOT run Docker Desktop alongside either runtime — it causes conflicts.\n\n## Step 3: Install devenv\n\n```bash\n# For external (non-Sentry-employee) contributors:\n# export SENTRY_EXTERNAL_CONTRIBUTOR=1\n\ncurl -fsSL https://raw.githubusercontent.com/getsentry/devenv/main/install-devenv.sh | bash\n```\n\nThis installs to `~/.local/share/sentry-devenv/bin/devenv`.\n\n### Shell Configuration\n\nThe user''s shell MUST have devenv on PATH and direnv hooked in. Check and fix:\n\n```bash\n# Check if already configured\ngrep -q \"sentry-devenv\" ~/.zshrc 2>/dev/null || grep -q \"sentry-devenv\" ~/.bashrc 2>/dev/null\n```\n\nIf not configured, add to the appropriate shell config (`~/.zshrc` for zsh, `~/.bashrc` for bash):\n\n```bash\n# devenv\nexport PATH=\"$HOME/.local/share/sentry-devenv/bin:$PATH\"\n\n# direnv\neval \"$(direnv hook zsh)\"   # or: eval \"$(direnv hook bash)\"\n```\n\n**Tell the user to restart their terminal** (or `source ~/.zshrc`) after this change.\n\n### Verify devenv Version\n\nMinimum version changes frequently. If devenv is already installed, check it''s not outdated:\n\n```bash\ndevenv --version\n```\n\nIf the version is old (e.g., < 1.22), upgrade:\n\n```bash\ndevenv update\n```\n\nIf `devenv update` itself fails because the version is too old, reinstall:\n\n```bash\ncurl -fsSL https://raw.githubusercontent.com/getsentry/devenv/main/install-devenv.sh | bash\n```\n\n## Step 4: Bootstrap (First Time Only)\n\nFor a completely fresh setup, run bootstrap first:\n\n```bash\ndevenv bootstrap\n```\n\nThis is interactive (~5 min) — it prompts for SSH keys, coderoot directory, etc. It installs Homebrew, Colima, Docker CLI, and direnv.\n\n**After bootstrap completes, close and reopen the terminal.**\n\n## Step 5: Sync the Environment\n\nThis is the longest step. Tell the user:\n\n> **This will take 10-20 minutes** on first run. It installs Python, Node, all pip/npm dependencies, and runs database migrations. Subsequent syncs are much faster (2-5 min).\n\n### If direnv hangs\n\nThe `.envrc` runs Docker checks. If the Docker runtime isn''t running, direnv will hang. Symptoms:\n\n```\ndirenv: ([...]/direnv export zsh) is taking a while to execute. Use CTRL-C to give up.\n```\n\n**Fix**: Start the Docker runtime first:\n\n- OrbStack: Open OrbStack.app or `open -a OrbStack`\n- Colima: `devenv colima start`\n\nThen `direnv allow` again.\n\n### Chicken-and-Egg Problem\n\ndirenv checks node version and sentry installation. On a fresh setup, these don''t exist yet, so direnv will fail. This is normal. **Bypass direnv and run devenv sync directly:**\n\n```bash\n~/.local/share/sentry-devenv/bin/devenv sync\n```\n\nOr if devenv is on PATH:\n\n```bash\ndevenv sync\n```\n\nAfter sync completes, `direnv allow` should succeed.\n\n### If devenv sync fails\n\nCommon causes:\n\n1. **Outdated devenv** — `devenv update` or reinstall\n2. **Docker not running** — start OrbStack/Colima first\n3. **Network issues** — retry; some downloads are large\n\nRun `devenv doctor` for automated diagnosis.\n\n## Step 6: Start Services\n\n### First: Start Docker Images\n\n```bash\ndevservices up\n```\n\n**⏱️ First run: 5-10 minutes.** It pulls many Docker images (PostgreSQL, Redis, Kafka, ClickHouse, Snuba, Relay, etc.). This is a one-time cost. Tell the user:\n\n> This is downloading all the Docker images Sentry needs. It looks like a lot — that''s normal. Subsequent starts take ~30 seconds.\n\n**Subsequent runs: ~30 seconds.**\n\n### OrbStack Socket Issue\n\nIf `devservices up` or `devservices serve` fails with:\n\n```\nMake sure colima is running. Run `devenv colima start`.\n```\n\n...but the user is using OrbStack, the `devservices.py` command is checking for the Colima socket only. Check `src/sentry/runner/commands/devservices.py`:\n\n```bash\ngrep -n \"colima\\|docker.sock\\|orbstack\" src/sentry/runner/commands/devservices.py\n```\n\nThe `_find_docker_socket()` function needs to check multiple socket paths. On macOS it should try, in order:\n\n1. `~/.colima/default/docker.sock` (Colima)\n2. `~/.orbstack/run/docker.sock` (OrbStack)\n3. `/var/run/docker.sock` (Docker Desktop / default)\n\nIf only Colima is checked, patch it to support all runtimes. Read `${CLAUDE_SKILL_ROOT}/references/orbstack-fix.md` for the exact pattern.\n\n### Then: Seed the Database\n\nIf this is a first-time setup, the database needs seeding:\n\n```bash\n.venv/bin/sentry upgrade --noinput\n```\n\nThis runs all Django migrations AND creates default data (organizations, roles, projects). Without this, the dev server will 500 on every page.\n\n**Do NOT just run `sentry django migrate`** — that only runs migrations without seeding the required default data.\n\n### Create Superuser\n\n```bash\n.venv/bin/sentry createuser --superuser --email admin@sentry.io --password admin --no-input\n```\n\n## Step 7: Start the Dev Server\n\n```bash\ndevservices serve\n```\n\nOr directly:\n\n```bash\n.venv/bin/sentry devserver\n```\n\n### What to Expect on Startup\n\n**Kafka topic warnings are normal.** On first start, you''ll see many lines like:\n\n```\n[WARNING] sentry.batching-kafka-consumer: Topic ''taskworker'' or its partitions are not ready, retrying...\n```\n\nThese settle down after 30-60 seconds as Kafka auto-creates topics. Don''t panic.\n\n### Access the Dev Server\n\n- **URL**: http://dev.sentry.localhost:8000\n- **Login**: admin@sentry.io / admin\n\n### Required: Sentry Cookie Sync Extension\n\n**Without this extension, the UI shows a blank white screen.** Install it:\n\nhttps://chromewebstore.google.com/detail/sentry-cookie-sync/kchlmkcdfohlmobgojmipoppgpedhijh\n\nThis syncs auth cookies between sentry.io and dev.sentry.localhost. It''s not optional.\n\n## Day-to-Day Commands\n\nAfter initial setup, the daily workflow is:\n\n```bash\ncd ~/Projects/sentry    # (or wherever the repo lives)\ndevservices up           # start background services (~30s)\ndevservices serve        # start dev server\n# → http://dev.sentry.localhost:8000\n```\n\nAfter pulling new code:\n\n```bash\ndevenv sync              # update dependencies + migrations (2-5 min)\n```\n\n## Troubleshooting Decision Tree\n\n| Symptom                                         | Likely Cause                              | Fix                                                  |\n| ----------------------------------------------- | ----------------------------------------- | ---------------------------------------------------- |\n| direnv hangs                                    | Docker runtime not running                | Start OrbStack / Colima                              |\n| `devenv sync` fails with version error          | Outdated devenv                           | `devenv update` or reinstall                         |\n| `devservices up` says \"colima not running\"      | Using OrbStack, script only checks Colima | Patch `devservices.py` — see Step 6                  |\n| Server 500s on every page                       | DB not seeded                             | `.venv/bin/sentry upgrade --noinput`                 |\n| `relation \"sentry_organization\" does not exist` | Migrations not run                        | `.venv/bin/sentry upgrade --noinput`                 |\n| White/blank screen in browser                   | Cookie Sync extension missing             | Install the Chrome extension                         |\n| Kafka topic warnings on startup                 | Normal first-boot behavior                | Wait 30-60 seconds                                   |\n| Port already in use                             | Stale containers                          | `docker rm -f $(docker ps -aq)` then retry           |\n| Everything is broken                            | Nuclear option                            | `devservices purge && devenv sync && devservices up` |\n| DNS failures in Docker                          | Colima DNS stale                          | `devenv doctor` or `devenv colima restart`           |\n\nFor deeper troubleshooting, use the AL MCP if available ([devinfra-mcp](https://github.com/getsentry/devinfra-mcp)):\n\n```\nal_search_docs(query=\"<symptom keywords>\")\nal_read_doc(path=\"devenv/troubleshooting.md\", query=\"<specific issue>\")\n```\n"},"lastSynced":"2026-03-06T06:24:05.664Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring streamlined error tracking and performance monitoring with Sentry","zh":"适合需要简化错误跟踪和性能监控的DevOps Agents，使用Sentry","ja":"DevOpsエージェントがエラートラッキングとパフォーマンスモニタリングをストリームライン化するためにSentryを使用するのに適しています","ko":"에러 추적과 성능 모니터링을 간소화해야 하는 DevOps 에이전트에게 적합하며, Sentry를 사용합니다","es":"Ideal para agentes de DevOps que requieren un seguimiento de errores y monitoreo de rendimiento optimizado con Sentry","fr":"Idéal pour les agents DevOps nécessitant une surveillance des erreurs et un suivi des performances simplifiés avec Sentry","de":"Ideal für DevOps-Agenten, die eine optimierte Fehlerverfolgung und Leistungsüberwachung mit Sentry benötigen","pt":"Ideal para DevOps Agents que exigem rastreamento de erros e monitoramento de desempenho simplificados com Sentry","ru":"Идеально для DevOps-агентов, требующих упрощенного отслеживания ошибок и мониторинга производительности с помощью Sentry","ar":"مثالية للوكلاء DevOps الذين يتطلبون تتبعًا للأخطاء وبثًا لمراقبة الأداء مع Sentry"},"recommendation":{"en":"Empowers agents to set up a local Sentry development environment, leveraging Docker and dependencies for comprehensive monitoring, and utilizing protocols like al_search_docs and al_read_doc for detailed troubleshooting","zh":"赋予代理设置本地Sentry开发环境的能力，利用Docker和依赖项进行全面监控，并使用协议如al_search_docs和al_read_doc进行详细故障排除","ja":"エージェントがローカルのSentry開発環境をセットアップできるようにし、Dockerと依存関係を使用して包括的な監視を行い、al_search_docsやal_read_docなどのプロトコルを使用して詳細なトラブルシューティングを行う","ko":"에이전트가 로컬 Sentry 개발 환경을 설정할 수 있도록 하며, Docker와 종속성을 사용하여 포괄적인 모니터링을 수행하고, al_search_docs 및 al_read_doc와 같은 프로토콜을 사용하여详细한 문제 해결을 수행합니다","es":"Permite a los agentes configurar un entorno de desarrollo local de Sentry, aprovecha