INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dlt-hub/dlt/review-pr', 'community', 'dlt-hub', 'dlt', 'dlt-hub/dlt', 'review-pr', 4949, 458, 52, '2026-02-24T16:53:33Z', '2026-03-06T06:25:10.864Z', '4840da2d82e0aaad3006247d17cd0b78c8634e1a4a6d6fa9f3d11927c219260d', '{"id":"dlt-hub/dlt/review-pr","name":"review-pr","description":{"en":"The review-pr skill analyzes pull requests by parsing $ARGUMENTS to extract PR identifiers and optional reviewer instructions, benefiting data engineers and developers.","zh":"review-pr 是一个 Python 库，用于简化数据加载和分析过程。它支持 ELT 和数据仓库集成","ja":"review-pr は、データローディングと分析を簡素化する Python ライブラリです。ELT とデータウェアハウス統合をサポートしています","ko":"review-pr은 데이터 로딩과 분석을 단순화하는 Python 라이브러리입니다. ELT와 데이터 웨어하우스 통합을 지원합니다","es":"Review-pr es una herramienta de carga de datos que utiliza Python para analizar solicitudes de extracción y cargar datos de manera eficiente","fr":"Review-pr est un outil de chargement de données qui utilise Python pour analyser les demandes d''extraction et charger des données de manière efficace","de":"Review-pr ist ein Datenladetool, das Python verwendet, um Pull-Anfragen zu analysieren und Daten effizient zu laden","pt":"O Review-PR é uma ferramenta de análise de pull requests em Python que facilita a revisão e análise de código. Ele extrai o identificador da PR e instruções do revisor a partir da linha de comando","ru":"ИИ Агент Review-PR - это инструмент для анализа пулл-реквестов на Python, который упрощает процесс ревью и анализа кода. Он извлекает идентификатор пулл-реквеста и инструкции ревьюера из командной строки","ar":"أداة Review-PR هي أداة لتحليل الطلبات السحابية باستخدام Python التي تسهل عملية المراجعة والتحليل الشامل للكود. إنها تستخرج معرّف الطلب السحابي وتعليمات المراجع من سطر الأوامر"},"seo":{"title":{"en":"review-pr: PR Analysis Setup Guide | AI Agent Skill","zh":"review-pr Setup Guide: 使用 Python 进行数据加载和分析","ja":"re