INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dlt-hub/dlt/review-pr', 'review-pr', 'dlt-hub', 'dlt', 'community', 'review-pr dlt-hub dlt community data data-engineering data-lake data-loading data-warehouse elt extract load python transform The review-pr skill analyzes pull requests by parsing $ARGUMENTS to extract PR identifiers and optional reviewer instructions, benefiting data engineers and developers. review-pr 是一个 Python 库，用于简化数据加载和分析过程。它支持 ELT 和数据仓库集成 review-pr は、データローディングと分析を簡素化する Python ライブラリです。ELT とデータウェアハウス統合をサポートしています review-pr은 데이터 로딩과 분석을 단순화하는 Python 라이브러리입니다. ELT와 데이터 웨어하우스 통합을 지원합니다 Review-pr es una herramienta de carga de datos que utiliza Python para analizar solicitudes de extracción y cargar datos de manera eficiente Review-pr est un outil de chargement de données qui utilise Python pour analyser les demandes d''extraction et charger des données de manière efficace Review-pr ist ein Datenladetool, das Python verwendet, um Pull-Anfragen zu analysieren und Daten effizient zu laden O Review-PR é uma ferramenta de análise de pull requests em Python que facilita a revisão e análise de código. Ele extrai o identificador da PR e instruções do revisor a partir da linha de comando ИИ Агент Review-PR - это инструмент для анализа пулл-реквестов на Python, который упрощает процесс ревью и анализа кода. Он извлекает идентификатор пулл-реквеста и инструкции ревьюера из командной строки أداة Review-PR هي أداة لتحليل الطلبات السحابية باستخدام Python التي تسهل عملية المراجعة والتحليل الشامل للكود. إنها تستخرج معرّف الطلب السحابي وتعليمات المراجع من سطر الأوامر how to use review-pr review-pr alternative review-pr setup guide what is review-pr review-pr vs github review-pr install review-pr for data engineers review-pr for python developers review-pr data loading review-pr pull request analysis review-pr Python 数据加载 ELT 数据仓库 数据湖 数据分析 AI 代理 数据加载工具 Parses $ARGUMENTS to extract PR identifiers and reviewer instructions Analyzes pull requests using the extracted PR identifier (PR_ID) Supports optional reviewer instructions for additional context Gathers data in paragraphs for streamlined review Utilizes Python for efficient data loading and analysis review-pr is an AI agent skill that analyzes pull requests by parsing arguments and extracting identifiers for efficient data loading and review');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mrmps/SMRY/mobile-design', 'community', 'mrmps', 'SMRY', 'mrmps/SMRY', 'mobile-design', 1235, 93, 52, '2026-02-28T13:02:36Z', '2026-03-06T06:26:20.244Z', 'ec74cda5e1954572e4282c3aaa9c1c32ec743cef83c53f8aef622c00dc8f0682', '{"id":"mrmps/SMRY/mobile-design","name":"mobile-design","description":{"en":"The mobile-design skill provides a tool for summaries and paywall bypassing, benefiting developers with touch-first and battery-conscious design principles.","zh":"移动设计系统是一种Touch-first、Battery-conscious、Platform-respectful、Offline-capable的设计方法","ja":"モバイルデザインシステムは、タッチファースト、バッテリー意識、プラットフォーム尊重、オフライン可能な設計方法です","ko":"모바일 디자인 시스템은 터치 우선, 배터리 소모 최소화, 플랫폼尊重, 오프라인 가능性的 설계 방법입니다","es":"El sistema de diseño móvil es una herramienta para desarrolladores que permite crear interfaces de usuario móviles eficaces","fr":"Le système de conception mobile est un outil pour les développeurs qui permet de créer des interfaces utilisateur mobiles efficaces","de":"Das mobile Designsystem ist ein Tool für Entwickler, mit dem effektive mobile Benutzeroberflächen erstellt werden können","pt":"Nossa ferramenta de design móvel é baseada em filosofia de toque, economia de bateria e respeito à plataforma, permitindo a criação de experiências móveis otimizadas.","ru":"Наш инструмент мобильного дизайна основан на философии осязания, экономии батареи и уважении к платформе, что позволяет создавать мобильные trải nghiệm.","ar":"أداة تصميم الهاتف المحمول لدينا تقوم على فلسفة اللمس وتوفير البطارية والاحترام للمنصة، مما يسمح بإنشاء تجارب الهاتف المحمول المُحسَّنة."},"seo":{"title":{"en":"mobile-design: Touch-First Development Setup Guide | AI A...","zh":"移动设计系统搭建指南 - AIエージェント集成","ja":"モバイルデザインのベストプラクティス - AIエージェントの活用","ko":"모바일 디자인 시스템 구축 가이드 - AI 에이전트 통합","es":"Guía de configuración de diseño móvil para herramientas d...","fr":"Guide de configuration de conception mobile pour les outi...","de":"Einrichtungsleitfaden für mobiles Design für KI-Tools","pt":"Guia de Configuração de Design Móvel com Ferramentas de AI","ru":"Настройка Мобильного Дизайна с ИИ Агентами","ar":"دليل تصميم الهاتف المحمول مع أدوات الإي أيه آي"},"description":{"en":"Unlock mobile-first design with our AI agent skill, featuring touch-first philosophy and platform-respectful principles. Get started now!","zh":"了解移动设计系统的核心原则和最佳实践，利用AIエージェント提高移动应用的用户体验","ja":"モバイルデザインのためのTouch-firstアプローチとPlatform-respectfulな設計方法を学び、AIエージェントの力を活用してください","ko":"모바일 디자인 시스템의 핵심 원칙과 모바일 제약 조건을 고려한 설계 방법을 알아보고, AI 에이전트를 활용하여 모바일 애플리케이션의 사용자 경험을 향상시키세요","es":"Aprenda a implementar un sistema de diseño móvil eficaz con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment mettre en œuvre un système de conception mobile efficace avec notre guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie ein effektives mobiles Designsystem mit unserem Schritt-für-Schritt-Leitfaden für Entwickler implementieren","pt":"Aprenda a criar experiências móveis otimizadas com nossa ferramenta de design móvel e scripts de validação em Python","ru":"Создавайте мобильные trải nghiệm с нашей инструментом мобильного дизайна и скриптами проверки на Python","ar":"تعلم كيفية إنشاء تجارب الهاتف المحمول المُحسَّنة باستخدام أداة تصميم الهاتف المحمول و스크рип特ات التحقق بالبايثون"},"definition":{"en":"mobile-design is a touch-first, battery-conscious, and platform-respectful design system for mobile applications.","zh":"移动设计系统是一种专注于移动设备的设计方法，强调Touch-first和Platform-respectful的设计原则","ja":"モバイルデザインシステムは、モバイルデバイス向けの設計方法であり、タッチファーストとプラットフォーム尊重の設計原則を重視します","ko":"모바일 디자인 시스템은 모바일 장치에 최적화된 설계 방법으로, 터치 우선과 플랫폼尊重의 설계 원칙을 강조합니다","es":"Un sistema de diseño móvil es un conjunto de principios y patrones para crear interfaces de usuario móviles","fr":"Un système de conception mobile est un ensemble de principes et de modèles pour créer des interfaces utilisateur mobiles","de":"Ein mobiles Designsystem ist eine Sammlung von Prinzipien und Mustern zur Erstellung von mobilen Benutzeroberflächen","pt":"O design móvel é uma abordagem de criação de experiências móveis que considera as limitações e oportunidades da plataforma móvel.","ru":"Мобильный дизайн - это подход к созданию мобильных trải nghiệm, который учитывает ограничения и возможности мобильной платформы.","ar":"تصميم الهاتف المحمول هو نهج لإنشاء تجارب الهاتف المحمول التي تأخذ في الاعتبار القيود والفرص التي تقدمها منصة الهاتف المحمول."},"features":{"en":["Executes mobile UX and touch audits via scripts/mobile_audit.py","Validates mobile constraints and platform choice","Runs on Python with scripts/mobile_audit.py command","Supports offline-capable design","Respects platform differences with core principle implementation"],"zh":["Touch-first设计原则","Battery-conscious的设计方法","Platform-respectful的设计原则","Offline-capable的设计能力","Python脚本用于移动UX和Touch Audit"],"ja":["タッチファースト設計原則","バッテリー意識の設計方法","プラットフォーム尊重の設計原則","オフライン可能な設計能力","PythonスクリプトによるモバイルUXとタッチオーディット"],"ko":["터치 우선의 설계 원칙","배터리 소모 최소화의 설계 방법","플랫폼尊重의 설계 원칙","오프라인 가능性的 설계 능력","Python 스크립트를 통한 모바일 UX 및 터치 오디트"],"es":["Filosofía de diseño touch-first","Validación de la experiencia del usuario móvil con scripts de Python","Diseño de interfaces de usuario móviles con restricciones de plataforma","Capacidad de funcionamiento sin conexión","Ejecución de scripts de validación para garantizar la compatibilidad"],"fr":["Philosophie de conception touch-first","Validation de l''expérience utilisateur mobile avec des scripts Python","Conception d''interfaces utilisateur mobiles avec des contraintes de plateforme","Capacité de fonctionnement hors ligne","Exécution de scripts de validation pour garantir la compatibilité"],"de":["Touch-first-Designphilosophie","Validierung der mobilen Benutzeroberfläche mit Python-Skripten","Entwurf von mobilen Benutzeroberflächen mit Plattformbeschränkungen","Offline-Fähigkeit","Ausführung von Validierungsskripten zur Gewährleistung der Kompatibilität"],"pt":["Filosofia de toque e economia de bateria","Respeito à plataforma e capacidade offline","Scripts de validação em Python para auditoria de UX","Execução de scripts de validação para garantir a experiência móvel","Suporte à plataforma móvel com consideração de limitações","Integração com tecnologias de IA para melhorar a experiência do usuário"],"ru":["Философия осязания и экономии батареи","Уважение к платформе и возможность офлайн","Скрипты проверки на Python для аудита UX","Выполнение скриптов проверки для обеспечения мобильного trải nghiệm","Поддержка мобильной платформы с учетом ограничений","Интеграция с технологиями ИИ для улучшения trải nghiệm пользователя"],"ar":["فلسفة اللمس وتوفير البطارية","الاحترام للمنصة والقدرة على العمل بدون اتصال","سكрипتات التحقق بالبايثون لتدقيق واجهة المستخدم","تشغيل سكрипتات التحقق لضمان تجربة الهاتف المحمول","دعم منصة الهاتف المحمول مع مراعاة القيود","التكامل مع تكنولوجيا الإي أيه آي لتحسين تجربة المستخدم"]},"keywords":{"en":["how to use mobile-design","mobile-design setup guide","mobile-design vs responsive design","what is mobile-design","mobile-design install","mobile-design alternative","mobile-design philosophy","touch-first design principles","battery-conscious design"],"zh":["移动设计系统","AIエージェント","Touch-first设计","Battery-conscious设计","Platform-respectful设计","Offline-capable设计","Python脚本","移动UX","Touch Audit"],"ja":["モバイルデザインシステム","AIエージェント","タッチファースト設計","バッテリー意識の設計","プラットフォーム尊重の設計","オフライン可能な設計","Pythonスクリプト","モバイルUX","タッチオーディット"],"ko":["모바일 디자인 시스템","AI 에이전트","터치 우선의 설계","배터리 소모 최소화의 설계","플랫폼尊重의 설계","오프라인 가능性的 설계","Python 스크립트","모바일 UX","터치 오디트"],"es":["diseño móvil","sistema de diseño móvil","herramientas de AI para móviles","desarrollo de aplicaciones móviles","experiencia del usuario móvil","validación de la experiencia del usuario","scripts de Python para móviles"],"fr":["conception mobile","système de conception mobile","outils d''IA pour mobiles","développement d''applications mobiles","expérience utilisateur mobile","validation de l''expérience utilisateur","scripts Python pour mobiles"],"de":["mobiles Design","mobiles Designsystem","KI-Tools für mobile Geräte","Entwicklung von mobilen Anwendungen","mobile Benutzeroberfläche","Validierung der Benutzeroberfläche","Python-Skripte für mobile Geräte"],"pt":["design móvel","ferramentas de AI","experiências móveis","otimização de UX","Python para validação","desenvolvimento móvel","plataforma móvel","tecnologias de IA","auditoria de UX"],"ru":["мобильный дизайн","ИИ Агенты","мобильные trải nghiệm","оптимизация UX","Python для проверки","мобильное развитие","мобильная платформа","технологии ИИ","аудит UX"],"ar":["تصميم الهاتف المحمول","أدوات الإي أيه آي","تجارب الهاتف المحمول","تحسين واجهة المستخدم","البايثون للتحقق","تطوير الهاتف المحمول","منصة الهاتف المحمول","تكنولوجيا الإي أيه آي","تدقيق واجهة المستخدم"]}},"owner":"mrmps","repo":"SMRY","repoPath":"mrmps/SMRY","stars":1235,"forks":93,"updatedAt":"2026-02-28T13:02:36Z","topics":["ai","next13","openai"],"category":"community","skillMd":{"name":"mobile-design","description":"Mobile-first design thinking and decision-making for iOS and Android apps. Touch interaction, performance patterns, platform conventions. Teaches principles, not fixed values. Use when building React Native, Flutter, or native mobile apps.","bodyPreview":"# Mobile Design System\n\n> **Philosophy:** Touch-first. Battery-conscious. Platform-respectful. Offline-capable.\n> **Core Principle:** Mobile is NOT a small desktop. THINK mobile constraints, ASK platform choice.\n\n---\n\n## 🔧 Runtime Scripts\n\n**Execute these for validation (don''t read, just run):**\n\n| Script | Purpose | Usage |\n|--------|---------|-------|\n| `scripts/mobile_audit.py` | Mobile UX & Touch Audit | `python scripts/mobile_audit.py <project_path>` |\n\n---\n\n## 🔴 MANDATORY: Read Reference","body":"# Mobile Design System\n\n> **Philosophy:** Touch-first. Battery-conscious. Platform-respectful. Offline-capable.\n> **Core Principle:** Mobile is NOT a small desktop. THINK mobile constraints, ASK platform choice.\n\n---\n\n## 🔧 Runtime Scripts\n\n**Execute these for validation (don''t read, just run):**\n\n| Script | Purpose | Usage |\n|--------|---------|-------|\n| `scripts/mobile_audit.py` | Mobile UX & Touch Audit | `python scripts/mobile_audit.py <project_path>` |\n\n---\n\n## 🔴 MANDATORY: Read Reference Files Before Working!\n\n**⛔ DO NOT start development until you read the relevant files:**\n\n### Universal (Always Read)\n\n| File | Content | Status |\n|------|---------|--------|\n| **[mobile-design-thinking.md](mobile-design-thinking.md)** | **⚠️ ANTI-MEMORIZATION: Forces thinking, prevents AI defaults** | **⬜ CRITICAL FIRST** |\n| **[touch-psychology.md](touch-psychology.md)** | **Fitts'' Law, gestures, haptics, thumb zone** | **⬜ CRITICAL** |\n| **[mobile-performance.md](mobile-performance.md)** | **RN/Flutter performance, 60fps, memory** | **⬜ CRITICAL** |\n| **[mobile-backend.md](mobile-backend.md)** | **Push notifications, offline sync, mobile API** | **⬜ CRITICAL** |\n| **[mobile-testing.md](mobile-testing.md)** | **Testing pyramid, E2E, platform-specific** | **⬜ CRITICAL** |\n| **[mobile-debugging.md](mobile-debugging.md)** | **Native vs JS debugging, Flipper, Logcat** | **⬜ CRITICAL** |\n| [mobile-navigation.md](mobile-navigation.md) | Tab/Stack/Drawer, deep linking | ⬜ Read |\n| [mobile-typography.md](mobile-typography.md) | System fonts, Dynamic Type, a11y | ⬜ Read |\n| [mobile-color-system.md](mobile-color-system.md) | OLED, dark mode, battery-aware | ⬜ Read |\n| [decision-trees.md](decision-trees.md) | Framework/state/storage selection | ⬜ Read |\n\n> 🧠 **mobile-design-thinking.md is PRIORITY!** This file ensures AI thinks instead of using memorized patterns.\n\n### Platform-Specific (Read Based on Target)\n\n| Platform | File | Content | When to Read |\n|----------|------|---------|--------------|\n| **iOS** | [platform-ios.md](platform-ios.md) | Human Interface Guidelines, SF Pro, SwiftUI patterns | Building for iPhone/iPad |\n| **Android** | [platform-android.md](platform-android.md) | Material Design 3, Roboto, Compose patterns | Building for Android |\n| **Cross-Platform** | Both above | Platform divergence points | React Native / Flutter |\n\n> 🔴 **If building for iOS → Read platform-ios.md FIRST!**\n> 🔴 **If building for Android → Read platform-android.md FIRST!**\n> 🔴 **If cross-platform → Read BOTH and apply conditional platform logic!**\n\n---\n\n## ⚠️ CRITICAL: ASK BEFORE ASSUMING (MANDATORY)\n\n> **STOP! If the user''s request is open-ended, DO NOT default to your favorites.**\n\n### You MUST Ask If Not Specified:\n\n| Aspect | Ask | Why |\n|--------|-----|-----|\n| **Platform** | \"iOS, Android, or both?\" | Affects EVERY design decision |\n| **Framework** | \"React Native, Flutter, or native?\" | Determines patterns and tools |\n| **Navigation** | \"Tab bar, drawer, or stack-based?\" | Core UX decision |\n| **State** | \"What state management? (Zustand/Redux/Riverpod/BLoC?)\" | Architecture foundation |\n| **Offline** | \"Does this need to work offline?\" | Affects data strategy |\n| **Target devices** | \"Phone only, or tablet support?\" | Layout complexity |\n\n### ⛔ AI MOBILE ANTI-PATTERNS (YASAK LİSTESİ)\n\n> 🚫 **These are AI default tendencies that MUST be avoided!**\n\n#### Performance Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **ScrollView for long lists** | Renders ALL items, memory explodes | Use `FlatList` / `FlashList` / `ListView.builder` |\n| **Inline renderItem function** | New function every render, all items re-render | `useCallback` + `React.memo` |\n| **Missing keyExtractor** | Index-based keys cause bugs on reorder | Unique, stable ID from data |\n| **Skip getItemLayout** | Async layout = janky scroll | Provide when items have fixed height |\n| **setState() everywhere** | Unnecessary widget rebuilds | Targeted state, `const` constructors |\n| **Native driver: false** | Animations blocked by JS thread | `useNativeDriver: true` always |\n| **console.log in production** | Blocks JS thread severely | Remove before release build |\n| **Skip React.memo/const** | Every item re-renders on any change | Memoize list items ALWAYS |\n\n#### Touch/UX Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **Touch target < 44px** | Impossible to tap accurately, frustrating | Minimum 44pt (iOS) / 48dp (Android) |\n| **Spacing < 8px between targets** | Accidental taps on neighbors | Minimum 8-12px gap |\n| **Gesture-only interactions** | Motor impaired users excluded | Always provide button alternative |\n| **No loading state** | User thinks app crashed | ALWAYS show loading feedback |\n| **No error state** | User stuck, no recovery path | Show error with retry option |\n| **No offline handling** | Crash/block when network lost | Graceful degradation, cached data |\n| **Ignore platform conventions** | Users confused, muscle memory broken | iOS feels iOS, Android feels Android |\n\n#### Security Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **Token in AsyncStorage** | Easily accessible, stolen on rooted device | `SecureStore` / `Keychain` / `EncryptedSharedPreferences` |\n| **Hardcode API keys** | Reverse engineered from APK/IPA | Environment variables, secure storage |\n| **Skip SSL pinning** | MITM attacks possible | Pin certificates in production |\n| **Log sensitive data** | Logs can be extracted | Never log tokens, passwords, PII |\n\n#### Architecture Sins\n\n| ❌ NEVER DO | Why It''s Wrong | ✅ ALWAYS DO |\n|-------------|----------------|--------------|\n| **Business logic in UI** | Untestable, unmaintainable | Service layer separation |\n| **Global state for everything** | Unnecessary re-renders, complexity | Local state default, lift when needed |\n| **Deep linking as afterthought** | Notifications, shares broken | Plan deep links from day one |\n| **Skip dispose/cleanup** | Memory leaks, zombie listeners | Clean up subscriptions, timers |\n\n---\n\n## 📱 Platform Decision Matrix\n\n### When to Unify vs Diverge\n\n```\n                    UNIFY (same on both)          DIVERGE (platform-specific)\n                    ───────────────────           ──────────────────────────\nBusiness Logic      ✅ Always                     -\nData Layer          ✅ Always                     -\nCore Features       ✅ Always                     -\n                    \nNavigation          -                             ✅ iOS: edge swipe, Android: back button\nGestures            -                             ✅ Platform-native feel\nIcons               -                             ✅ SF Symbols vs Material Icons\nDate Pickers        -                             ✅ Native pickers feel right\nModals/Sheets       -                             ✅ iOS: bottom sheet vs Android: dialog\nTypography          -                             ✅ SF Pro vs Roboto (or custom)\nError Dialogs       -                             ✅ Platform conventions for alerts\n```\n\n### Quick Reference: Platform Defaults\n\n| Element | iOS | Android |\n|---------|-----|---------|\n| **Primary Font** | SF Pro / SF Compact | Roboto |\n| **Min Touch Target** | 44pt × 44pt | 48dp × 48dp |\n| **Back Navigation** | Edge swipe left | System back button/gesture |\n| **Bottom Tab Icons** | SF Symbols | Material Symbols |\n| **Action Sheet** | UIActionSheet from bottom | Bottom Sheet / Dialog |\n| **Progress** | Spinner | Linear progress (Material) |\n| **Pull to Refresh** | Native UIRefreshControl | SwipeRefreshLayout |\n\n---\n\n## 🧠 Mobile UX Psychology (Quick Reference)\n\n### Fitts'' Law for Touch\n\n```\nDesktop: Cursor is precise (1px)\nMobile:  Finger is imprecise (~7mm contact area)\n\n→ Touch targets MUST be 44-48px minimum\n→ Important actions in THUMB ZONE (bottom of screen)\n→ Destructive actions AWAY from easy reach\n```\n\n### Thumb Zone (One-Handed Usage)\n\n```\n┌─────────────────────────────┐\n│      HARD TO REACH          │ ← Navigation, menu, back\n│        (stretch)            │\n├─────────────────────────────┤\n│      OK TO REACH            │ ← Secondary actions\n│       (natural)             │\n├─────────────────────────────┤\n│      EASY TO REACH          │ ← PRIMARY CTAs, tab bar\n│    (thumb''s natural arc)    │ ← Main content interaction\n└─────────────────────────────┘\n        [  HOME  ]\n```\n\n### Mobile-Specific Cognitive Load\n\n| Desktop | Mobile Difference |\n|---------|-------------------|\n| Multiple windows | ONE task at a time |\n| Keyboard shortcuts | Touch gestures |\n| Hover states | NO hover (tap or nothing) |\n| Large viewport | Limited space, scroll vertical |\n| Stable attention | Interrupted constantly |\n\nFor deep dive: [touch-psychology.md](touch-psychology.md)\n\n---\n\n## ⚡ Performance Principles (Quick Reference)\n\n### React Native Critical Rules\n\n```typescript\n// ✅ CORRECT: Memoized renderItem + React.memo wrapper\nconst ListItem = React.memo(({ item }: { item: Item }) => (\n  <View style={styles.item}>\n    <Text>{item.title}</Text>\n  </View>\n));\n\nconst renderItem = useCallback(\n  ({ item }: { item: Item }) => <ListItem item={item} />,\n  []\n);\n\n// ✅ CORRECT: FlatList with all optimizations\n<FlatList\n  data={items}\n  renderItem={renderItem}\n  keyExtractor={(item) => item.id}  // Stable ID, NOT index\n  getItemLayout={(data, index) => ({\n    length: ITEM_HEIGHT,\n    offset: ITEM_HEIGHT * index,\n    index,\n  })}\n  removeClippedSubviews={true}\n  maxToRenderPerBatch={10}\n  windowSize={5}\n/>\n```\n\n### Flutter Critical Rules\n\n```dart\n// ✅ CORRECT: const constructors prevent rebuilds\nclass MyWidget extends StatelessWidget {\n  const MyWidget({super.key}); // CONST!\n\n  @override\n  Widget build(BuildContext context) {\n    return const Column( // CONST!\n      children: [\n        Text(''Static content''),\n        MyConstantWidget(),\n      ],\n    );\n  }\n}\n\n// ✅ CORRECT: Targeted state with ValueListenableBuilder\nValueListenableBuilder<int>(\n  valueListenable: counter,\n  builder: (context, value, child) => Text(''$value''),\n  child: const ExpensiveWidget(), // Won''t rebuild!\n)\n```\n\n### Animation Performance\n\n```\nGPU-accelerated (FAST):     CPU-bound (SLOW):\n├── transform               ├── width, height\n├── opacity                 ├── top, left, right, bottom\n└── (use these ONLY)        ├── margin, padding\n                            └── (AVOID animating these)\n```\n\nFor complete guide: [mobile-performance.md](mobile-performance.md)\n\n---\n\n## 📝 CHECKPOINT (MANDATORY Before Any Mobile Work)\n\n> **Before writing ANY mobile code, you MUST complete this checkpoint:**\n\n```\n🧠 CHECKPOINT:\n\nPlatform:   [ iOS / Android / Both ]\nFramework:  [ React Native / Flutter / SwiftUI / Kotlin ]\nFiles Read: [ List the skill files you''ve read ]\n\n3 Principles I Will Apply:\n1. _______________\n2. _______________\n3. _______________\n\nAnti-Patterns I Will Avoid:\n1. _______________\n2. _______________\n```\n\n**Example:**\n```\n🧠 CHECKPOINT:\n\nPlatform:   iOS + Android (Cross-platform)\nFramework:  React Native + Expo\nFiles Read: touch-psychology.md, mobile-performance.md, platform-ios.md, platform-android.md\n\n3 Principles I Will Apply:\n1. FlatList with React.memo + useCallback for all lists\n2. 48px touch targets, thumb zone for primary CTAs\n3. Platform-specific navigation (edge swipe iOS, back button Android)\n\nAnti-Patterns I Will Avoid:\n1. ScrollView for lists → FlatList\n2. Inline renderItem → Memoized\n3. AsyncStorage for tokens → SecureStore\n```\n\n> 🔴 **Can''t fill the checkpoint? → GO BACK AND READ THE SKILL FILES.**\n\n---\n\n## 🔧 Framework Decision Tree\n\n```\nWHAT ARE YOU BUILDING?\n        │\n        ├── Need OTA updates + rapid iteration + web team\n        │   └── ✅ React Native + Expo\n        │\n        ├── Need pixel-perfect custom UI + performance critical\n        │   └── ✅ Flutter\n        │\n        ├── Deep native features + single platform focus\n        │   ├── iOS only → SwiftUI\n        │   └── Android only → Kotlin + Jetpack Compose\n        │\n        ├── Existing RN codebase + new features\n        │   └── ✅ React Native (bare workflow)\n        │\n        └── Enterprise + existing Flutter codebase\n            └── ✅ Flutter\n```\n\nFor complete decision trees: [decision-trees.md](decision-trees.md)\n\n---\n\n## 📋 Pre-Development Checklist\n\n### Before Starting ANY Mobile Project\n\n- [ ] **Platform confirmed?** (iOS / Android / Both)\n- [ ] **Framework chosen?** (RN / Flutter / Native)\n- [ ] **Navigation pattern decided?** (Tabs / Stack / Drawer)\n- [ ] **State management selected?** (Zustand / Redux / Riverpod / BLoC)\n- [ ] **Offline requirements known?**\n- [ ] **Deep linking planned from day one?**\n- [ ] **Target devices defined?** (Phone / Tablet / Both)\n\n### Before Every Screen\n\n- [ ] **Touch targets ≥ 44-48px?**\n- [ ] **Primary CTA in thumb zone?**\n- [ ] **Loading state exists?**\n- [ ] **Error state with retry exists?**\n- [ ] **Offline handling considered?**\n- [ ] **Platform conventions followed?**\n\n### Before Release\n\n- [ ] **console.log removed?**\n- [ ] **SecureStore for sensitive data?**\n- [ ] **SSL pinning enabled?**\n- [ ] **Lists optimized (memo, keyExtractor)?**\n- [ ] **Memory cleanup on unmount?**\n- [ ] **Tested on low-end devices?**\n- [ ] **Accessibility labels on all interactive elements?**\n\n---\n\n## 📚 Reference Files\n\nFor deeper guidance on specific areas:\n\n| File | When to Use |\n|------|-------------|\n| [mobile-design-thinking.md](mobile-design-thinking.md) | **FIRST! Anti-memorization, forces context-based thinking** |\n| [touch-psychology.md](touch-psychology.md) | Understanding touch interaction, Fitts'' Law, gesture design |\n| [mobile-performance.md](mobile-performance.md) | Optimizing RN/Flutter, 60fps, memory/battery |\n| [platform-ios.md](platform-ios.md) | iOS-specific design, HIG compliance |\n| [platform-android.md](platform-android.md) | Android-specific design, Material Design 3 |\n| [mobile-navigation.md](mobile-navigation.md) | Navigation patterns, deep linking |\n| [mobile-typography.md](mobile-typography.md) | Type scale, system fonts, accessibility |\n| [mobile-color-system.md](mobile-color-system.md) | OLED optimization, dark mode, battery |\n| [decision-trees.md](decision-trees.md) | Framework, state, storage decisions |\n\n---\n\n> **Remember:** Mobile users are impatient, interrupted, and using imprecise fingers on small screens. Design for the WORST conditions: bad network, one hand, bright sun, low battery. If it works there, it works everywhere.\n"},"lastSynced":"2026-03-06T06:26:20.244Z","agentAnalysis":{"suitability":{"en":"Perfect for UI/UX Agents needing touch-first and battery-conscious design principles for mobile applications.","zh":"非常适合需要触摸优先和电池节能设计原则的移动应用 UI/UX 代理。","ja":"タッチファーストとバッテリー意識のある設計原則を必要とするモバイルアプリケーションの UI/UX エージェントに最適です。","ko":"모바일 애플리케이션의 터치 우선 및 배터리 节能 설계 원칙이 필요한 UI/UX 에이전트에 적합합니다.","es":"Perfecto para Agentes de UI/UX que necesitan principios de diseño de touch-first y conciencia de batería para aplicaciones móviles.","fr":"Parfait pour les agents UI/UX ayant besoin de principes de conception de touch-first et de conscience de batterie pour les applications mobiles.","de":"Perfekt für UI/UX-Agents, die touch-first- und batteriebewusste Designprinzipien für mobile Anwendungen benötigen.","pt":"Perfeito para Agentes de UI/UX que necessitam de princípios de design touch-first e conscientes da bateria para aplicações móveis.","ru":"Идеально для агентов UI/UX, которым необходимы принципы дизайна touch-first и экономии батареи для мобильных приложений.","ar":"مثالي للوكلاء UI/UX الذين يحتاجون إلى مبادئ التصميم التي تعمل بالأولوية على اللمس وأحكام البطارية لتطبيقات الجوال."},"recommendation":{"en":"Empowers agents to design mobile interfaces with platform-respectful and offline-capable principles, utilizing Python scripts like mobile_audit.py for validation and optimization, and respecting mobile constraints.","zh":"使代理能够使用 Python 脚本（如 mobile_audit.py）设计移动接口，利用平台尊重和离线功能的原则进行验证和优化，并尊重移动约束。","ja":"エージェントが Python スクリプト（例：mobile_audit.py）を使用してプラットフォーム尊重とオフライン対応の原則を活用し、モバイル制約を尊重しながらモバイルインターフェイスを設計できるようにします。","ko":"에이전트가 Python 스크립트(mobile_audit.py와 같은)를 사용하여 플랫폼 존중 및 오프라인 기능의 원칙을 활용하여 모바일 인터페이스를 설계할 수 있도록 하며, 모바일 제약을尊重합니다.","es":"Habilita a los agentes a diseñar interfaces móviles con principios respetuosos con la plataforma y capaces de funcionar sin conexión, utilizando scripts de Python como mobile_audit.py para la validación y optimización, y respetando las restricciones móviles.","fr":"Permet aux agents de concevoir des interfaces mobiles avec des principes respectueux de la plateforme et capables de fonctionner hors ligne, en utilisant des scripts Python tels que mobile_audit.py pour la validation et l''optimisation, et en respectant les contraintes mobiles.","de":"Ermächtigt die Agenten, mobile Schnittstellen mit plattformrespektierenden und offline-fähigen Prinzipien zu entwerfen, indem sie Python-Skripte wie mobile_audit.py für die Validierung und Optimierung verwenden und die mobilen Einschränkungen respektieren.","pt":"Habilita os agentes a projetarem interfaces móveis com princípios respeitosos com a plataforma e capazes de funcionar offline, utilizando scripts Python como mobile_audit.py para validação e otimização, e respeitando as restrições móveis.","ru":"Наделяет агентов возможностью проектировать мобильные интерфейсы с учетом платформы и возможностью работы в автономном режиме, используя скрипты Python, такие как mobile_audit.py, для проверки и оптимизации, а также уважая ограничения мобильных устройств.","ar":"يمنح الوكلاء القدرة على تصميم واجهات مستخدم الجوال مع مبادئ محترمة للمنصة وقادرة على العمل بدون اتصال، باستخدام نصوص Python مثل mobile_audit.py للتحقق والتحسين، واحترام القيود المتنقلة."},"useCases":{"en":["Auditing mobile applications for touch and UX optimization","Designing battery-conscious and offline-capable mobile interfaces","Validating mobile design principles for platform respectfulness"],"zh":["审计移动应用程序以优化触摸和用户体验","设计节能和离线功能的移动接口","验证移动设计原则以确保平台尊重"],"ja":["タッチと UX 最適化のためのモバイル アプリケーションの監査","バッテリー意識のあるオフライン対応のモバイル インターフェイスの設計","プラットフォーム尊重のためのモバイル設計原則の検証"],"ko":["터치 및 UX 최적화를 위한 모바일 애플리케이션 감사","배터리 절약 및 오프라인 기능의 모바일 인터페이스 설계","플랫폼 존중을 위한 모바일 디자인 원칙의 검증"],"es":["Auditoría de aplicaciones móviles para la optimización de touch y UX","Diseño de interfaces móviles conscientes de la batería y capaces de funcionar sin conexión","Validación de principios de diseño móvil para el respeto a la plataforma"],"fr":["Audit des applications mobiles pour l''optimisation de touch et UX","Conception d''interfaces mobiles économes en batterie et capables de fonctionner hors ligne","Validation des principes de conception mobile pour le respect de la plateforme"],"de":["Auditing von mobilen Anwendungen für Touch- und UX-Optimierung","Entwurf von batteriebewussten und offline-fähigen mobilen Schnittstellen","Validierung von mobilen Designprinzipien für Plattformrespekt"],"pt":["Auditoria de aplicações móveis para otimização de toque e UX","Projeto de interfaces móveis conscientes da bateria e capazes de funcionar offline","Validação de princípios de design móvel para respeito à plataforma"],"ru":["Проверка мобильных приложений на оптимальность касания и UX","Проектирование мобильных интерфейсов, экономящих батарею и работающих в автономном режиме","Проверка принципов мобильного дизайна на уважение платформы"],"ar":["فحص التطبيقات الجوالة لتحسين اللمس وتجربة المستخدم","تصميم واجهات الجوال المحسنة للبطارية والقادرة على العمل بدون اتصال","التحقق من مبادئ تصميم الجوال لاحترام المنصة"]},"limitations":{"en":["Requires Python environment for script execution","Limited to mobile design principles and validation"],"zh":["需要 Python 环境来执行脚本","仅限于移动设计原则和验证"],"ja":["スクリプトの実行には Python 環境が必要","モバイル設計原則と検証のみに限定"],"ko":["스크립트 실행을 위해 Python 환경이 필요","모바일 디자인 원칙 및 검증에만 제한"],"es":["Requiere un entorno de Python para la ejecución de scripts","Limitado a principios de diseño móvil y validación"],"fr":["Nécessite un environnement Python pour l''exécution de scripts","Limité aux principes de conception mobile et à la validation"],"de":["Benötigt eine Python-Umgebung für die Skriptausführung","Begrenzt auf mobile Designprinzipien und Validierung"],"pt":["Requer ambiente Python para execução de scripts","Limitado a princípios de design móvel e validação"],"ru":["Требуется среда Python для выполнения скриптов","Ограничен принципами дизайна мобильных устройств и проверкой"],"ar":["يتطلب بيئة Python لتشغيل النصوص","محدود بمبادئ تصميم الجوال والتحقق"]},"version":4},"contentHash":"ec74cda5e1954572e4282c3aaa9c1c32ec743cef83c53f8aef622c00dc8f0682","qualityScore":52}');
