INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mrmps/SMRY/mobile-design', 'mobile-design', 'mrmps', 'SMRY', 'community', 'mobile-design mrmps SMRY community ai next13 openai The mobile-design skill provides a tool for summaries and paywall bypassing, benefiting developers with touch-first and battery-conscious design principles. 移动设计系统是一种Touch-first、Battery-conscious、Platform-respectful、Offline-capable的设计方法 モバイルデザインシステムは、タッチファースト、バッテリー意識、プラットフォーム尊重、オフライン可能な設計方法です 모바일 디자인 시스템은 터치 우선, 배터리 소모 최소화, 플랫폼尊重, 오프라인 가능性的 설계 방법입니다 El sistema de diseño móvil es una herramienta para desarrolladores que permite crear interfaces de usuario móviles eficaces Le système de conception mobile est un outil pour les développeurs qui permet de créer des interfaces utilisateur mobiles efficaces Das mobile Designsystem ist ein Tool für Entwickler, mit dem effektive mobile Benutzeroberflächen erstellt werden können Nossa ferramenta de design móvel é baseada em filosofia de toque, economia de bateria e respeito à plataforma, permitindo a criação de experiências móveis otimizadas. Наш инструмент мобильного дизайна основан на философии осязания, экономии батареи и уважении к платформе, что позволяет создавать мобильные trải nghiệm. أداة تصميم الهاتف المحمول لدينا تقوم على فلسفة اللمس وتوفير البطارية والاحترام للمنصة، مما يسمح بإنشاء تجارب الهاتف المحمول المُحسَّنة. how to use mobile-design mobile-design setup guide mobile-design vs responsive design what is mobile-design mobile-design install mobile-design alternative mobile-design philosophy touch-first design principles battery-conscious design 移动设计系统 AIエージェント Touch-first设计 Battery-conscious设计 Platform-respectful设计 Offline-capable设计 Python脚本 移动UX Touch Audit Executes mobile UX and touch audits via scripts/mobile_audit.py Validates mobile constraints and platform choice Runs on Python with scripts/mobile_audit.py command Supports offline-capable design Respects platform differences with core principle implementation mobile-design is a touch-first, battery-conscious, and platform-respectful design system for mobile applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ziggy42/epsilon/release', 'community', 'ziggy42', 'epsilon', 'ziggy42/epsilon', 'release', 414, 9, 52, '2026-03-01T14:59:17Z', '2026-03-06T06:28:10.017Z', '34ba7896fb562499db5f5e863721d6deb618a9981cf7883b09318329d9f08f93', '{"id":"ziggy42/epsilon/release","name":"release","description":{"en":"The Release skill automates the process of cutting new releases for projects, handling version determination, changelog generation, and git tagging. It benefits developers working with Go and WebAssembly.","zh":"Release技能是一个基于Go的WASM虚拟机，用于版本确定、变更日志生成和Git标签","ja":"Releaseスキルは、GoによるWASM仮想マシンで、バージョンの決定、変更ログの生成、Gitタグ付けを行う","ko":"Release 스킬은 Go 기반의 WASM 가상 머신으로 버전 결정, 변경 로그 생성 및 Git 태그 지정","es":"El skill release es una máquina virtual WASM escrita en Go que maneja la determinación de versión y la generación de changelog para tu proyecto","fr":"Le skill release est une machine virtuelle WASM écrite en Go qui gère la détermination de version et la génération de changelog pour votre projet","de":"Der Release-Skill ist eine WASM-Virtuelle Maschine, die in Go geschrieben ist und die Versionsbestimmung und Changelog-Generierung für Ihr Projekt handhabt","pt":"O release é um processo que envolve a determinação da versão e a geração de changelog. Nossa guia ajuda a configurar o release com facilidade.","ru":"Релиз - это процесс, который включает определение версии и генерацию changelog. Наша инструкция помогает настроить релиз легко.","ar":"الإصدار هو عملية تتضمن تحديد الإصدار وتوليد سجل التغييرات. دليلنا يساعد على إعداد الإصدار بسهولة."},"seo":{"title":{"en":"Release: Automated Versioning Setup Guide | AI Agent Skill","zh":"Release Setup Guide - 基于Go的WASM虚拟机","ja":"Release 初期化ガイド - GoによるWASM仮想マシン","ko":"Release 설정 가이드 - Go 기반 WASM 가상 머신","es":"Guía de configuración de release para WASM con Go","fr":"Guide d''installation de relea