INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ziggy42/epsilon/release', 'release', 'ziggy42', 'epsilon', 'community', 'release ziggy42 epsilon community go golang wasm webassembly webassembly-runtime The Release skill automates the process of cutting new releases for projects, handling version determination, changelog generation, and git tagging. It benefits developers working with Go and WebAssembly. Release技能是一个基于Go的WASM虚拟机，用于版本确定、变更日志生成和Git标签 Releaseスキルは、GoによるWASM仮想マシンで、バージョンの決定、変更ログの生成、Gitタグ付けを行う Release 스킬은 Go 기반의 WASM 가상 머신으로 버전 결정, 변경 로그 생성 및 Git 태그 지정 El skill release es una máquina virtual WASM escrita en Go que maneja la determinación de versión y la generación de changelog para tu proyecto Le skill release est une machine virtuelle WASM écrite en Go qui gère la détermination de version et la génération de changelog pour votre projet Der Release-Skill ist eine WASM-Virtuelle Maschine, die in Go geschrieben ist und die Versionsbestimmung und Changelog-Generierung für Ihr Projekt handhabt O release é um processo que envolve a determinação da versão e a geração de changelog. Nossa guia ajuda a configurar o release com facilidade. Релиз - это процесс, который включает определение версии и генерацию changelog. Наша инструкция помогает настроить релиз легко. الإصدار هو عملية تتضمن تحديد الإصدار وتوليد سجل التغييرات. دليلنا يساعد على إعداد الإصدار بسهولة. how to use release release setup guide go release management webassembly release process release alternative to manual versioning release vs semantic release install release release for ai agents automated versioning with release Release技能 Go语言 WASM虚拟机 版本发布 变更日志 Git标签 AIエージェント 自动化版本发布 Handles version determination using Git Generates changelogs automatically Updates files and creates git tags Verifies local branch and syncs with remote origin Runs on a WASM virtual machine with 0 dependencies Release is a WASM virtual machine written in Go that automates the release process, including version determination and changelog generation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('techwithanirudh/coolify-tweaks/create-changeset', 'community', 'techwithanirudh', 'coolify-tweaks', 'techwithanirudh/coolify-tweaks', 'create-changeset', 146, 4, 52, '2026-02-18T13:30:56Z', '2026-03-06T06:29:32.173Z', 'cc1041b67def390ec249f5954d24eaa341c79205014123ded754551a1010ea3b', '{"id":"techwithanirudh/coolify-tweaks/create-changeset","name":"create-changeset","description":{"en":"The create-changeset skill automatically analyzes branch changes and creates changesets for package releases. It benefits developers by simplifying the release process.","zh":"Create Changeset 技术自动分析 Git 历史记录，根据 Conventional Commits 确定版本 bump 类型，生成格式化的更改集文件","ja":"Create Changeset 技術は Git 歴史を自動分析し、Conventional Commits に基づいてバージョン bump タイプを決定して、正しくフォーマットされた変更セットファイルを生成","ko":"Create Changeset 기술은 Git 기록을 자동 분석하여 Conventional Commits 기반의 버전 bump 유형을 결정하고 올바르게 형식화된 변경 세트 파일을 생성","es":"Create-changeset es una habilidad que automatiza la creación de cambios en tu monorepo, examinando el historial de Git y generando archivos de cambios correctamente formateados","fr":"Create-changeset est une compétence qui automatise la création de changements dans votre monorepo, en examinant l''historique de Git et en générant des fichiers de changements correctement formatés","de":"Create-changeset ist eine Fähigkeit, die die Erstellung von Änderungen in Ihrem Monorepo automatisiert, indem sie den Git-Verlauf untersucht und korrekt formatierte Änderungsdateien generiert","pt":"O Create Changeset é uma habilidade que melhora a UI do Coolify com ajustes personalizados e layouts aprimorados","ru":"Create Changeset - это навык, который улучшает интерфейс Coolify с помощью индивидуальных настроек и оптимизированных макетов","ar":"Create Changeset هو مهارة لتحسين واجهة Coolify بتحسينات وتصميمات مخصصة"},"seo":{"title":{"en":"create-changeset: Automated Changeset Creation for AI Age...","zh":"Create Changeset 技术指南 - 自动分析分支变化","ja":"Create Changeset セットアップガイド - ブランチ変更の自動分析","ko":"Create Changeset 설정 가이드 - 자동 브랜치 변경 분석","es":"Guía de configuración de create-changeset para optimizar ...","fr":"Configurer create-changeset pour améliorer votre workflow...","de":"Einrichtungsleitfaden für create-changeset zur Optimierun...","pt":"Guia de Configuração do Create Changeset para Melhorar a ...","ru":"Настройка Create Changeset: автоматическое создание измен...","ar":"إعداد Create Changeset لتحسين واجهة Coolify"},"description":{"en":"Streamline your package release process with create-changeset, a skill that automatically generates changesets based on Conventional Commits. Learn how to in...","zh":"了解 Create Changeset 技术，自动分析 Git 历史记录，生成更改集文件，简化包发布流程","ja":"Create Changeset 技術で Git 歴史を自動分析し、変更セットファイルを生成してパッケージリリースを簡素化","ko":"Create Changeset 기술로 Git 기록을 자동 분석하고 변경 세트 파일을 생성하여 패키지 릴리스를 간소화","es":"Aprende a utilizar create-changeset para automatizar la creación de cambios en tu monorepo y mejorar la eficiencia de tu equipo de desarrollo","fr":"Découvrez comment utiliser create-changeset pour automatiser la création de changements dans votre monorepo et améliorer l''efficacité de votre équipe de déve...","de":"Erfahren Sie, wie Sie create-changeset verwenden können, um die Erstellung von Änderungen in Ihrem Monorepo zu automatisieren und die Effizienz Ihres Entwick...","pt":"Aprenda a configurar o Create Changeset para melhorar a UI do Coolify com ajustes personalizados e layouts aprimorados","ru":"Узнайте, как настроить Create Changeset для автоматического создания изменений и улучшения интерфейса Coolify","ar":"تعلم كيفية إعداد Create Changeset لتحسين واجهة Coolify بتحسينات وتصميمات مخصصة"},"definition":{"en":"create-changeset is a skill that automatically generates properly formatted changeset files based on git history and Conventional Commits.","zh":"Create Changeset 是一种自动分析 Git 历史记录的技术，用于生成更改集文件","ja":"Create Changeset は Git 歴史を自動分析して変更セットファイルを生成する技術","ko":"Create Changeset은 Git 기록을 자동 분석하여 변경 세트 파일을 생성하는 기술","es":"Create-changeset es una herramienta de desarrollo que automatiza la creación de cambios en un monorepo","fr":"Create-changeset est un outil de développement qui automatise la création de changements dans un monorepo","de":"Create-changeset ist ein Entwicklungstool, das die Erstellung von Änderungen in einem Monorepo automatisiert","pt":"O que é Create Changeset? Uma habilidade que analisa alterações de branch e cria conjuntos de alterações para lançamentos de pacotes","ru":"Что такое Create Changeset? Навык, который анализирует изменения веток и создает наборы изменений для выпусков пакетов","ar":"ما هو Create Changeset؟ مهارة تحليل التغييرات وتạo مجموعات التغييرات للنشر"},"features":{"en":["Analyzes git history to determine version bump types","Generates properly formatted changeset files","Automatically invokes when preparing to create a pull request","Supports Conventional Commits for versioning","Examines branch changes for package releases","Creates changesets for monorepo package releases"],"zh":["自动分析 Git 历史记录","根据 Conventional Commits 确定版本 bump 类型","生成格式化的更改集文件","支持 monorepo 包发布","自动检测分支变化"],"ja":["Git 歴史の自動分析","Conventional Commits に基づくバージョン bump タイプの決定","正しくフォーマットされた変更セットファイルの生成","monorepo パッケージリリースのサポート","ブランチ変更の自動検出"],"ko":["Git 기록의 자동 분석","Conventional Commits 기반의 버전 bump 유형 결정","올바르게 형식화된 변경 세트 파일 생성","monorepo 패키지 릴리스 지원","브랜치 변경 자동 감지"],"es":["Análisis automático del historial de Git","Determinación del tipo de incremento de versión basado en Commits Convencionales","Generación de archivos de cambios correctamente formateados","Integración con el flujo de trabajo de desarrollo","Soporte para monorepo","Automatización de la creación de cambios"],"fr":["Analyse automatique de l''historique de Git","Détermination du type d''increment de version basé sur les Commits Conventionnels","Génération de fichiers de changements correctement formatés","Intégration avec le flux de travail de développement","Support pour monorepo","Automatisation de la création de changements"],"de":["Automatisierte Analyse des Git-Verlaufs","Bestimmung des Versionsincrement-Typs basierend auf Conventional Commits","Generierung korrekt formatierter Änderungsdateien","Integration in den Entwicklungsworkflow","Unterstützung für Monorepo","Automatisierung der Erstellung von Änderungen"],"pt":["Análise de alterações de branch","Criação automática de conjuntos de alterações","Ajustes personalizados para a UI do Coolify","Layouts aprimorados para melhor experiência do usuário","Integração com Conventional Commits","Geração de arquivos de changeset formatados"],"ru":["Анализ изменений веток","Автоматическое создание наборов изменений","Индивидуальные настройки для интерфейса Coolify","Оптимизированные макеты для лучшего пользовательского опыта","Интеграция с Conventional Commits","Генерация форматированных файлов changeset"],"ar":["تحليل التغييرات","إنشاء مجموعات التغييرات автомatisch","تحسينات مخصصة لواجهة Coolify","تصميمات محسنة لتجربة المستخدم","التكامل مع Conventional Commits","إنشاء ملفات التغييرات المنسقة"]},"keywords":{"en":["how to use create-changeset","create-changeset setup guide","automated changeset creation","Conventional Commits","git history analysis","create-changeset alternative","create-changeset vs manual changeset creation","monorepo package release","package release automation"],"zh":["Create Changeset","Git 自动分析","Conventional Commits","版本 bump","monorepo 包发布","AI エージェント","自动化开发工具"],"ja":["Create Changeset","Git 自動分析","Conventional Commits","バージョン bump","monorepo パッケージリリース","AIエージェント","自動化開発ツール"],"ko":["Create Changeset","Git 자동 분석","Conventional Commits","버전 bump","monorepo 패키지 릴리스","AI 에이전트","자동화 개발 도구"],"es":["create-changeset","monorepo","Git","Commits Convencionales","automatización de desarrollo","herramientas de desarrollo","flujo de trabajo de desarrollo","optimización de desarrollo","Agente de IA para desarrollo"],"fr":["create-changeset","monorepo","Git","Commits Conventionnels","automatisation de développement","outils de développement","flux de travail de développement","optimisation de développement","Agent IA pour développement"],"de":["create-changeset","Monorepo","Git","Conventional Commits","Automatisierung von Entwicklung","Entwicklungstools","Entwicklungsworkflow","Optimierung von Entwicklung","KI-Agent für Entwicklung"],"pt":["Create Changeset","Coolify","UI personalizada","Conventional Commits","análise de alterações de branch","criação de conjuntos de alterações","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Create Changeset","Coolify","индивидуальный интерфейс","Conventional Commits","анализ изменений веток","создание наборов изменений","разработка программного обеспечения","инструменты разработки"],"ar":["Create Changeset","Coolify","واجهة مخصصة","Conventional Commits","تحليل التغييرات","إنشاء مجموعات التغييرات","تطوير البرمجيات","أدوات تطوير البرمجيات"]}},"owner":"techwithanirudh","repo":"coolify-tweaks","repoPath":"techwithanirudh/coolify-tweaks","stars":146,"forks":4,"updatedAt":"2026-02-18T13:30:56Z","topics":["coolify","coolify-v4","stylus","theme","themes","theming","tweaks","ui","userstyle"],"category":"community","skillMd":{"name":"create-changeset","description":"Analyze git changes and create changesets for package releases. Use when preparing pull requests, creating PRs, when branch has commits ready for review, or when user mentions changeset or version bump.","bodyPreview":"# Create Changeset Skill\n\n## Purpose\n\nThis skill automatically analyzes branch changes and creates appropriate changesets for package releases in this monorepo. It examines git history, determines version bump types based on Conventional Commits, and generates properly formatted changeset files.\n\n## When to Invoke\n\nAutomatically invoke this skill when:\n- User is preparing to create a pull request\n- User mentions \"PR\", \"pull request\", or \"ready for review\"\n- Branch has commits ready for review\n-","body":"# Create Changeset Skill\n\n## Purpose\n\nThis skill automatically analyzes branch changes and creates appropriate changesets for package releases in this monorepo. It examines git history, determines version bump types based on Conventional Commits, and generates properly formatted changeset files.\n\n## When to Invoke\n\nAutomatically invoke this skill when:\n- User is preparing to create a pull request\n- User mentions \"PR\", \"pull request\", or \"ready for review\"\n- Branch has commits ready for review\n- User explicitly mentions \"changeset\" or \"version bump\"\n\nDo NOT invoke when:\n- User is only pushing changes without creating a PR\n- Only documentation files have changed (README, .md files)\n- Only CI/CD configuration has changed (.github/workflows/)\n- Only development tool configuration has changed (eslint, prettier, etc.)\n- Commits are only `docs:`, `chore:`, `ci:`, or `test:` types that don''t affect packages\n\n## Pre-execution Validation\n\nBefore creating a changeset, check if a changeset file already exists for the current changes:\n- Look for `.changeset/*.md` files (excluding README.md)\n- If exists, ask user: \"A changeset already exists. Create another one?\"\n\n> **Repository note:** Only the `@repo/style` package currently publishes via changesets. No other workspace packages emit changeset-based releases, so focus analysis on `apps/style/` files and the surrounding tooling that affects it.\n\n## Implementation Steps\n\n### 1. Check Current State\n\n- Run `git fetch --tags`, then determine the latest release tag (`git tag --list ''v*'' --sort=-v:refname | head -n1`).\n- Use `git log <latest-tag>..HEAD` (or `origin/main..<latest-tag>` if needed) to verify there are commits to release.\n- If no tags exist, fall back to `git log main..HEAD` and explain why you''re using the branch range.\n- Stop if there are no commits since the latest tag.\n\n### 2. Analyze Changes\n\n- Diff against the latest tag (`git diff <latest-tag>..HEAD`) to inspect committed changes.\n- Keep the focus on `apps/style/` and its build tooling, since `@repo/style` is the only changeset-published package.\n- Summaries: use `git log <latest-tag>..HEAD --oneline` for Conventional Commit intents.\n- Only mention files outside `apps/style/` if they clearly affect the generated CSS.\n\n### 3. Determine Version Bump Type\n\nAnalyze commit messages following Conventional Commits 1.0.0 format:\n\n- **major**: Contains `BREAKING CHANGE` in commit body, or breaking changes detected in code\n  - API signature changes\n  - Removed exports or features\n  - Incompatible behavior changes\n- **minor**: Starts with `feat:` or `feat(scope):` - new features (backward compatible)\n  - New components or functionality\n  - New props or options (with defaults)\n  - New exports\n- **patch**: Starts with `fix:` or `fix(scope):` - bug fixes and minor improvements\n  - Bug fixes\n  - Performance improvements\n  - Minor style updates\n- **skip**: Other types (`chore:`, `docs:`, `ci:`, `test:`) typically don''t require changesets unless they affect package functionality\n\nReview actual code changes to confirm the appropriate version bump. **When in doubt between minor and patch, prefer patch for safety.**\n\nIf the version bump is ambiguous or unclear:\n- Ask user for clarification\n- Explain the reasoning behind the suggested bump type\n- Allow user to override the suggestion\n\nIf all commits are types that don''t require changesets (`docs:`, `chore:`, `ci:`, `test:`), exit early without creating a changeset.\n\n### 4. Generate Changeset\n\nCreate a changeset file with a descriptive filename in `.changeset/` directory.\n\n**Filename format:**\n- Use kebab-case with `.md` extension\n- Examples: `.changeset/add-new-button.md`, `.changeset/fix-layout-bug.md`, `.changeset/update-icon-props.md`\n\n**File content format:**\n```markdown\n---\n\"@repo/package-name\": major|minor|patch\n---\n\nClear description of the change\n```\n\n**Example for single package:**\n```markdown\n---\n\"@repo/style\": minor\n---\n\nAdd new Button variant for secondary actions\n```\n\n**Example for multiple packages:**\n```markdown\n---\n\"@repo/style\": minor\n\"@repo/docs\": patch\n---\n\n- style: Add new Button variant for secondary actions\n- dosc: Add new docs page for contributing\n```\n\n**Important guidelines:**\n- The description should be user-friendly as it will appear in CHANGELOG\n- **Use the same language as the commit messages** (Japanese or English). If commit messages are mixed, prefer Japanese.\n- Split changesets into separate files when the same package has changes with different purposes (e.g., new feature + bug fix, breaking change + internal refactoring)\n- This creates individual top-level items in release notes, making it easier for readers to understand the intent of each change\n- Example: Create `.changeset/add-secondary-button.md` for a new feature and `.changeset/fix-button-layout.md` for a bug fix, even if both target the same package\n\n### 5. Verify and Commit\n\nDisplay the generated changeset for review:\n- Show the file path\n- Show the file content\n- Confirm it accurately reflects the changes\n\nOnce verified, commit the changeset file:\n```bash\ngit add .changeset/<filename>.md\ngit commit -m \"chore: add changeset\"\n```\n"},"lastSynced":"2026-03-06T06:29:32.173Z","agentAnalysis":{"suitability":{"en":"Ideal for Git-based AI Agents needing automated release management and Conventional Commits analysis.","zh":"适用于需要自动化发布管理和 Conventional Commits 分析的基于 Git 的 AI Agent。","ja":"Git ベースの AI エージェントが自動化されたリリース管理と Conventional Commits 分析を必要とする場合に最適です。","ko":"자동화된 릴리스 관리 및 Conventional Commits 분석이 필요한 Git 기반 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA basados en Git que necesitan administración de versiones automatizada y análisis de Commits Convencionales.","fr":"Idéal pour les agents d''IA basés sur Git nécessitant une gestion de version automatisée et une analyse de Commits Conventionnels.","de":"Ideal für Git-basierte KI-Agents, die eine automatisierte Versionsverwaltung und eine Analyse von Conventional Commits benötigen.","pt":"Ideal para Agentes de IA baseados em Git que precisam de gerenciamento de lançamento automatizado e análise de Commits Convencionais.","ru":"Идеально для агентов ИИ на основе Git, которым требуется автоматизированное управление выпусками и анализ Conventional Commits.","ar":"مثالي لعميل الذكاء الاصطناعي المستند إلى Git الذي يحتاج إلى إدارة الإصدارات الآلية وتحليل Commits التقليدية."},"recommendation":{"en":"Empowers agents to automate package releases by analyzing git history, determining version bump types, and generating properly formatted changeset files using Conventional Commits protocol.","zh":"赋予代理人自动化包发布的能力，通过分析 Git 历史记录、确定版本 bump 类型，并使用 Conventional Commits 协议生成正确格式的更改集文件。","ja":"エージェントは Git の履歴を分析し、バージョンのバンプタイプを決定し、Conventional Commits プロトコルを使用して適切にフォーマットされた変更セットファイルを生成することで、パッケージのリリースを自動化できます。","ko":"에이전트가 Git 기록을 분석하여 버전 bump 유형을 결정하고 Conventional Commits 프로토콜을 사용하여 올바르게 형식화된 변경 세트 파일을 생성함으로써 패키지 릴리스를 자동화할 수 있습니다.","es":"Habilita a los agentes a automatizar las versiones de los paquetes analizando el historial de Git, determinando los tipos de incremento de versión y generando archivos de cambios correctamente formateados utilizando el protocolo Conventional Commits.","fr":"Permet aux agents d''automatiser les versions de packages en analysant l''historique Git, en déterminant les types d''incrément de version et en générant des fichiers de changements correctement formatés à l''aide du protocole Conventional Commits.","de":"Ermöglicht es den Agents, Paketversionen zu automatisieren, indem sie den Git-Verlauf analysieren, Versionssprungtypen bestimmen und ordnungsgemäß formatierte Änderungsprotokoll-Dateien unter Verwendung des Conventional Commits-Protokolls generieren.","pt":"Habilita os agentes a automatizar a liberação de pacotes analisando o histórico do git, determinando os tipos de incremento de versão e gerando arquivos de conjunto de alterações formatados corretamente usando o protocolo Conventional Commits.","ru":"Наделяет агентов возможностью автоматизировать выпуск пакетов, анализируя историю git, определяя типы инкремента версии и генерируя правильно отформатированные файлы изменений с использованием протокола Conventional Commits.","ar":"تمكين الوكيل من تلقين إصدار الحزم عن طريق تحليل تاريخ git وتحديد أنواع زيادة الإصدار وتوليد ملفات مجموعة التغييرات الصحيحة باستخدام بروتوكول Commits التقليدية."},"useCases":{"en":["Automating changeset creation for pull requests","Generating version bump types based on commit history","Streamlining package release processes with formatted changeset files"],"zh":["自动化 pull 请求的更改集创建","根据提交历史记录生成版本 bump 类型","使用格式化的更改集文件简化包发布流程"],"ja":["プルリクエストの変更セットの自動化","コミット履歴に基づいてバージョンのバンプタイプを生成","整形された変更セットファイルを使用したパッケージリリースプロセスの簡素化"],"ko":["풀 리퀘스트에 대한 변경 세트 생성 자동화","커밋 기록을 기준으로 버전 bump 유형 생성","형식화된 변경 세트 파일을 사용한 패키지 릴리스 프로세스 간소화"],"es":["Automatización de la creación de conjuntos de cambios para solicitudes de extracción","Generación de tipos de incremento de versión en función del historial de confirmaciones","Optimización de los procesos de lanzamiento de paquetes con archivos de conjuntos de cambios formateados"],"fr":["Automatisation de la création de jeux de modifications pour les demandes d''extraction","Génération de types d''incrément de version en fonction de l''historique des validations","Optimisation des processus de publication de packages avec des fichiers de jeux de modifications formatés"],"de":["Automatisierung der Erstellung von Änderungssätzen für Pull-Requests","Generierung von Versionssprungtypen auf der Grundlage des Commit-Verlaufs","Optimierung der Paketveröffentlichungsprozesse mit formatierten Änderungsprotokoll-Dateien"],"pt":["Automatizar a criação de conjunto de alterações para solicitações de pull","Gerar tipos de incremento de versão com base no histórico de commits","Otimizar os processos de lançamento de pacotes com arquivos de conjunto de alterações formatados"],"ru":["Автоматизировать создание набора изменений для запросов на вытягивание","Генерировать типы инкремента версии на основе истории коммитов","Оптимизировать процессы выпуска пакетов с отформатированными файлами изменений"],"ar":["تلقين إنشاء مجموعة التغييرات لطلبات السحب","توليد أنواع زيادة الإصدار بناءً على تاريخ الالتزامات","تبسيط عمليات إصدار الحزم مع ملفات مجموعة التغييرات المنسقة"]},"limitations":{"en":["Requires access to git repository","Limited to Conventional Commits protocol","Monorepo setup necessary for optimal functionality"],"zh":["需要访问 Git 存储库","仅限于 Conventional Commits 协议","单体仓库设置是实现最佳功能的必要条件"],"ja":["Git リポジトリへのアクセスが必要","Conventional Commits プロトコルに限定される","モノリポ設定が最適な機能を実現するために必要"],"ko":["Git 저장소에 대한 액세스가 필요합니다","Conventional Commits 프로토콜로 제한됨","최적의 기능을 구현하기 위해 모노리포 설정이 필요함"],"es":["Requiere acceso al repositorio de Git","Limitado al protocolo Conventional Commits","Configuración de monorepo necesaria para una funcionalidad óptima"],"fr":["Nécessite un accès au référentiel Git","Limité au protocole Conventional Commits","Configuration de monorepo nécessaire pour une fonctionnalité optimale"],"de":["Erfordert Zugriff auf das Git-Repository","Begrenzt auf das Conventional Commits-Protokoll","Monorepo-Einrichtung erforderlich für optimale Funktionalität"],"pt":["Requer acesso ao repositório git","Limitado ao protocolo Conventional Commits","Configuração de monorepo necessária para funcionalidade ótima"],"ru":["Требуется доступ к репозиторию git","Ограничен протоколом Conventional Commits","Настройка monorepo необходима для оптимальной функциональности"],"ar":["يتطلب الوصول إلى مستودع git","محدود ببروتوكول Commits التقليدية","إعداد monorepo ضروري للوظيفة المثلى"]},"version":4},"contentHash":"cc1041b67def390ec249f5954d24eaa341c79205014123ded754551a1010ea3b","qualityScore":52}');
