INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('techwithanirudh/coolify-tweaks/create-changeset', 'create-changeset', 'techwithanirudh', 'coolify-tweaks', 'community', 'create-changeset techwithanirudh coolify-tweaks community coolify coolify-v4 stylus theme themes theming tweaks ui userstyle The create-changeset skill automatically analyzes branch changes and creates changesets for package releases. It benefits developers by simplifying the release process. Create Changeset 技术自动分析 Git 历史记录，根据 Conventional Commits 确定版本 bump 类型，生成格式化的更改集文件 Create Changeset 技術は Git 歴史を自動分析し、Conventional Commits に基づいてバージョン bump タイプを決定して、正しくフォーマットされた変更セットファイルを生成 Create Changeset 기술은 Git 기록을 자동 분석하여 Conventional Commits 기반의 버전 bump 유형을 결정하고 올바르게 형식화된 변경 세트 파일을 생성 Create-changeset es una habilidad que automatiza la creación de cambios en tu monorepo, examinando el historial de Git y generando archivos de cambios correctamente formateados Create-changeset est une compétence qui automatise la création de changements dans votre monorepo, en examinant l''historique de Git et en générant des fichiers de changements correctement formatés Create-changeset ist eine Fähigkeit, die die Erstellung von Änderungen in Ihrem Monorepo automatisiert, indem sie den Git-Verlauf untersucht und korrekt formatierte Änderungsdateien generiert O Create Changeset é uma habilidade que melhora a UI do Coolify com ajustes personalizados e layouts aprimorados Create Changeset - это навык, который улучшает интерфейс Coolify с помощью индивидуальных настроек и оптимизированных макетов Create Changeset هو مهارة لتحسين واجهة Coolify بتحسينات وتصميمات مخصصة how to use create-changeset create-changeset setup guide automated changeset creation Conventional Commits git history analysis create-changeset alternative create-changeset vs manual changeset creation monorepo package release package release automation Create Changeset Git 自动分析 Conventional Commits 版本 bump monorepo 包发布 AI エージェント 自动化开发工具 Analyzes git history to determine version bump types Generates properly formatted changeset files Automatically invokes when preparing to create a pull request Supports Conventional Commits for versioning Examines branch changes for package releases Creates changesets for monorepo package releases create-changeset is a skill that automatically generates properly formatted changeset files based on git history and Conventional Commits.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('FireworkSky/RotatingartLauncher/ui-architecture', 'community', 'FireworkSky', 'RotatingartLauncher', 'FireworkSky/RotatingartLauncher', 'ui-architecture', 43, 6, 52, '2026-02-28T17:01:43Z', '2026-03-06T06:37:08.500Z', '639a6dd84367460815462a50f4009db48003b2d9d0692bdbd9280ddd0f3a172f', '{"id":"FireworkSky/RotatingartLauncher/ui-architecture","name":"ui-architecture","description":{"en":"The ui-architecture skill helps developers structure their UI components and logic. It provides guidelines for placing reusable UI and ViewModel logic in shared/src/commonMain/... and Android runtime integration in app/src/main/java/...","zh":"UI架构是一种将UI逻辑和ViewModel逻辑分离的设计模式。它可以帮助开发者构建高效、可维护的UI","ja":"UIアーキテクチャは、UIロジックとViewModelロジックを分離する設計パターンです。効率的なUIを構築するのに役立ちます","ko":"UI 아키텍처는 UI 로직과 ViewModel 로직을 분리하는 디자인 패턴입니다. 효율적이고 유지 보수 가능한 UI를 구축하는 데 도움이 됩니다","es":"La arquitectura de UI es fundamental para el desarrollo de aplicaciones móviles. Nuestra guía cubre la configuración de la arquitectura de UI para aplicaciones Android.","fr":"L''architecture d''UI est essentielle pour le développement d''applications mobiles. Notre guide couvre la configuration de l''architecture d''UI pour les applications Android et les outils d''IA","de":"Die UI-Architektur ist für die Entwicklung mobiler Anwendungen von entscheidender Bedeutung. Unser Leitfaden behandelt die Einrichtung der UI-Architektur für Android-Anwendungen und KI-Tools","pt":"A arquitetura de UI é fundamental para uma experiência do usuário agradável. Aprenda a estruturar seu projeto com nossas dicas","ru":"Архитектура UI является основой для приятного пользовательского опыта. Узнайте, как cấu trúcровать свой проект с нашими советами","ar":"هندسة واجهة المستخدم هي الأساس لتجربة المستخدم الممتعة. تعلم كيفية هيكلة مشروعك مع نصائحنا"},"seo":{"title":{"en":"ui-architecture: Setup Guide for AI Agents","zh":"UI架构最佳实践指南 - AIエージェント","ja":"UIアーキテクチャ設定ガイド - AIエージェント","ko":"UI 아키텍처 설정 가이드 - AI 에이전트","es":"Arquitectura de UI: Guía de configuración para desarrolla...","fr":"Architecture d''UI : Guide de démarrage pour les développe...","de":"UI-Architektur: Einrichtungsleitfaden für Entwickler von ...","pt":"Guia de Arquitetura de UI: Melhores Práticas para Desenvo...","ru":"ИИ Агенты: Руководство по Архитектуре UI для Разработчиков","ar":"دليل هندسة واجهة المستخدم: إرشادات لل مطورين"},"description":{"en":"Discover how to implement ui-architecture in your project. Learn where to place UI components, handle landscape constraints, and follow existing routing cont...","zh":"了解UI架构的技术细节，包括布局、路由和状态管理。使用AIエージェント构建高效的UI","ja":"UIアーキテクチャの技術的な詳細を学び、効率的なUIを構築する。AIエージェントを使用して","ko":"UI 아키텍처의 기술적인 세부 사항을 알아보고 AI 에이전트를 사용하여 효율적인 UI를 구축합니다","es":"Aprenda a diseñar una arquitectura de UI eficaz para sus aplicaciones móviles con nuestra guía de configuración paso a paso para desarrolladores","fr":"Découvrez comment concevoir une architecture d''UI efficace pour vos applications mobiles avec notre guide de démarrage étape par étape pour les développeurs ...","de":"Erfahren Sie, wie Sie eine effektive UI-Architektur für Ihre mobilen Anwendungen entwerfen können, mit unserem Schritt-für-Schritt-Einrichtungsleitfaden für ...","pt":"Aprenda a projetar uma arquitetura de UI eficaz com nossas dicas e melhores práticas para desenvolvedores","ru":"Узнайте, как спроектировать эффективную архитектуру UI с нашими советами и лучшими практиками для разработчиков ИИ Агентов","ar":"تعلم كيفية تصميم هندسة واجهة المستخدم الفعالة مع نصائحنا وأفضل الممارسات للمطورين"},"definition":{"en":"ui-architecture is a set of guidelines for structuring user interface components and logic in a scalable and maintainable way","zh":"UI架构是一种设计模式，用于将UI逻辑和ViewModel逻辑分离","ja":"UIアーキテクチャは、UIロジックとViewModelロジックを分離する設計パターン","ko":"UI 아키텍처는 UI 로직과 ViewModel 로직을 분리하는 디자인 패턴","es":"La arquitectura de UI se refiere al diseño y la estructura de la interfaz de usuario de una aplicación","fr":"L''architecture d''UI fait référence à la conception et à la structure de l''interface utilisateur d''une application d''outils d''IA","de":"Die UI-Architektur bezieht sich auf das Design und die Struktur der Benutzeroberfläche einer Anwendung von KI-Tools","pt":"Arquitetura de UI é a estruturação de elementos visuais e interativos em um aplicativo ou site","ru":"Архитектура UI - это структуризация визуальных и интерактивных элементов в приложении или сайте","ar":"هندسة واجهة المستخدم هي هيكلة العناصر المرئية والتفاعلية في تطبيق أو موقع"},"features":{"en":["Places reusable UI and ViewModel logic in shared/src/commonMain/...","Handles Android runtime integration in app/src/main/java/...","Confirms landscape constraints before layout work using manifest and base activity","Follows existing routing contracts using Screen, NavDestination, and NavState","Separates UI logic from Android runtime integration for better maintainability"],"zh":["将UI逻辑和ViewModel逻辑分离","使用Screen、NavDestination和NavState进行路由管理","支持Android运行时集成","遵循现有的路由合同"],"ja":["UIロジックとViewModelロジックを分離","Screen、NavDestination、NavStateを使用したルーティング管理","Androidランタイム統合のサポート","既存のルーティング契約の遵守"],"ko":["UI 로직과 ViewModel 로직을 분리","Screen, NavDestination, NavState를 사용한 라우팅 관리","Android 런타임 통합 지원","既存의 라우팅 계약 준수"],"es":["Configuración de la arquitectura de UI para aplicaciones Android","Uso de routing contracts como Screen, NavDestination y NavState","Integración con permisos, intents y lanzadores de actividades","Consideración de restricciones de paisaje antes del trabajo de diseño","Seguimiento de la lógica de ViewModel y UI reutilizable"],"fr":["Configuration de l''architecture d''UI pour les applications Android et les outils d''IA","Utilisation de contrats de routing tels que Screen, NavDestination et NavState","Intégration avec les autorisations, les intents et les lanceurs d''activités","Prise en compte des contraintes de paysage avant le travail de conception","Suivi de la logique de ViewModel et de l''UI réutilisable"],"de":["Einrichtung der UI-Architektur für Android-Anwendungen und KI-Tools","Verwendung von Routing-Verträgen wie Screen, NavDestination und NavState","Integration mit Berechtigungen, Intents und Aktivitätsstartern","Berücksichtigung von Landschaftsbeschränkungen vor dem Entwurfsprozess","Verfolgung der ViewModel-Logik und der wiederverwendbaren UI"],"pt":["Confirme onde a UI pertence no projeto","Verifique as restrições de paisagem antes do trabalho de layout","Siga os contratos de roteamento existentes","Siga o estado e os eventos da aplicação"],"ru":["Подтвердите, где UI принадлежит в проекте","Проверьте ограничения ландшафта перед работой по макету","Следуйте существующим маршрутизационным контрактам","Следуйте состоянию и событиям приложения"],"ar":["أكد مكان واجهة المستخدم في المشروع","تحقق من قيود المناظر قبل العمل على التصميم","اتبع العقود التوجيهية الحالية","اتبع حالة وأحداث التطبيق"]},"keywords":{"en":["how to use ui-architecture","ui-architecture setup guide","ui-architecture vs material design","what is ui-architecture","ui-architecture install","ui-architecture best practices","ui-architecture for android","ui-architecture navigation stack"],"zh":["UI架构","AIエージェント","UI设计模式","ViewModel","Android运行时集成","路由管理","Screen","NavDestination","NavState"],"ja":["UIアーキテクチャ","AIエージェント","UI設計パターン","ViewModel","Androidランタイム統合","ルーティング管理","Screen","NavDestination","NavState"],"ko":["UI 아키텍처","AI 에이전트","UI 디자인 패턴","ViewModel","Android 런타임 통합","라우팅 관리","Screen","NavDestination","NavState"],"es":["arquitectura de ui","desarrollo de aplicaciones móviles","guias de configuración","routing contracts","integración android","diseño de ui","lógica de viewmodel","ui reutilizable"],"fr":["architecture d''ui","développement d''applications mobiles","guides de configuration","contrats de routing","intégration android","conception d''ui","logique de viewmodel","ui réutilisable","outils d''ia"],"de":["ui-architektur","entwicklung mobiler anwendungen","einrichtungsleitfäden","routing-verträge","integration android","entwurf von ui","viewmodel-logik","wiederverwendbare ui","ki-tools"],"pt":["arquitetura de ui","desenvolvimento de aplicativos","ui para desenvolvedores","guias de ui","melhores práticas de ui","projeto de ui"],"ru":["архитектура ui","разработка приложений","ui для разработчиков","руководства по ui","лучшие практики ui","проектирование ui","ИИ Агенты"],"ar":["هندسة واجهة المستخدم","تطوير التطبيقات","واجهة المستخدم للمطورين","دليل واجهة المستخدم","أفضل الممارسات لواجهة المستخدم","تصميم واجهة المستخدم"]}},"owner":"FireworkSky","repo":"RotatingartLauncher","repoPath":"FireworkSky/RotatingartLauncher","stars":43,"forks":6,"updatedAt":"2026-02-28T17:01:43Z","topics":[],"category":"community","skillMd":{"name":"ui-architecture","description":"Project-specific UI implementation guideline for RotatingartLauncher. Use when adding, refactoring, or reviewing launcher UI so changes stay aligned with the apps landscape-first design, custom NavState/Screen routing, and MVVM state-event-effect patterns across app and shared modules.","bodyPreview":"# UI Architecture\n\n## Quick Start\n\n1. Confirm where the UI belongs:\n   - `shared/src/commonMain/...` for reusable/domain UI and ViewModel logic.\n   - `app/src/main/java/...` for Android runtime integration (permissions, intents, activity launchers, file system APIs).\n2. Confirm landscape constraints before layout work (manifest + base activity).\n3. Follow existing routing contracts (`Screen`, `NavDestination`, `NavState`) instead of introducing a parallel navigation stack.\n4. Follow state/event/","body":"# UI Architecture\n\n## Quick Start\n\n1. Confirm where the UI belongs:\n   - `shared/src/commonMain/...` for reusable/domain UI and ViewModel logic.\n   - `app/src/main/java/...` for Android runtime integration (permissions, intents, activity launchers, file system APIs).\n2. Confirm landscape constraints before layout work (manifest + base activity).\n3. Follow existing routing contracts (`Screen`, `NavDestination`, `NavState`) instead of introducing a parallel navigation stack.\n4. Follow state/event/effect MVVM flow before adding mutable local state.\n5. Keep visual design aligned with this repo''s MD3 + glass style (`RaLaunchTheme`, `GlassSurface`, motion and state feedback patterns).\n\n## Mandatory Pre-Modification Context\n\nBefore proposing UI changes, read these files first:\n\n1. `app/src/main/AndroidManifest.xml`\n2. `app/src/main/java/com/app/ralaunch/core/ui/base/BaseActivity.kt`\n3. `app/src/main/java/com/app/ralaunch/feature/main/MainActivityCompose.kt`\n4. `app/src/main/java/com/app/ralaunch/feature/main/MainApp.kt`\n5. `shared/src/commonMain/kotlin/com/app/ralaunch/shared/core/navigation/NavRoutes.kt`\n6. `shared/src/commonMain/kotlin/com/app/ralaunch/shared/core/navigation/AppNavHost.kt`\n7. `shared/src/commonMain/kotlin/com/app/ralaunch/shared/core/navigation/NavigationExtensions.kt`\n8. `app/src/main/java/com/app/ralaunch/feature/main/contracts/MainContracts.kt`\n9. `shared/src/commonMain/kotlin/com/app/ralaunch/shared/feature/settings/SettingsViewModel.kt`\n10. `shared/src/commonMain/kotlin/com/app/ralaunch/shared/core/component/game/GameListContent.kt`\n11. `shared/src/commonMain/kotlin/com/app/ralaunch/shared/core/theme/Theme.kt`\n12. `shared/src/commonMain/kotlin/com/app/ralaunch/shared/core/theme/Color.kt`\n13. `shared/src/commonMain/kotlin/com/app/ralaunch/shared/core/theme/Shape.kt`\n14. `shared/src/commonMain/kotlin/com/app/ralaunch/shared/core/theme/Typography.kt`\n15. `shared/src/commonMain/kotlin/com/app/ralaunch/shared/core/component/GlassComponents.kt`\n16. `shared/src/commonMain/kotlin/com/app/ralaunch/shared/core/component/AppNavigationRail.kt`\n\nFor deeper project context, load:\n- `../map-project-structure/references/rotatingart-architecture.md`\n- `references/ui-implementation-notes.md`\n\n## Landscape Rules\n\n1. Keep screens landscape-first. All launcher activities are locked to `sensorLandscape`; do not add portrait-only UI assumptions.\n2. Prefer split-pane `Row` layouts for high-information screens (list + detail).\n3. Reuse existing layout proportions when possible (for example `0.62/0.38` or `0.65/0.35`) before introducing new ratios.\n4. Validate both landscape widths commonly seen on tablets and phones; avoid fixed widths that break at smaller heights.\n\n## Routing Notes (Brief)\n\n1. Routing is custom and state-driven (`NavState`), not Navigation Compose `NavController`.\n2. Add new routes to `Screen` first (`NavRoutes.kt`).\n3. If the screen is a primary rail tab, add/update `NavDestination` too.\n4. Render route content in `MainApp` page routing (`PageContent`) and wire Android-specific dependencies in `MainActivityCompose` wrapper slots.\n5. Keep back behavior consistent with `handleBackPress()`:\n   - Pop sub-screen stack first.\n   - If on a non-games root destination, return to games before exiting.\n\n## MVVM Notes (Brief)\n\n1. Prefer unidirectional data flow:\n   - `UiState` as `StateFlow`\n   - `UiEvent` input to ViewModel\n   - `UiEffect` for one-time side effects\n2. Keep domain/business logic in repository/use-case layers, not Composables.\n3. Keep Android integration in app wrappers:\n   - activity result launchers\n   - permission flows\n   - intents/toasts/navigation side effects\n4. Use shared ViewModels for cross-platform reusable features; use app ViewModels for Android-only orchestration.\n5. Avoid new legacy MVP-style code for new UI work; align with existing Compose + ViewModel paths.\n\n## MD3 Design Rules\n\n1. Always render feature UI under `RaLaunchTheme`; do not create parallel theming systems.\n2. Prefer semantic tokens over hard-coded values:\n   - color: `MaterialTheme.colorScheme.*` and `RaLaunchTheme.extendedColors`\n   - type: `MaterialTheme.typography.*`\n   - shape: `MaterialTheme.shapes.*` / `AppShapes`\n3. Use MD3 surface layering for hierarchy (`surfaceContainerLow` -> `surfaceContainerHighest`) instead of arbitrary alpha overlays.\n4. Reuse existing glass primitives for blurred panels (`GlassSurface`, `GlassSurfaceRegular`) rather than custom blur stacks.\n5. Keep state communication explicit:\n   - selected, pressed, disabled, focused states must be visually distinct\n   - actions should use MD3 components (`Button`, `AssistChip`, `DropdownMenu`, etc.) before custom controls\n6. Maintain consistency with current motion language:\n   - short transitions for feedback (`150-300ms`)\n   - medium transitions for page/surface changes (`250-450ms`)\n   - spring for press/select responses when needed\n7. Keep one dominant accent per screen; avoid mixing unrelated highlight colors that reduce visual hierarchy.\n\n## Good UI Quality Bar\n\n1. Build for task clarity:\n   - one primary action per pane\n   - keep secondary actions grouped and visually quieter\n2. Build for scanability in landscape:\n   - split-pane composition for dense workflows\n   - avoid long single-column forms when side-by-side grouping is possible\n3. Build for resilient states:\n   - loading, empty, and error states must exist for each data-driven screen\n   - destructive actions require clear confirmation\n4. Build for usability:\n   - touch targets should remain comfortable in landscape (`~48dp` minimum)\n   - long labels should degrade gracefully (ellipsis/wrapping rules)\n5. Build for accessibility:\n   - meaningful `contentDescription` for icons/images\n   - sufficient contrast for text and controls over video/image backgrounds\n6. Build for performance:\n   - keep expensive operations out of Composables\n   - use stable keys in lazy lists/grids\n   - avoid heavy recomposition loops in animated screens\n\n## Workflow\n\n1. Identify target screen type:\n   - Main tab (`NavDestination`)\n   - Sub-screen (`Screen` with back stack)\n   - Dialog/overlay in current screen\n2. Reuse existing composables/components before creating new ones (`AppNavigationRail`, `GameListContent`, settings/file-browser shared UI).\n3. Add/extend `UiState`, `UiEvent`, `UiEffect` contracts before wiring UI interactions.\n4. Apply MD3 token decisions (color/type/shape/surface hierarchy) before finalizing visuals.\n5. Keep platform-specific code in app wrappers and shared logic in `shared` module.\n6. Validate behavior:\n   - route transitions\n   - back behavior\n   - state restoration after resume/config changes\n   - landscape usability\n   - interaction feedback (pressed/selected/disabled/loading/error)\n   - contrast/readability on themed backgrounds\n\n## Output Contract\n\nWhen using this skill for implementation guidance, provide:\n\n1. Target files and module boundaries (`app` vs `shared`).\n2. Routing impact (`Screen`/`NavDestination`/`PageContent` changes).\n3. MVVM contract impact (`UiState`/`UiEvent`/`UiEffect` + ViewModel updates).\n4. Landscape layout impact (pane structure, width ratios, overflow handling).\n5. MD3 design decisions (tokens/components/motion/surface layering).\n6. UI quality checks (state coverage, usability, accessibility, performance).\n7. Test/validation checklist (manual + automated where practical).\n"},"lastSynced":"2026-03-06T06:37:08.500Z","agentAnalysis":{"suitability":{"en":"Ideal for Android Development Agents requiring structured UI component organization and ViewModel logic management.","zh":"适用于需要结构化UI组件组织和ViewModel逻辑管理的Android开发代理。","ja":"Android開発エージェントが構造化されたUIコンポーネントの組織化とViewModelのロジック管理を必要とする場合に適しています。","ko":"구조화된 UI 컴포넌트 조직 및 ViewModel 논리 관리가 필요한 안드로이드 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo de Android que requieren una organización de componentes de interfaz de usuario estructurada y una gestión de lógica de ViewModel.","fr":"Idéal pour les agents de développement Android nécessitant une organisation de composants d''interface utilisateur structurée et une gestion de logique de ViewModel.","de":"Ideal für Android-Entwicklungsagenten, die eine strukturierte Organisation von Benutzeroberflächenkomponenten und eine Verwaltung der ViewModel-Logik erfordern.","pt":"Ideal para Agentes de Desenvolvimento Android que exigem organização de componentes de interface do usuário estruturada e gerenciamento de lógica de ViewModel.","ru":"Идеально подходит для агентов разработки Android, требующих структурированной организации компонентов пользовательского интерфейса и управления логикой ViewModel.","ar":"مثالي للوكلاء الذين يتطلبون تنظيم مكونات واجهة المستخدم المنظمة وإدارة منطق ViewModel."},"recommendation":{"en":"Empowers agents to efficiently structure UI components and logic using shared/src/commonMain/... for reusable UI and ViewModel logic, and app/src/main/java/... for Android runtime integration, while adhering to existing routing contracts like Screen, NavDestination, and NavState.","zh":"赋予代理高效地结构化UI组件和逻辑，使用shared/src/commonMain/...进行可重用的UI和ViewModel逻辑，以及app/src/main/java/...进行Android运行时集成，同时遵守现有的路由合约，如Screen、NavDestination和NavState。","ja":"エージェントに、共有されたUIとViewModelのロジックを共有/src/commonMain/...で、Androidのランタイム統合をapp/src/main/java/...で実行しながら、Screen、NavDestination、NavStateなどの既存のルーティング契約に従って、UIコンポーネントとロジックを効率的に構造化する能力を与えます。","ko":"에이전트에게 공유된 UI 및 ViewModel 논리를 shared/src/commonMain/...에서, 안드로이드 런타임 통합을 app/src/main/java/...에서 수행하면서 Screen, NavDestination, NavState 등의 기존 라우팅 계약을 준수하여 UI 컴포넌트 및 논리를 효율적으로 구조화할 수 있는 능력을 부여합니다.","es":"Permite a los agentes estructurar de manera eficiente los componentes de la interfaz de usuario y la lógica utilizando shared/src/commonMain/... para la lógica de interfaz de usuario y ViewModel reutilizable, y app/src/main/java/... para la integración de tiempo de ejecución de Android, mientras se adhiere a los contratos de enrutamiento existentes como Screen, NavDestination y NavState.","fr":"Permet aux agents de structurer efficacement les composants d''interface utilisateur et la logique en utilisant shared/src/commonMain/... pour la logique d''interface utilisateur et de ViewModel réutilisable, et app/src/main/java/... pour l''intégration du runtime Android, tout en respectant les contrats de routage existants tels que Screen, NavDestination et NavState.","de":"Ermöglicht es den Agenten, die Benutzeroberflächenkomponenten und die Logik effizient zu strukturieren, indem sie shared/src/commonMain/... für wiederverwendbare Benutzeroberflächen- und ViewModel-Logik und app/src/main/java/... für die Android-Laufzeitintegration verwenden, während sie den bestehenden Routing-Verträgen wie Screen, NavDestination und NavState entsprechen.","pt":"Habilita os agentes a estruturar componentes de interface do usuário e lógica de forma eficiente usando shared/src/commonMain/... para lógica de interface do usuário e ViewModel reutilizável, e app/src/main/java/... para integração de tempo de execução do Android, enquanto adere a contratos de roteamento existentes como Screen, NavDestination e NavState.","ru":"Позволяет агентам эффективно структурировать компоненты пользовательского интерфейса и логику, используя shared/src/commonMain/... для повторного использования логики пользовательского интерфейса и ViewModel, и app/src/main/java/... для интеграции с временем выполнения Android, при этом соблюдая существующие маршрутизационные контракты, такие как Screen, NavDestination и NavState.","ar":"تمكّن الوكلاء من تنظيم مكونات واجهة المستخدم ومنطقها بفعالية باستخدام shared/src/commonMain/... من أجل منطق واجهة المستخدم وViewModel القابل لإعادة الاستخدام، و app/src/main/java/... من أجل التكامل مع وقت تشغيل Android، مع الالتزام بالعقود التوجيهية الموجودة مثل الشاشة والوجهة والتوجيه والнавستيت."},"useCases":{"en":["Organizing reusable UI components in shared directories","Integrating Android runtime permissions and intents into UI architecture","Implementing navigation stacks using Screen, NavDestination, and NavState contracts"],"zh":["在共享目录中组织可重用的UI组件","将Android运行时权限和意图集成到UI架构中","使用Screen、NavDestination和NavState合约实现导航栈"],"ja":["共有ディレクトリで再利用可能なUIコンポーネントを組織する","Androidのランタイム権限と意図をUIアーキテクチャに統合する","Screen、NavDestination、NavState契約を使用してナビゲーションスタックを実装する"],"ko":["공유 디렉토리에서 재사용 가능한 UI 컴포넌트를 조직화하는 것","안드로이드 런타임 권한 및 의도를 UI 아키텍처에 통합하는 것","Screen, NavDestination, NavState 계약을 사용하여 네비게이션 스택을 구현하는 것"],"es":["Organizar componentes de interfaz de usuario reutilizables en directorios compartidos","Integrar permisos e intenciones de tiempo de ejecución de Android en la arquitectura de la interfaz de usuario","Implementar pilas de navegación utilizando contratos Screen, NavDestination y NavState"],"fr":["Organiser les composants d''interface utilisateur réutilisables dans des répertoires partagés","Intégrer les autorisations et les intentions de runtime Android dans l''architecture de l''interface utilisateur","Mettre en œuvre des piles de navigation en utilisant les contrats Screen, NavDestination et NavState"],"de":["Wiederverwendbare Benutzeroberflächenkomponenten in gemeinsamen Verzeichnissen organisieren","Android-Laufzeitberechtigungen und -intentionen in die Benutzeroberflächenarchitektur integrieren","Navigationsstapel mit Screen-, NavDestination- und NavState-Verträgen implementieren"],"pt":["Organizar componentes de interface do usuário reutilizáveis em diretórios compartilhados","Integrar permissões e intenções de tempo de execução do Android na arquitetura de interface do usuário","Implementar pilhas de navegação usando contratos Screen, NavDestination e NavState"],"ru":["Организация повторно используемых компонентов пользовательского интерфейса в общих директориях","Интеграция разрешений и интентов времени выполнения Android в архитектуру пользовательского интерфейса","Реализация навигационных стеков, используя контракты Screen, NavDestination и NavState"],"ar":["تنظيم مكونات واجهة المستخدم القابلة لإعادة الاستخدام في الدلائل المشتركة","تكامل أذونات ونية وقت تشغيل Android في هندسة واجهة المستخدم","تنفيذ أكوام التوجيه باستخدام عقود الشاشة والوجهة والتوجيه"]},"limitations":{"en":["Requires adherence to specific directory structures (shared/src/commonMain/... and app/src/main/java/...)","Android-specific, may not be directly applicable to other platforms"],"zh":["需要遵守特定的目录结构（shared/src/commonMain/...和app/src/main/java/...）","仅适用于Android，可能不直接适用于其他平台"],"ja":["特定のディレクトリ構造（shared/src/commonMain/...とapp/src/main/java/...）に従う必要がある","Android専用であり、他のプラットフォームには直接適用できない可能性がある"],"ko":["특정 디렉토리 구조(shared/src/commonMain/... 및 app/src/main/java/...)를 따라야 함","안드로이드専용으로, 다른 플랫폼에는 직접 적용할 수 없는可能性가 있음"],"es":["Requiere la adhesión a estructuras de directorios específicas (shared/src/commonMain/... y app/src/main/java/...)","Específico de Android, puede que no sea directamente aplicable a otras plataformas"],"fr":["Nécessite l''adhésion à des structures de répertoire spécifiques (shared/src/commonMain/... et app/src/main/java/...)","Spécifique à Android, peut ne pas être directement applicable à d''autres plateformes"],"de":["Erfordert die Einhaltung spezifischer Verzeichnisstrukturen (shared/src/commonMain/... und app/src/main/java/...)","Spezifisch für Android, kann möglicherweise nicht direkt auf andere Plattformen angewendet werden"],"pt":["Exige aderência a estruturas de diretório específicas (shared/src/commonMain/... e app/src/main/java/...)","Específico do Android, pode não ser diretamente aplicável a outras plataformas"],"ru":["Требует соблюдения определенных структур директорий (shared/src/commonMain/... и app/src/main/java/...)","Специфичен для Android, может не быть直接 применим к другим платформам"],"ar":["يتطلب الالتزام بهياكل دلائل محددة (shared/src/commonMain/... و app/src/main/java/...)","محدد لمنصة Android، قد لا يكون قابلا للتطبيق مباشرة على منصات أخرى"]},"version":4},"contentHash":"639a6dd84367460815462a50f4009db48003b2d9d0692bdbd9280ddd0f3a172f","qualityScore":52}');
