INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('FireworkSky/RotatingartLauncher/ui-architecture', 'ui-architecture', 'FireworkSky', 'RotatingartLauncher', 'community', 'ui-architecture FireworkSky RotatingartLauncher community The ui-architecture skill helps developers structure their UI components and logic. It provides guidelines for placing reusable UI and ViewModel logic in shared/src/commonMain/... and Android runtime integration in app/src/main/java/... UI架构是一种将UI逻辑和ViewModel逻辑分离的设计模式。它可以帮助开发者构建高效、可维护的UI UIアーキテクチャは、UIロジックとViewModelロジックを分離する設計パターンです。効率的なUIを構築するのに役立ちます UI 아키텍처는 UI 로직과 ViewModel 로직을 분리하는 디자인 패턴입니다. 효율적이고 유지 보수 가능한 UI를 구축하는 데 도움이 됩니다 La arquitectura de UI es fundamental para el desarrollo de aplicaciones móviles. Nuestra guía cubre la configuración de la arquitectura de UI para aplicaciones Android. L''architecture d''UI est essentielle pour le développement d''applications mobiles. Notre guide couvre la configuration de l''architecture d''UI pour les applications Android et les outils d''IA Die UI-Architektur ist für die Entwicklung mobiler Anwendungen von entscheidender Bedeutung. Unser Leitfaden behandelt die Einrichtung der UI-Architektur für Android-Anwendungen und KI-Tools A arquitetura de UI é fundamental para uma experiência do usuário agradável. Aprenda a estruturar seu projeto com nossas dicas Архитектура UI является основой для приятного пользовательского опыта. Узнайте, как cấu trúcровать свой проект с нашими советами هندسة واجهة المستخدم هي الأساس لتجربة المستخدم الممتعة. تعلم كيفية هيكلة مشروعك مع نصائحنا how to use ui-architecture ui-architecture setup guide ui-architecture vs material design what is ui-architecture ui-architecture install ui-architecture best practices ui-architecture for android ui-architecture navigation stack UI架构 AIエージェント UI设计模式 ViewModel Android运行时集成 路由管理 Screen NavDestination NavState Places reusable UI and ViewModel logic in shared/src/commonMain/... Handles Android runtime integration in app/src/main/java/... Confirms landscape constraints before layout work using manifest and base activity Follows existing routing contracts using Screen, NavDestination, and NavState Separates UI logic from Android runtime integration for better maintainability ui-architecture is a set of guidelines for structuring user interface components and logic in a scalable and maintainable way');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OmarHosamCodes/som-brain-turbo/zustand-patterns', 'community', 'OmarHosamCodes', 'som-brain-turbo', 'OmarHosamCodes/som-brain-turbo', 'zustand-patterns', 0, 0, 52, '2026-03-02T11:08:32Z', '2026-03-07T04:02:35.356Z', '607f3bafacee1e5b809680993d6d8e14404fd1c0f107de5ed288e02d6e329e69', '{"id":"OmarHosamCodes/som-brain-turbo/zustand-patterns","name":"zustand-patterns","description":{"en":"zustand-patterns provides modern state management with Zustand 5.x, enabling global state without Redux complexity. It benefits developers seeking lightweight, TypeScript-first solutions.","zh":"Zustand Patterns提供了现代的状态管理解决方案，支持全局状态、共享状态、持久化状态和计算状态","ja":"Zustand パターンは、グローバル状態、共有状態、永続化状態、計算状態をサポートするモダンな状態管理ソリューションを提供します","ko":"Zustand Patterns는 전역 상태, 공유 상태, 지속성 상태 및 계산 상태를 지원하는 현대적인 상태 관리 솔루션을 제공합니다","es":"Zustand Patterns es una biblioteca ligera para la administración de estado en aplicaciones JavaScript y TypeScript, sin la complejidad de Redux","fr":"Zustand Patterns est une bibliothèque légère pour la gestion d''état dans les applications JavaScript et TypeScript, sans la complexité de Redux","de":"Zustand Patterns ist eine leichte Bibliothek für die Zustandsverwaltung in JavaScript- und TypeScript-Anwendungen, ohne die Komplexität von Redux","pt":"O Zustand Patterns é uma biblioteca leve para gerenciamento de estado, com suporte a TypeScript e sem boilerplate","ru":"Шаблоны Zustand — это лёгкая библиотека для управления состоянием, с поддержкой TypeScript и без boilerplate","ar":"نمط Zustand هو مكتبة خفيفة لإدارة الحالة، مع دعم ل TypeScript وبدون كود زائد"},"seo":{"title":{"en":"zustand-patterns: Modern State Management Setup Guide | A...","zh":"Zustand Patterns Setup Guide - Modern State Management","ja":"Zustand パターン設定ガイド - モダンな状態管理","ko":"Zustand Patterns 설정 가이드 - 현대적인 상태 관리","es":"Guía de Configuración de Zustand Patterns para Administra...","fr":"Mise en Route de Zustand Patterns pour la Gestion d''État","de":"Einrichtungsleitfaden für Zustand Patterns zur Zustandsve...","pt":"Guia de Configuração do Zustand Patterns para Gerenciamen...","ru":"Настройка шаблонов Zustand для современного управления со...","ar":"إعداد نمط Zustand لتخزين الحالة الحديثة"},"description":{"en":"Discover how to simplify global state management with Zustand 5.x. Learn patterns for shared state, persisted state, and computed state. Get started now!","zh":"使用Zustand Patterns实现轻量级、TypeScript优先的状态管理，无需复杂的Redux配置","ja":"Zustand パターンを使用して、軽量でTypeScript優先の状態管理を実現します。Reduxの複雑な設定は不要です","ko":"Zustand Patterns를 사용하여 가벼운 TypeScript 우선 상태 관리를 구현합니다. Redux의 복잡한 설정이 필요 없습니다","es":"Aprende a implementar Zustand Patterns para una administración de estado moderna y ligera en tus aplicaciones con TypeScript y JavaScript","fr":"Découvrez comment mettre en œuvre des modèles de Zustand pour une gestion d''état moderne et légère dans vos applications avec TypeScript et JavaScript","de":"Erfahren Sie, wie Sie Zustand Patterns für eine moderne und leichte Zustandsverwaltung in Ihren Anwendungen mit TypeScript und JavaScript implementieren","pt":"Aprenda a usar o Zustand Patterns para gerenciar estado em aplicativos com TypeScript, sem complexidade do Redux","ru":"Узнайте, как использовать шаблоны Zustand для управления состоянием в приложениях с TypeScript, без сложности Redux","ar":"تعلم كيفية استخدام نمط Zustand لإدارة الحالة في التطبيقات مع TypeScript، بدون تعقيدات Redux"},"definition":{"en":"zustand-patterns is a state management approach using Zustand 5.x, offering features like global state, shared state, and computed state with TypeScript support.","zh":"Zustand Patterns是一种现代的状态管理方法，使用Zustand 5.x实现轻量级和TypeScript优先的状态管理","ja":"Zustand パターンは、Zustand 5.xを使用して軽量でTypeScript優先の状態管理を実現するモダンな状態管理方法です","ko":"Zustand Patterns는 Zustand 5.x를 사용하여 가벼운 TypeScript 우선 상태 관리를 구현하는 현대적인 상태 관리 방법입니다","es":"Zustand Patterns es un patrón de diseño para la administración de estado en aplicaciones, que proporciona una forma ligera y sencilla de gestionar el estado","fr":"Zustand Patterns est un motif de conception pour la gestion d''état dans les applications, qui offre une façon légère et simple de gérer l''état","de":"Zustand Patterns ist ein Entwurfsmuster für die Zustandsverwaltung in Anwendungen, das eine leichte und einfache Möglichkeit zur Verwaltung des Zustands bietet","pt":"O que é Zustand Patterns? É uma biblioteca para gerenciamento de estado moderno com TypeScript","ru":"Что такое шаблоны Zustand? Это библиотека для современного управления состоянием с TypeScript","ar":"ما هو نمط Zustand؟ هو مكتبة لإدارة الحالة الحديثة مع TypeScript"},"features":{"en":["Global state management without Redux complexity","Shared state across components without prop drilling","Persisted state with localStorage/sessionStorage","Computed/derived state with selectors","Support for middleware like logging, devtools, and persistence"],"zh":["全局状态管理","共享状态管理","持久化状态管理","计算状态管理","支持TypeScript"],"ja":["グローバル状態管理","共有状態管理","永続化状態管理","計算状態管理","TypeScriptサポート"],"ko":["전역 상태 관리","공유 상태 관리","지속성 상태 관리","계산 상태 관리","TypeScript 지원"],"es":["Almacenamiento de estado global sin la complejidad de Redux","Compartir estado entre componentes sin drilling de props","Estado persistente con localStorage y sessionStorage","Estado computado y derivado con selectores","Soporte para middleware como registro y herramientas de desarrollo"],"fr":["Stockage d''état global sans la complexité de Redux","Partage d''état entre les composants sans forage de props","État persistant avec localStorage et sessionStorage","État calculé et dérivé avec des sélecteurs","Prise en charge du middleware comme la journalisation et les outils de développement"],"de":["Globale Zustandsverwaltung ohne die Komplexität von Redux","Zustand teilen zwischen Komponenten ohne Prop-Drilling","Persistenter Zustand mit localStorage und sessionStorage","Berechneter und abgeleiteter Zustand mit Selektoren","Unterstützung für Middleware wie Protokollierung und Entwicklungstools"],"pt":["Gerenciamento de estado global sem complexidade do Redux","Compartilhamento de estado entre componentes sem prop drilling","Persistência de estado com localStorage e sessionStorage","Estado computado com seletores","Suporte a middleware para logging, devtools e persistência"],"ru":["Глобальное управление состоянием без сложности Redux","Обмен состоянием между компонентами без prop drilling","Сохранение состояния с помощью localStorage и sessionStorage","Вычисленное состояние с помощью селекторов","Поддержка middleware для логирования, devtools и сохранения"],"ar":["إدارة الحالة العالمية بدون تعقيدات Redux","مشاركة الحالة بين المكونات بدون حفر الممتلكات","استمرار الحالة مع localStorage وsessionStorage","حالة محسوبة مع محددي الخواص","دعم وسيطات التخزين المؤقت للتسجيل، والأدوات التطويرية والاستمرار"]},"keywords":{"en":["how to use zustand-patterns","zustand-patterns vs Redux","zustand-patterns setup guide","what is zustand-patterns","zustand-patterns install","zustand-patterns alternative","zustand 5.x tutorial","TypeScript state management","modern state management patterns"],"zh":["Zustand Patterns","状态管理","TypeScript","轻量级状态管理","现代状态管理","AIエージェント工具","状态管理解决方案"],"ja":["Zustand パターン","状態管理","TypeScript","軽量状態管理","モダンな状態管理","AIエージェント","状態管理ソリューション"],"ko":["Zustand Patterns","상태 관리","TypeScript","가벼운 상태 관리","현대적인 상태 관리","AI 에이전트","상태 관리 솔루션"],"es":["zustand patterns","administración de estado","typescript","javascript","redux","estado global","compartir estado","estado persistente","selectores","middleware"],"fr":["zustand patterns","gestion d''état","typescript","javascript","redux","état global","partage d''état","état persistant","sélecteurs","middleware"],"de":["zustand patterns","zustandsverwaltung","typescript","javascript","redux","globale zustandsverwaltung","zustand teilen","persistenter zustand","selektoren","middleware"],"pt":["zustand patterns","gerenciamento de estado","typescript","react","estado global","compartilhamento de estado","persistência de estado","middleware","logging","devtools"],"ru":["шаблоны zustand","управление состоянием","typescript","react","глобальное состояние","обмен состоянием","сохранение состояния","middleware","логирование","devtools"],"ar":["نمط zustand","إدارة الحالة","typescript","react","حالة عالمية","مشاركة الحالة","استمرار الحالة","وسيطات التخزين المؤقت","التسجيل","أدوات التطوير"]}},"owner":"OmarHosamCodes","repo":"som-brain-turbo","repoPath":"OmarHosamCodes/som-brain-turbo","stars":0,"forks":0,"updatedAt":"2026-03-02T11:08:32Z","topics":[],"category":"community","skillMd":{"name":"zustand-patterns","description":"Zustand 5.x state management with slices, middleware, Immer, useShallow, and persistence patterns for React applications. Use when building state management with Zustand.","version":"1.0.0","tags":["zustand","state-management","react","immer","middleware","persistence","slices"],"bodyPreview":"# Zustand Patterns\n\nModern state management with Zustand 5.x - lightweight, TypeScript-first, no boilerplate.\n\n## Overview\n\n- Global state without Redux complexity\n- Shared state across components without prop drilling\n- Persisted state with localStorage/sessionStorage\n- Computed/derived state with selectors\n- State that needs middleware (logging, devtools, persistence)\n\n## Core Patterns\n\n### 1. Basic Store with TypeScript\n\n```typescript\nimport { create } from ''zustand'';\n\ninterface BearState {","body":"# Zustand Patterns\n\nModern state management with Zustand 5.x - lightweight, TypeScript-first, no boilerplate.\n\n## Overview\n\n- Global state without Redux complexity\n- Shared state across components without prop drilling\n- Persisted state with localStorage/sessionStorage\n- Computed/derived state with selectors\n- State that needs middleware (logging, devtools, persistence)\n\n## Core Patterns\n\n### 1. Basic Store with TypeScript\n\n```typescript\nimport { create } from ''zustand'';\n\ninterface BearState {\n  bears: number;\n  increase: (by: number) => void;\n  reset: () => void;\n}\n\nconst useBearStore = create<BearState>()((set) => ({\n  bears: 0,\n  increase: (by) => set((state) => ({ bears: state.bears + by })),\n  reset: () => set({ bears: 0 }),\n}));\n```\n\n### 2. Slices Pattern (Modular Stores)\n\n```typescript\nimport { create, StateCreator } from ''zustand'';\n\n// Auth slice\ninterface AuthSlice {\n  user: User | null;\n  login: (user: User) => void;\n  logout: () => void;\n}\n\nconst createAuthSlice: StateCreator<AuthSlice & CartSlice, [], [], AuthSlice> = (set) => ({\n  user: null,\n  login: (user) => set({ user }),\n  logout: () => set({ user: null }),\n});\n\n// Cart slice\ninterface CartSlice {\n  items: CartItem[];\n  addItem: (item: CartItem) => void;\n  clearCart: () => void;\n}\n\nconst createCartSlice: StateCreator<AuthSlice & CartSlice, [], [], CartSlice> = (set) => ({\n  items: [],\n  addItem: (item) => set((state) => ({ items: [...state.items, item] })),\n  clearCart: () => set({ items: [] }),\n});\n\n// Combined store\nconst useStore = create<AuthSlice & CartSlice>()((...a) => ({\n  ...createAuthSlice(...a),\n  ...createCartSlice(...a),\n}));\n```\n\n### 3. Immer Middleware (Immutable Updates)\n\n```typescript\nimport { create } from ''zustand'';\nimport { immer } from ''zustand/middleware/immer'';\n\ninterface TodoState {\n  todos: Todo[];\n  addTodo: (text: string) => void;\n  toggleTodo: (id: string) => void;\n  updateNested: (id: string, subtaskId: string, done: boolean) => void;\n}\n\nconst useTodoStore = create<TodoState>()(\n  immer((set) => ({\n    todos: [],\n    addTodo: (text) =>\n      set((state) => {\n        state.todos.push({ id: crypto.randomUUID(), text, done: false });\n      }),\n    toggleTodo: (id) =>\n      set((state) => {\n        const todo = state.todos.find((t) => t.id === id);\n        if (todo) todo.done = !todo.done;\n      }),\n    updateNested: (id, subtaskId, done) =>\n      set((state) => {\n        const todo = state.todos.find((t) => t.id === id);\n        const subtask = todo?.subtasks?.find((s) => s.id === subtaskId);\n        if (subtask) subtask.done = done;\n      }),\n  }))\n);\n```\n\n### 4. Persist Middleware\n\n```typescript\nimport { create } from ''zustand'';\nimport { persist, createJSONStorage } from ''zustand/middleware'';\n\ninterface SettingsState {\n  theme: ''light'' | ''dark'';\n  language: string;\n  setTheme: (theme: ''light'' | ''dark'') => void;\n}\n\nconst useSettingsStore = create<SettingsState>()(\n  persist(\n    (set) => ({\n      theme: ''light'',\n      language: ''en'',\n      setTheme: (theme) => set({ theme }),\n    }),\n    {\n      name: ''settings-storage'',\n      storage: createJSONStorage(() => localStorage),\n      partialize: (state) => ({ theme: state.theme }), // Only persist theme\n      version: 1,\n      migrate: (persisted, version) => {\n        if (version === 0) {\n          // Migration logic\n        }\n        return persisted as SettingsState;\n      },\n    }\n  )\n);\n```\n\n### 5. Selectors (Prevent Re-renders)\n\n```typescript\n// ❌ BAD: Re-renders on ANY state change\nconst { bears, fish } = useBearStore();\n\n// ✅ GOOD: Only re-renders when bears changes\nconst bears = useBearStore((state) => state.bears);\n\n// ✅ GOOD: Shallow comparison for objects (Zustand 5.x)\nimport { useShallow } from ''zustand/react/shallow'';\n\nconst { bears, fish } = useBearStore(\n  useShallow((state) => ({ bears: state.bears, fish: state.fish }))\n);\n\n// ✅ GOOD: Computed/derived state via selector\nconst totalAnimals = useBearStore((state) => state.bears + state.fish);\n\n// ❌ BAD: Storing computed state\nconst useStore = create((set) => ({\n  items: [],\n  total: 0, // Don''t store derived values!\n  addItem: (item) => set((s) => ({\n    items: [...s.items, item],\n    total: s.total + item.price, // Sync issues!\n  })),\n}));\n\n// ✅ GOOD: Compute in selector\nconst total = useStore((s) => s.items.reduce((sum, i) => sum + i.price, 0));\n```\n\n### 6. Async Actions\n\n```typescript\ninterface UserState {\n  user: User | null;\n  loading: boolean;\n  error: string | null;\n  fetchUser: (id: string) => Promise<void>;\n}\n\nconst useUserStore = create<UserState>()((set) => ({\n  user: null,\n  loading: false,\n  error: null,\n  fetchUser: async (id) => {\n    set({ loading: true, error: null });\n    try {\n      const user = await api.getUser(id);\n      set({ user, loading: false });\n    } catch (error) {\n      set({ error: error.message, loading: false });\n    }\n  },\n}));\n```\n\n### 7. DevTools Integration\n\n```typescript\nimport { create } from ''zustand'';\nimport { devtools } from ''zustand/middleware'';\n\nconst useStore = create<State>()(\n  devtools(\n    (set) => ({\n      // ... state and actions\n    }),\n    { name: ''MyStore'', enabled: process.env.NODE_ENV === ''development'' }\n  )\n);\n```\n\n## Quick Reference\n\n```typescript\n// ✅ Create typed store with double-call pattern\nconst useStore = create<State>()((set, get) => ({ ... }));\n\n// ✅ Use selectors for all state access\nconst count = useStore((s) => s.count);\n\n// ✅ Use useShallow for multiple values (Zustand 5.x)\nconst { a, b } = useStore(useShallow((s) => ({ a: s.a, b: s.b })));\n\n// ✅ Middleware order: immer → subscribeWithSelector → devtools → persist\ncreate(persist(devtools(immer((set) => ({ ... })))))\n\n// ❌ Never destructure entire store\nconst store = useStore(); // Re-renders on ANY change\n\n// ❌ Never store server state (use TanStack Query instead)\nconst useStore = create((set) => ({ users: [], fetchUsers: async () => ... }));\n```\n\n## Key Decisions\n\n| Decision | Option A | Option B | Recommendation |\n|----------|----------|----------|----------------|\n| State structure | Single store | Multiple stores | **Slices in single store** - easier cross-slice access |\n| Nested updates | Spread operator | Immer middleware | **Immer** for deeply nested state (3+ levels) |\n| Persistence | Manual localStorage | persist middleware | **persist middleware** with partialize |\n| Multiple values | Multiple selectors | useShallow | **useShallow** for 2-5 related values |\n| Server state | Zustand | TanStack Query | **TanStack Query** - Zustand for client-only state |\n| DevTools | Always on | Conditional | **Conditional** - `enabled: process.env.NODE_ENV === ''development''` |\n\n## Anti-Patterns (FORBIDDEN)\n\n```typescript\n// ❌ FORBIDDEN: Destructuring entire store\nconst { count, increment } = useStore(); // Re-renders on ANY state change\n\n// ❌ FORBIDDEN: Storing derived/computed state\nconst useStore = create((set) => ({\n  items: [],\n  total: 0, // Will get out of sync!\n}));\n\n// ❌ FORBIDDEN: Storing server state\nconst useStore = create((set) => ({\n  users: [], // Use TanStack Query instead\n  fetchUsers: async () => { ... },\n}));\n\n// ❌ FORBIDDEN: Mutating state without Immer\nset((state) => {\n  state.items.push(item); // Breaks reactivity!\n  return state;\n});\n\n// ❌ FORBIDDEN: Using deprecated shallow import\nimport { shallow } from ''zustand/shallow''; // Use useShallow from zustand/react/shallow\n```\n\n## Integration with React Query\n\n```typescript\n// ✅ Zustand for CLIENT state (UI, preferences, local-only)\nconst useUIStore = create<UIState>()((set) => ({\n  sidebarOpen: false,\n  theme: ''light'',\n  toggleSidebar: () => set((s) => ({ sidebarOpen: !s.sidebarOpen })),\n}));\n\n// ✅ TanStack Query for SERVER state (API data)\nfunction Dashboard() {\n  const sidebarOpen = useUIStore((s) => s.sidebarOpen);\n  const { data: users } = useQuery({ queryKey: [''users''], queryFn: fetchUsers });\n  // Zustand: UI state | TanStack Query: server data\n}\n```\n\n## Related Skills\n\n- `tanstack-query-advanced` - Server state management (use with Zustand for client state)\n- `form-state-patterns` - Form state (React Hook Form vs Zustand for forms)\n- `react-server-components-framework` - RSC hydration considerations with Zustand\n\n## Capability Details\n\n### store-creation\n**Keywords**: zustand, create, store, typescript, state\n**Solves**: Setting up type-safe Zustand stores with proper TypeScript inference\n\n### slices-pattern\n**Keywords**: slices, modular, split, combine, StateCreator\n**Solves**: Organizing large stores into maintainable, domain-specific slices\n\n### middleware-stack\n**Keywords**: immer, persist, devtools, middleware, compose\n**Solves**: Combining middleware in correct order for immutability, persistence, and debugging\n\n### selector-optimization\n**Keywords**: selector, useShallow, re-render, performance, memoization\n**Solves**: Preventing unnecessary re-renders with proper selector patterns\n\n### persistence-migration\n**Keywords**: persist, localStorage, sessionStorage, migrate, version\n**Solves**: Persisting state with schema migrations between versions\n\n## References\n\n- `references/middleware-composition.md` - Combining multiple middleware\n- `scripts/store-template.ts` - Production-ready store template\n- `checklists/zustand-checklist.md` - Implementation checklist\n"},"lastSynced":"2026-03-07T04:02:35.356Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing lightweight state management with TypeScript support.","zh":"非常适合需要轻量级状态管理和TypeScript支持的前端代理。","ja":"フロントエンドエージェントがTypeScriptをサポートした軽量な状態管理を必要とする場合に最適です。","ko":"타입스크립트 지원과 가벼운 상태 관리가 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para agentes Frontend que necesitan una gestión de estado ligera con soporte para TypeScript.","fr":"Parfait pour les agents Frontend nécessitant une gestion d''état légère avec prise en charge de TypeScript.","de":"Perfekt für Frontend-Agents, die eine leichte Zustandsverwaltung mit TypeScript-Unterstützung benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de gerenciamento de estado leve com suporte ao TypeScript.","ru":"Идеально для фронтенд-агентов, которым требуется легкое управление состоянием с поддержкой TypeScript.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى إدارة الحالة الخفيفة مع دعم TypeScript."},"recommendation":{"en":"Empowers agents to manage global state without Redux complexity, utilizing Zustand 5.x for shared state across components, persisted state with localStorage/sessionStorage, and computed/derived state with selectors.","zh":"赋予代理管理全局状态的能力，而无需Redux的复杂性，利用Zustand 5.x实现组件间的共享状态、localStorage/sessionStorage的持久化状态以及选择器的计算/派生状态。","ja":"Reduxの複雑さなしに、エージェントがグローバル状態を管理できるようにします。Zustand 5.xを使用して、コンポーネント間の共有状態、localStorage/sessionStorageの永続化状態、およびセレクターの計算/派生状態を実現します。","ko":"리덕스의 복잡성 없이 에이전트가 전역 상태를 관리할 수 있도록 합니다. Zustand 5.x를 사용하여 컴포넌트 간의 공유 상태, localStorage/sessionStorage의 지속성 상태 및 선택기(computed/derived state)를 구현합니다.","es":"Habilita a los agentes a gestionar el estado global sin la complejidad de Redux, utilizando Zustand 5.x para el estado compartido entre componentes, estado persistente con localStorage/sessionStorage y estado calculado/derivado con selectores.","fr":"Permet aux agents de gérer l''état global sans la complexité de Redux, en utilisant Zustand 5.x pour l''état partagé entre les composants, l''état persistant avec localStorage/sessionStorage et l''état calculé/dérivé avec des sélecteurs.","de":"Ermöglicht es Agenten, den globalen Zustand ohne die Komplexität von Redux zu verwalten, indem Zustand 5.x für den gemeinsam genutzten Zustand zwischen Komponenten, den persistenten Zustand mit localStorage/sessionStorage und den berechneten/abgeleiteten Zustand mit Selektoren verwendet wird.","pt":"Habilita os agentes a gerenciar o estado global sem a complexidade do Redux, utilizando o Zustand 5.x para estado compartilhado entre componentes, estado persistido com localStorage/sessionStorage e estado computado/derivado com seletores.","ru":"Наделяет агентов возможностью управлять глобальным состоянием без сложности Redux, используя Zustand 5.x для общего состояния между компонентами, сохраненного состояния с localStorage/sessionStorage и вычисленного/производного состояния с селекторами.","ar":"تمكّن الوكلاء من إدارة الحالة العالمية دون تعقيد Redux، باستخدام Zustand 5.x للحالة المشتركة بين المكونات، والحالة المخزنة باستخدام localStorage/sessionStorage، والحالة المحسوبة/المشتقة مع محدّدات الاختيار."},"useCases":{"en":["Managing global state across components","Implementing persisted state with localStorage/sessionStorage","Creating computed/derived state with selectors"],"zh":["管理组件间的全局状态","使用localStorage/sessionStorage实现持久化状态","使用选择器创建计算/派生状态"],"ja":["コンポーネント間のグローバル状態を管理する","localStorage/sessionStorageを使用した永続化状態の実現","セレクターを使用した計算/派生状態の作成"],"ko":["컴포넌트 간의 전역 상태 관리","localStorage/sessionStorage를 사용한 지속성 상태 구현","선택기를 사용한 계산/파생 상태 생성"],"es":["Gestionar el estado global entre componentes","Implementar estado persistente con localStorage/sessionStorage","Crear estado calculado/derivado con selectores"],"fr":["Gérer l''état global entre les composants","Mettre en œuvre un état persistant avec localStorage/sessionStorage","Créer un état calculé/dérivé avec des sélecteurs"],"de":["Globalen Zustand zwischen Komponenten verwalten","Persistenten Zustand mit localStorage/sessionStorage implementieren","Berechneten/abgeleiteten Zustand mit Selektoren erstellen"],"pt":["Gerenciar estado global entre componentes","Implementar estado persistido com localStorage/sessionStorage","Criar estado computado/derivado com seletores"],"ru":["Управлять глобальным состоянием между компонентами","Реализовать сохраненное состояние с localStorage/sessionStorage","Создать вычисленное/производное состояние с селекторами"],"ar":["إدارة الحالة العالمية بين المكونات","تنفيذ الحالة المخزنة باستخدام localStorage/sessionStorage","إنشاء الحالة المحسوبة/المشتقة مع محدّدات الاختيار"]},"limitations":{"en":["Requires Zustand 5.x","TypeScript-first approach may require additional setup for non-TypeScript projects"],"zh":["需要Zustand 5.x","基于TypeScript的方法可能需要为非TypeScript项目进行额外的设置"],"ja":["Zustand 5.xが必要","TypeScriptを第一に考えたアプローチにより、非TypeScriptプロジェクトでは追加の設定が必要になる可能性がある"],"ko":["Zustand 5.x 필요","타입스크립트 우선 접근 방식으로 인해 비타입스크립트 프로젝트에서는 추가 설정이 필요할 수 있음"],"es":["Requiere Zustand 5.x","El enfoque de TypeScript primero puede requerir una configuración adicional para proyectos que no utilizan TypeScript"],"fr":["Nécessite Zustand 5.x","L''approche TypeScript première peut nécessiter une configuration supplémentaire pour les projets qui n''utilisent pas TypeScript"],"de":["Benötigt Zustand 5.x","Der TypeScript-erst-Ansatz kann für nicht-TypeScript-Projekte eine zusätzliche Einrichtung erfordern"],"pt":["Requer Zustand 5.x","Abordagem TypeScript-first pode exigir configuração adicional para projetos não-TypeScript"],"ru":["Требует Zustand 5.x","Подход TypeScript-first может потребовать дополнительной настройки для проектов не на TypeScript"],"ar":["يتطلب Zustand 5.x","النهج TypeScript-first قد يتطلب إعدادات إضافية لمشاريع غير TypeScript"]},"version":4},"contentHash":"607f3bafacee1e5b809680993d6d8e14404fd1c0f107de5ed288e02d6e329e69","qualityScore":52}');
