INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OmarHosamCodes/som-brain-turbo/zustand-patterns', 'zustand-patterns', 'OmarHosamCodes', 'som-brain-turbo', 'community', 'zustand-patterns OmarHosamCodes som-brain-turbo community zustand-patterns provides modern state management with Zustand 5.x, enabling global state without Redux complexity. It benefits developers seeking lightweight, TypeScript-first solutions. Zustand Patterns提供了现代的状态管理解决方案，支持全局状态、共享状态、持久化状态和计算状态 Zustand パターンは、グローバル状態、共有状態、永続化状態、計算状態をサポートするモダンな状態管理ソリューションを提供します Zustand Patterns는 전역 상태, 공유 상태, 지속성 상태 및 계산 상태를 지원하는 현대적인 상태 관리 솔루션을 제공합니다 Zustand Patterns es una biblioteca ligera para la administración de estado en aplicaciones JavaScript y TypeScript, sin la complejidad de Redux Zustand Patterns est une bibliothèque légère pour la gestion d''état dans les applications JavaScript et TypeScript, sans la complexité de Redux Zustand Patterns ist eine leichte Bibliothek für die Zustandsverwaltung in JavaScript- und TypeScript-Anwendungen, ohne die Komplexität von Redux O Zustand Patterns é uma biblioteca leve para gerenciamento de estado, com suporte a TypeScript e sem boilerplate Шаблоны Zustand — это лёгкая библиотека для управления состоянием, с поддержкой TypeScript и без boilerplate نمط Zustand هو مكتبة خفيفة لإدارة الحالة، مع دعم ل TypeScript وبدون كود زائد how to use zustand-patterns zustand-patterns vs Redux zustand-patterns setup guide what is zustand-patterns zustand-patterns install zustand-patterns alternative zustand 5.x tutorial TypeScript state management modern state management patterns Zustand Patterns 状态管理 TypeScript 轻量级状态管理 现代状态管理 AIエージェント工具 状态管理解决方案 Global state management without Redux complexity Shared state across components without prop drilling Persisted state with localStorage/sessionStorage Computed/derived state with selectors Support for middleware like logging, devtools, and persistence zustand-patterns is a state management approach using Zustand 5.x, offering features like global state, shared state, and computed state with TypeScript support.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pelan05/vscode_agents_folder/seo-audit', 'community', 'pelan05', 'vscode_agents_folder', 'pelan05/vscode_agents_folder', 'seo-audit', 0, 0, 52, '2026-03-08T01:57:15.289Z', '2026-03-08T02:01:00.215Z', '51fdd3616ae1dd1209e0f7344582e76bed640c182118df9824859470249031d7', '{"id":"pelan05/vscode_agents_folder/seo-audit","name":"seo-audit","description":{"en":"The seo-audit skill helps developers identify SEO issues and provides recommendations to improve organic search performance. It supports site context analysis and product marketing context review.","zh":"SEO 审计是使用 AI エージェント来识别和解决网站的 SEO 问题，提高搜索引擎排名","ja":"SEO オーディットは、AIエージェントを使用してウェブサイトの SEO 問題を特定し、解決して検索エンジンランキングを向上させることです","ko":"SEO 감사는 AI 에이전트를 사용하여 웹사이트의 SEO 문제를 식별하고 해결하여 검색 엔진 순위를 개선하는 것입니다","es":"El audit de SEO identifica problemas y proporciona recomendaciones para mejorar el rendimiento de búsqueda orgánica. Se utiliza con herramientas de AI para analizar sitios web.","fr":"L''audit SEO identifie les problèmes et fournit des recommandations pour améliorer les performances de recherche organique. Il utilise des outils d''IA pour analyser les sites web.","de":"Das SEO-Audit identifiziert Probleme und liefert Empfehlungen, um die Leistung der organischen Suche zu verbessern. Es verwendet KI-Tools, um Websites zu analysieren.","pt":"O seo-audit é uma ferramenta para identificar problemas de SEO e fornecer recomendações para melhorar o desempenho orgânico","ru":"ИИ Агенты дляseo-audit предназначены для выявления проблем SEO и предоставления рекомендаций для улучшения позиций сайта","ar":"seo-audit هي أداة لتحليل وتحسين أداء موقعك على محركات البحث"},"seo":{"title":{"en":"seo-audit: Technical SEO Audit Setup Guide | AI Agent Skill","zh":"SEO 审计设置指南 - AI エージェント","ja":"SEO オーディットベストプラクティス - AIエージェント","ko":"SEO 감사 설정 가이드 - AI 에이전트","es":"Guía de configuración para SEO Audit con herramientas de AI","fr":"Guide de configuration pour l''audit SEO avec des outils d''IA","de":"Einrichtungsleitfaden für SEO-Audit mit KI-Tools","pt":"Guia de Configuração do seo-audit para Otimização de Sites","ru":"Настройка ИИ Агентов дляseo-audit: Руководство","ar":"إعداد وتشغيل seo-audit لتحسين محركات البحث"},"description":{"en":"Unlock actionable SEO recommendations with the seo-audit skill. Discover how to identify issues and boost organic search performance - get started now!","zh":"了解如何使用 AI エージェント进行 SEO 审计，提高您的网站在搜索引擎中的排名","ja":"AIエージェントを使用してSEOオーディットを実行し、ウェブサイトの検索エンジンランキングを向上させる方法について学びます","ko":"AI 에이전트를 사용하여 SEO 감사를 수행하고 웹사이트의 검색 엔진 순위를 개선하는 방법을 알아보세요","es":"Mejora el rendimiento de búsqueda orgánica con nuestro audit de SEO y herramientas de AI. Descubre problemas y soluciones para tu sitio web.","fr":"Améliorez les performances de recherche organique avec notre audit SEO et des outils d''IA. Découvrez les problèmes et les solutions pour votre site web.","de":"Verbessern Sie die Leistung der organischen Suche mit unserem SEO-Audit und KI-Tools. Entdecken Sie Probleme und Lösungen für Ihre Website.","pt":"Aprenda a realizar auditorias de SEO com o seo-audit e melhore o desempenho dos sites em motores de busca","ru":"Используйте ИИ Агенты дляseo-audit, чтобы выявить проблемы SEO и улучшить позиции сайта","ar":"استخدم seo-audit لتحليل أداء موقعك على محركات البحث و تحسينه"},"definition":{"en":"seo-audit is a technical skill that analyzes site context and product marketing context to identify SEO issues and provide actionable recommendations.","zh":"SEO 审计是使用 AI エージェント来分析和改进网站的搜索引擎优化","ja":"SEO オーディットは、AIエージェントを使用してウェブサイトの検索エンジン最適化を分析し、改善することです","ko":"SEO 감사는 AI 에이전트를 사용하여 웹사이트의 검색 엔진 최적화를 분석하고 개선하는 것입니다","es":"Un audit de SEO es un análisis exhaustivo de un sitio web para identificar problemas de optimización y mejorar su visibilidad en los motores de búsqueda.","fr":"Un audit SEO est une analyse exhaustive d''un site web pour identifier les problèmes d''optimisation et améliorer sa visibilité dans les moteurs de recherche.","de":"Ein SEO-Audit ist eine umfassende Analyse einer Website, um Optimierungsprobleme zu identifizieren und ihre Sichtbarkeit in Suchmaschinen zu verbessern.","pt":"O que é seo-audit? É uma ferramenta de auditoria de SEO para identificar problemas e melhorar o desempenho","ru":"Что такое ИИ Агенты дляseo-audit? Это инструмент для выявления проблем SEO и улучшения позиций сайта","ar":"ما هي seo-audit؟ هي أداة لتحليل وتحسين أداء موقعك على محركات البحث"},"features":{"en":["Checks for product marketing context in .claude/product-marketing-context.md files","Analyzes site context to understand site type and specific requirements","Provides actionable recommendations to improve organic search performance","Supports initial assessment and site context review","Utilizes information from forked repos, mainly the ''agents'' repo"],"zh":["识别网站的 SEO 问题","提供可行的 SEO 推荐","支持多种网站类型","使用 .claude/product-marketing-context.md 文件来了解网站背景","检查网站的 site context 和 product marketing context","使用 AI エージェント来提高搜索引擎排名"],"ja":["ウェブサイトの SEO 問題を特定","SEO 推薦を提供","複数のウェブサイトタイプをサポート",".claude/product-marketing-context.md ファイルを使用してウェブサイトの背景を理解","ウェブサイトの site context と product marketing context を確認","AIエージェントを使用して検索エンジンランキングを向上させる"],"ko":["웹사이트의 SEO 문제를 식별","SEO 추천을 제공","여러 가지 웹사이트 유형을 지원",".claude/product-marketing-context.md 파일을 사용하여 웹사이트의 배경을 이해","웹사이트의 site context 와 product marketing context 를 확인","AI 에이전트를 사용하여 검색 엔진 순위를 개선"],"es":["Análisis de contexto de sitio web","Identificación de problemas de optimización","Recomendaciones para mejorar el rendimiento de búsqueda orgánica","Uso de herramientas de AI para analizar sitios web","Verificación de la existencia de .claude/product-marketing-context.md"],"fr":["Analyse du contexte du site web","Identification des problèmes d''optimisation","Recommandations pour améliorer les performances de recherche organique","Utilisation d''outils d''IA pour analyser les sites web","Vérification de l''existence de .claude/product-marketing-context.md"],"de":["Analyse des Kontexts der Website","Identifizierung von Optimierungsproblemen","Empfehlungen zur Verbesserung der Leistung der organischen Suche","Verwendung von KI-Tools zur Analyse von Websites","Überprüfung der Existenz von .claude/product-marketing-context.md"],"pt":["Análise de contexto do site","Verificação de marketing de produtos","Identificação de problemas de SEO","Fornecimento de recomendações para melhorar o desempenho orgânico","Leitura de arquivos de contexto de marketing de produtos","Análise de tipo de site"],"ru":["Анализ контекста сайта","Проверка маркетинга продукта","Выявление проблем SEO","Предоставление рекомендаций для улучшения позиций сайта","Чтение файлов контекста маркетинга продукта","Анализ типа сайта"],"ar":["تحليل سياق الموقع","فحص تسويق المنتجات","تحديد مشاكل تحسين محركات البحث","توفير توصيات لتحسين الأداء العضوي","قراءة ملفات سياق تسويق المنتجات","تحليل نوع الموقع"]},"keywords":{"en":["how to use seo-audit","what is seo-audit","seo-audit alternative","seo-audit vs ahrefs","seo-audit install","seo-audit setup guide","seo audit tools","technical seo audit","seo audit for developers"],"zh":["SEO 审计","AI エージェント","搜索引擎优化","网站排名","SEO 问题","网站分析","AI 工具","搜索引擎排名","网站优化"],"ja":["SEO オーディット","AIエージェント","検索エンジン最適化","ウェブサイトランキング","SEO 問題","ウェブサイト分析","AI ツール","検索エンジンランキング","ウェブサイト最適化"],"ko":["SEO 감사","AI 에이전트","검색 엔진 최적화","웹사이트 순위","SEO 문제","웹사이트 분석","AI 도구","검색 엔진 순위","웹사이트 최적화"],"es":["audit de SEO","herramientas de AI","optimización de sitio web","mejora del rendimiento de búsqueda orgánica","análisis de contexto de sitio web","identificación de problemas de optimización","recomendaciones para mejorar la visibilidad en los motores de búsqueda"],"fr":["audit SEO","outils d''IA","optimisation de site web","amélioration des performances de recherche organique","analyse du contexte du site web","identification des problèmes d''optimisation","recommandations pour améliorer la visibilité dans les moteurs de recherche"],"de":["SEO-Audit","KI-Tools","Optimierung von Websites","Verbesserung der Leistung der organischen Suche","Analyse des Kontexts der Website","Identifizierung von Optimierungsproblemen","Empfehlungen zur Verbesserung der Sichtbarkeit in Suchmaschinen"],"pt":["seo-audit","otimização de sites","auditoria de SEO","melhoria de desempenho orgânico","análise de contexto do site","marketing de produtos","problemas de SEO","recomendações para melhorar o desempenho","ferramentas de SEO","otimização de motores de busca"],"ru":["ИИ Агенты дляseo-audit","оптимизация сайта","аудит SEO","улучшение позиций сайта","анализ контекста сайта","маркетинг продукта","проблемы SEO","рекомендации для улучшения позиций","инструменты SEO","оптимизация поисковых систем"],"ar":["seo-audit","تحسين موقع","تحليل أداء موقع","تحسين أداء عضوي","تحليل سياق الموقع","تسويق المنتجات","مشاكل تحسين محركات البحث","توصيات لتحسين الأداء","أدوات تحسين محركات البحث","تحسين محركات البحث"]}},"owner":"pelan05","repo":"vscode_agents_folder","repoPath":"pelan05/vscode_agents_folder","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.289Z","topics":[],"category":"community","skillMd":{"name":"seo-audit","description":"When the user wants to audit, review, or diagnose SEO issues on their site. Also use when the user mentions SEO audit, technical SEO, why am I not ranking, SEO issues, on-page SEO, meta tags review, or SEO health check. For building pages at scale to target keywords, see programmatic-seo. For adding structured data, see schema-markup.","version":"1.0.0","bodyPreview":"# SEO Audit\n\nYou are an expert in search engine optimization. Your goal is to identify SEO issues and provide actionable recommendations to improve organic search performance.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.claude/product-marketing-context.md` exists, read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore auditing, understand:\n\n1. **Site Context**\n   - What type of site? (Sa","body":"# SEO Audit\n\nYou are an expert in search engine optimization. Your goal is to identify SEO issues and provide actionable recommendations to improve organic search performance.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.claude/product-marketing-context.md` exists, read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore auditing, understand:\n\n1. **Site Context**\n   - What type of site? (SaaS, e-commerce, blog, etc.)\n   - What''s the primary business goal for SEO?\n   - What keywords/topics are priorities?\n\n2. **Current State**\n   - Any known issues or concerns?\n   - Current organic traffic level?\n   - Recent changes or migrations?\n\n3. **Scope**\n   - Full site audit or specific pages?\n   - Technical + on-page, or one focus area?\n   - Access to Search Console / analytics?\n\n---\n\n## Audit Framework\n\n### Priority Order\n1. **Crawlability & Indexation** (can Google find and index it?)\n2. **Technical Foundations** (is the site fast and functional?)\n3. **On-Page Optimization** (is content optimized?)\n4. **Content Quality** (does it deserve to rank?)\n5. **Authority & Links** (does it have credibility?)\n\n---\n\n## Technical SEO Audit\n\n### Crawlability\n\n**Robots.txt**\n- Check for unintentional blocks\n- Verify important pages allowed\n- Check sitemap reference\n\n**XML Sitemap**\n- Exists and accessible\n- Submitted to Search Console\n- Contains only canonical, indexable URLs\n- Updated regularly\n- Proper formatting\n\n**Site Architecture**\n- Important pages within 3 clicks of homepage\n- Logical hierarchy\n- Internal linking structure\n- No orphan pages\n\n**Crawl Budget Issues** (for large sites)\n- Parameterized URLs under control\n- Faceted navigation handled properly\n- Infinite scroll with pagination fallback\n- Session IDs not in URLs\n\n### Indexation\n\n**Index Status**\n- site:domain.com check\n- Search Console coverage report\n- Compare indexed vs. expected\n\n**Indexation Issues**\n- Noindex tags on important pages\n- Canonicals pointing wrong direction\n- Redirect chains/loops\n- Soft 404s\n- Duplicate content without canonicals\n\n**Canonicalization**\n- All pages have canonical tags\n- Self-referencing canonicals on unique pages\n- HTTP → HTTPS canonicals\n- www vs. non-www consistency\n- Trailing slash consistency\n\n### Site Speed & Core Web Vitals\n\n**Core Web Vitals**\n- LCP (Largest Contentful Paint): < 2.5s\n- INP (Interaction to Next Paint): < 200ms\n- CLS (Cumulative Layout Shift): < 0.1\n\n**Speed Factors**\n- Server response time (TTFB)\n- Image optimization\n- JavaScript execution\n- CSS delivery\n- Caching headers\n- CDN usage\n- Font loading\n\n**Tools**\n- PageSpeed Insights\n- WebPageTest\n- Chrome DevTools\n- Search Console Core Web Vitals report\n\n### Mobile-Friendliness\n\n- Responsive design (not separate m. site)\n- Tap target sizes\n- Viewport configured\n- No horizontal scroll\n- Same content as desktop\n- Mobile-first indexing readiness\n\n### Security & HTTPS\n\n- HTTPS across entire site\n- Valid SSL certificate\n- No mixed content\n- HTTP → HTTPS redirects\n- HSTS header (bonus)\n\n### URL Structure\n\n- Readable, descriptive URLs\n- Keywords in URLs where natural\n- Consistent structure\n- No unnecessary parameters\n- Lowercase and hyphen-separated\n\n---\n\n## On-Page SEO Audit\n\n### Title Tags\n\n**Check for:**\n- Unique titles for each page\n- Primary keyword near beginning\n- 50-60 characters (visible in SERP)\n- Compelling and click-worthy\n- Brand name placement (end, usually)\n\n**Common issues:**\n- Duplicate titles\n- Too long (truncated)\n- Too short (wasted opportunity)\n- Keyword stuffing\n- Missing entirely\n\n### Meta Descriptions\n\n**Check for:**\n- Unique descriptions per page\n- 150-160 characters\n- Includes primary keyword\n- Clear value proposition\n- Call to action\n\n**Common issues:**\n- Duplicate descriptions\n- Auto-generated garbage\n- Too long/short\n- No compelling reason to click\n\n### Heading Structure\n\n**Check for:**\n- One H1 per page\n- H1 contains primary keyword\n- Logical hierarchy (H1 → H2 → H3)\n- Headings describe content\n- Not just for styling\n\n**Common issues:**\n- Multiple H1s\n- Skip levels (H1 → H3)\n- Headings used for styling only\n- No H1 on page\n\n### Content Optimization\n\n**Primary Page Content**\n- Keyword in first 100 words\n- Related keywords naturally used\n- Sufficient depth/length for topic\n- Answers search intent\n- Better than competitors\n\n**Thin Content Issues**\n- Pages with little unique content\n- Tag/category pages with no value\n- Doorway pages\n- Duplicate or near-duplicate content\n\n### Image Optimization\n\n**Check for:**\n- Descriptive file names\n- Alt text on all images\n- Alt text describes image\n- Compressed file sizes\n- Modern formats (WebP)\n- Lazy loading implemented\n- Responsive images\n\n### Internal Linking\n\n**Check for:**\n- Important pages well-linked\n- Descriptive anchor text\n- Logical link relationships\n- No broken internal links\n- Reasonable link count per page\n\n**Common issues:**\n- Orphan pages (no internal links)\n- Over-optimized anchor text\n- Important pages buried\n- Excessive footer/sidebar links\n\n### Keyword Targeting\n\n**Per Page**\n- Clear primary keyword target\n- Title, H1, URL aligned\n- Content satisfies search intent\n- Not competing with other pages (cannibalization)\n\n**Site-Wide**\n- Keyword mapping document\n- No major gaps in coverage\n- No keyword cannibalization\n- Logical topical clusters\n\n---\n\n## Content Quality Assessment\n\n### E-E-A-T Signals\n\n**Experience**\n- First-hand experience demonstrated\n- Original insights/data\n- Real examples and case studies\n\n**Expertise**\n- Author credentials visible\n- Accurate, detailed information\n- Properly sourced claims\n\n**Authoritativeness**\n- Recognized in the space\n- Cited by others\n- Industry credentials\n\n**Trustworthiness**\n- Accurate information\n- Transparent about business\n- Contact information available\n- Privacy policy, terms\n- Secure site (HTTPS)\n\n### Content Depth\n\n- Comprehensive coverage of topic\n- Answers follow-up questions\n- Better than top-ranking competitors\n- Updated and current\n\n### User Engagement Signals\n\n- Time on page\n- Bounce rate in context\n- Pages per session\n- Return visits\n\n---\n\n## Common Issues by Site Type\n\n### SaaS/Product Sites\n- Product pages lack content depth\n- Blog not integrated with product pages\n- Missing comparison/alternative pages\n- Feature pages thin on content\n- No glossary/educational content\n\n### E-commerce\n- Thin category pages\n- Duplicate product descriptions\n- Missing product schema\n- Faceted navigation creating duplicates\n- Out-of-stock pages mishandled\n\n### Content/Blog Sites\n- Outdated content not refreshed\n- Keyword cannibalization\n- No topical clustering\n- Poor internal linking\n- Missing author pages\n\n### Local Business\n- Inconsistent NAP\n- Missing local schema\n- No Google Business Profile optimization\n- Missing location pages\n- No local content\n\n---\n\n## Output Format\n\n### Audit Report Structure\n\n**Executive Summary**\n- Overall health assessment\n- Top 3-5 priority issues\n- Quick wins identified\n\n**Technical SEO Findings**\nFor each issue:\n- **Issue**: What''s wrong\n- **Impact**: SEO impact (High/Medium/Low)\n- **Evidence**: How you found it\n- **Fix**: Specific recommendation\n- **Priority**: 1-5 or High/Medium/Low\n\n**On-Page SEO Findings**\nSame format as above\n\n**Content Findings**\nSame format as above\n\n**Prioritized Action Plan**\n1. Critical fixes (blocking indexation/ranking)\n2. High-impact improvements\n3. Quick wins (easy, immediate benefit)\n4. Long-term recommendations\n\n---\n\n## References\n\n- [AI Writing Detection](references/ai-writing-detection.md): Common AI writing patterns to avoid (em dashes, overused phrases, filler words)\n- [AEO & GEO Patterns](references/aeo-geo-patterns.md): Content patterns optimized for answer engines and AI citation\n\n---\n\n## Tools Referenced\n\n**Free Tools**\n- Google Search Console (essential)\n- Google PageSpeed Insights\n- Bing Webmaster Tools\n- Rich Results Test\n- Mobile-Friendly Test\n- Schema Validator\n\n**Paid Tools** (if available)\n- Screaming Frog\n- Ahrefs / Semrush\n- Sitebulb\n- ContentKing\n\n---\n\n## Task-Specific Questions\n\n1. What pages/keywords matter most?\n2. Do you have Search Console access?\n3. Any recent changes or migrations?\n4. Who are your top organic competitors?\n5. What''s your current organic traffic baseline?\n\n---\n\n## Related Skills\n\n- **programmatic-seo**: For building SEO pages at scale\n- **schema-markup**: For implementing structured data\n- **page-cro**: For optimizing pages for conversion (not just ranking)\n- **analytics-tracking**: For measuring SEO performance\n"},"lastSynced":"2026-03-08T02:01:00.215Z","agentAnalysis":{"suitability":{"en":"Perfect for Digital Marketing Agents needing advanced SEO analysis and optimization capabilities.","zh":"非常适合需要高级SEO分析和优化功能的数字营销代理。","ja":"デジタルマーケティングエージェントが高度なSEO分析および最適化機能を必要とする場合に最適です。","ko":"고급 SEO 분석 및 최적화 기능이 필요한 디지털 마케팅 에이전트에게 적합합니다.","es":"Perfecto para agentes de marketing digital que necesitan capacidades de análisis y optimización de SEO avanzadas.","fr":"Parfait pour les agents de marketing numérique qui ont besoin d''une analyse et d''optimisation de SEO avancées.","de":"Perfekt für digitale Marketingagenten, die erweiterte SEO-Analyse- und Optimierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Marketing Digital que necessitam de capacidades avançadas de análise e otimização de SEO.","ru":"Идеально для цифровых маркетинговых агентов, которым необходимы расширенные возможности анализа и оптимизации SEO.","ar":"مثالي لعمليات التسويق الرقمي التي تحتاج إلى قدرات تحليل و تحسين متقدمة لتحسين محركات البحث."},"recommendation":{"en":"Empowers agents to identify SEO issues and provide actionable recommendations to improve organic search performance through site context analysis and product marketing context review, leveraging file formats like `.claude/product-marketing-context.md`.","zh":"赋予代理识别SEO问题的能力，并通过网站上下文分析和产品营销上下文审查提供可行的建议来提高有机搜索性能，利用诸如`.claude/product-marketing-context.md`的文件格式。","ja":"エージェントにSEOの問題を特定し、`.claude/product-marketing-context.md`などのファイル形式を使用して、サイトのコンテキスト分析と製品マーケティングコンテキストのレビューを通じて、オーガニック検索のパフォーマンスを改善するための実行可能な推奨事項を提供する機能を提供します。","ko":"에이전트가 SEO 문제를 식별하고 `.claude/product-marketing-context.md`와 같은 파일 형식을 사용하여 사이트 컨텍스트 분석 및 제품 마케팅 컨텍스트 검토를 통해 유기적 검색 성능을 개선하기 위한 실행 가능한 권장 사항을 제공할 수 있는 기능을 제공합니다.","es":"Habilita a los agentes a identificar problemas de SEO y proporcionar recomendaciones concretas para mejorar el rendimiento de la búsqueda orgánica a través del análisis del contexto del sitio y la revisión del contexto de marketing de productos, aprovechando formatos de archivo como .claude/product-marketing-context.md.","fr":"Permet aux agents d''identifier les problèmes de SEO et de fournir des recommandations concrètes pour améliorer les performances de recherche organique via l''analyse du contexte du site et l''examen du contexte de marketing de produits, en exploitant des formats de fichiers tels que .claude/product-marketing-context.md.","de":"Ermöglicht es Agenten, SEO-Probleme zu identifizieren und konkrete Empfehlungen zur Verbesserung der organischen Suchleistung durch Kontextanalyse der Website und Überprüfung des Produktmarketing-Kontexts bereitzustellen, indem Formate wie .claude/product-marketing-context.md genutzt werden.","pt":"Permite que os agentes identifiquem problemas de SEO e forneçam recomendações práticas para melhorar o desempenho de busca orgânica por meio da análise do contexto do site e da revisão do contexto de marketing de produtos, utilizando formatos de arquivo como `.claude/product-marketing-context.md`.","ru":"Наделяет агентов возможностью выявлять проблемы SEO и предоставлять действенные рекомендации для улучшения органического поискового показателя через анализ контекста сайта и обзор контекста продуктивного маркетинга, используя форматы файлов seperti `.claude/product-marketing-context.md`.","ar":"تمكن الوكلاء من تحديد مشاكل تحسين محركات البحث وتقديم توصيات قابلة للتنفيذ لتحسين أداء البحث العضوي من خلال تحليل سياق الموقع ومراجعة سياق تسويق المنتجات، باستخدام تنسيقات الملفات مثل `.claude/product-marketing-context.md`."},"useCases":{"en":["Auditing website SEO performance","Generating recommendations for SEO improvement","Analyzing product marketing context for SEO optimization"],"zh":["审计网站SEO性能","生成SEO改进建议","分析产品营销上下文以进行SEO优化"],"ja":["WebサイトのSEOパフォーマンスを監査する","SEOの改善に関する推奨事項を生成する","SEO最適化のための製品マーケティングコンテキストを分析する"],"ko":["웹사이트 SEO 성능을 감사하는 것","SEO 개선에 대한 제안을 생성하는 것","SEO 최적화를 위한 제품 마케팅 컨텍스트를 분석하는 것"],"es":["Auditoría del rendimiento de SEO del sitio web","Generación de recomendaciones para la mejora de SEO","Análisis del contexto de marketing de productos para la optimización de SEO"],"fr":["Audit des performances de SEO du site Web","Génération de recommandations pour l''amélioration de SEO","Analyse du contexte de marketing de produits pour l''optimisation de SEO"],"de":["Prüfung der SEO-Leistung der Website","Generierung von Empfehlungen zur Verbesserung von SEO","Analyse des Produktmarketing-Kontexts für die SEO-Optimierung"],"pt":["Auditoria do desempenho de SEO do site","Geração de recomendações para melhoria de SEO","Análise do contexto de marketing de produtos para otimização de SEO"],"ru":["Аудит показателей SEO сайта","Генерация рекомендаций для улучшения SEO","Анализ контекста продуктивного маркетинга для оптимизации SEO"],"ar":["مراجعة أداء تحسين محركات البحث للموقع","توليد التوصيات لتحسين تحسين محركات البحث","تحليل سياق تسويق المنتجات لتحسين تحسين محركات البحث"]},"limitations":{"en":["Requires access to site context and product marketing context information","Limited to organic search performance optimization"],"zh":["需要访问网站上下文和产品营销上下文信息","仅限于有机搜索性能优化"],"ja":["サイトのコンテキストおよび製品マーケティングコンテキスト情報へのアクセスが必要","オーガニック検索のパフォーマンス最適化のみ"],"ko":["사이트 컨텍스트 및 제품 마케팅 컨텍스트 정보에 대한 액세스가 필요함","유기적 검색 성능 최적화에만 제한됨"],"es":["Requiere acceso a información de contexto del sitio y contexto de marketing de productos","Limitado a la optimización del rendimiento de la búsqueda orgánica"],"fr":["Nécessite l''accès à des informations de contexte du site et de contexte de marketing de produits","Limité à l''optimisation des performances de recherche organique"],"de":["Benötigt Zugriff auf Kontextinformationen der Website und Produktmarketing-Kontext","Begrenzt auf die Optimierung der organischen Suchleistung"],"pt":["Requer acesso às informações de contexto do site e contexto de marketing de produtos","Limitado à otimização do desempenho de busca orgânica"],"ru":["Требует доступа к информации контекста сайта и контекста продуктивного маркетинга","Ограничен оптимизацией органического поискового показателя"],"ar":["يتطلب الوصول إلى معلومات سياق الموقع وسياق تسويق المنتجات","محدود لتحسين أداء البحث العضوي"]},"version":4},"contentHash":"51fdd3616ae1dd1209e0f7344582e76bed640c182118df9824859470249031d7","qualityScore":52}');
