INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ErickAguilar95/full_wordpress_figma_creator/wordpress-pro', 'wordpress-pro', 'ErickAguilar95', 'full_wordpress_figma_creator', 'community', 'wordpress-pro ErickAguilar95 full_wordpress_figma_creator community wordpress-pro helps expert WordPress developers build custom themes, plugins, and solutions with PHP 8.1+, Gutenberg block development, and WooCommerce customization. WordPress Pro是一种使用AIエージェント的高级WordPress开发工具，用于创建可配置的Figma登录页面和自定义WordPress主题 WordPress Proは、AIエージェントを使用したカスタムテーマ、プラグイン、Gutenbergブロックの開発を可能にする高级WordPress開発ツールです WordPress Pro는 AI 도구를 사용하여 REST API를 통합하고、パフォーマンスを最適化し、セキュアでスケーラブルなWordPressソリューションを構築するための開発ツール입니다 WordPress Pro es un experto en desarrollo de WordPress con experiencia en temas personalizados, plugins y optimización de rendimiento WordPress Pro est un expert en développement WordPress avec une expérience dans les thèmes personnalisés, les plugins et l''optimisation des performances WordPress Pro ist ein Experte für WordPress-Entwicklung mit Erfahrung in benutzerdefinierten Themen, Plugins und Leistungsoptimierung O WordPress Pro é um especialista em desenvolvimento de temas e plugins personalizados para WordPress, com foco em PHP 8.1+, Gutenberg e WooCommerce WordPress Pro - это эксперт в области разработки кастомных тем и плагинов для WordPress, специализирующийся на PHP 8.1+, Gutenberg и WooCommerce ووردبريس پرو هو مختص في تطوير الثيمات والأدوات الإضافية المخصصة لـ ووردبريس، مع التركيز على PHP 8.1+ و Gutenberg و WooCommerce how to use wordpress-pro wordpress-pro setup guide wordpress-pro vs elementor wordpress-pro install what is wordpress-pro wordpress-pro expert developer wordpress-pro gutenberg blocks wordpress-pro performance optimization WordPress Pro AIエージェント Figma WordPress主题开发 Gutenberg块开发 WooCommerce定制 REST API集成 性能优化 Develops custom WordPress themes with modern PHP 8.1+ Creates Gutenberg blocks for enhanced content creation Customizes WooCommerce for e-commerce solutions Integrates REST API for seamless data exchange Optimizes WordPress performance for scalable and secure solutions wordpress-pro is a specialized AI agent skill for expert WordPress developers, focusing on custom theme development, plugin creation, and performance optimization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yusuke124358/keiba/chatgpt-bridge', 'community', 'yusuke124358', 'keiba', 'yusuke124358/keiba', 'chatgpt-bridge', 0, 0, 52, '2026-03-08T01:57:15.381Z', '2026-03-08T02:05:39.567Z', '130ad825df18c6c8d4e2fa8f73741990a4b8c53441abd101a63420d781b4642e', '{"id":"yusuke124358/keiba/chatgpt-bridge","name":"chatgpt-bridge","description":{"en":"The chatgpt-bridge skill enables the generation of machine-readable JSON output, strictly matching the provided output schema, benefiting developers working with AI agents and data exchange protocols.","zh":"chatgpt-bridge 是一个用于桥接 ChatGPT 和其他 AI 工具的技术解决方案，提供机器可读的 JSON 输出","ja":"chatgpt-bridge は、ChatGPT と他の AI エージェントを橋渡しする技術的なソリューションであり、機械可読の JSON 出力を提供","ko":"chatgpt-bridge는 ChatGPT와 다른 AI 에이전트를 브릿지하는 기술적인 솔루션으로 기계가 읽을 수 있는 JSON 출력을 제공","es":"chatgpt-bridge es una herramienta de integración para Agentes de IA que permite a los desarrolladores crear soluciones personalizadas con código JSON","fr":"chatgpt-bridge est un outil d''intégration pour les Outils d''IA qui permet aux développeurs de créer des solutions personnalisées avec du code JSON","de":"chatgpt-bridge ist ein Integrationswerkzeug für KI-Tools und -Agenten, das es Entwicklern ermöglicht, individuelle Lösungen mit JSON-Code zu erstellen","pt":"O chatgpt-bridge é uma ferramenta de integração de AI Agents que permite desenvolvedores trabalharem com JSON e preferir mudanças mínimas.","ru":"chatgpt-bridge - это инструмент интеграции ИИ Агентов, который позволяет разработчикам работать с JSON и предпочитать минимальные изменения.","ar":"chatgpt-bridge هي أداة دمج الوكلاء الذكية التي تمكن المطورين من العمل مع JSON و تفضل التغييرات الطفيفة."},"seo":{"title":{"en":"chatgpt-bridge: JSON Output Generation for AI Agents | AI...","zh":"chatgpt-bridge 集成指南：AI 工具桥接解决方案","ja":"chatgpt-bridge Setup Guide: AIエージェントの橋渡しソリューション","ko":