INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yusuke124358/keiba/chatgpt-bridge', 'chatgpt-bridge', 'yusuke124358', 'keiba', 'community', 'chatgpt-bridge yusuke124358 keiba community The chatgpt-bridge skill enables the generation of machine-readable JSON output, strictly matching the provided output schema, benefiting developers working with AI agents and data exchange protocols. chatgpt-bridge 是一个用于桥接 ChatGPT 和其他 AI 工具的技术解决方案，提供机器可读的 JSON 输出 chatgpt-bridge は、ChatGPT と他の AI エージェントを橋渡しする技術的なソリューションであり、機械可読の JSON 出力を提供 chatgpt-bridge는 ChatGPT와 다른 AI 에이전트를 브릿지하는 기술적인 솔루션으로 기계가 읽을 수 있는 JSON 출력을 제공 chatgpt-bridge es una herramienta de integración para Agentes de IA que permite a los desarrolladores crear soluciones personalizadas con código JSON chatgpt-bridge est un outil d''intégration pour les Outils d''IA qui permet aux développeurs de créer des solutions personnalisées avec du code JSON chatgpt-bridge ist ein Integrationswerkzeug für KI-Tools und -Agenten, das es Entwicklern ermöglicht, individuelle Lösungen mit JSON-Code zu erstellen O chatgpt-bridge é uma ferramenta de integração de AI Agents que permite desenvolvedores trabalharem com JSON e preferir mudanças mínimas. chatgpt-bridge - это инструмент интеграции ИИ Агентов, который позволяет разработчикам работать с JSON и предпочитать минимальные изменения. chatgpt-bridge هي أداة دمج الوكلاء الذكية التي تمكن المطورين من العمل مع JSON و تفضل التغييرات الطفيفة. how to use chatgpt-bridge what is chatgpt-bridge chatgpt-bridge alternative chatgpt-bridge vs other AI agents chatgpt-bridge install guide chatgpt-bridge setup for JSON output chatgpt-bridge for AI agent development chatgpt-bridge JSON schema matching chatgpt-bridge AI 工具桥接 机器可读的 JSON 输出 最小化代码变更 避免非必要的网络访问 AI开发 chatgpt集成 Produces machine-readable JSON output Strictly matches the provided output schema Prefers minimal changes for efficient data processing Avoids network access unless explicitly allowed Sets status to needs_approval for risky or confirmatory actions chatgpt-bridge is a skill that generates machine-readable JSON output, following specific rules and protocols for efficient data exchange and processing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('davidmoneil/AIfred/project-lifecycle', 'community', 'davidmoneil', 'AIfred', 'davidmoneil/AIfred', 'project-lifecycle', 0, 0, 52, '2026-03-08T01:57:15.414Z', '2026-03-08T02:07:09.948Z', '86e16d8047d9a29478b0c588228d5fae3dfaab2a67aefceedc8d21c104009fde', '{"id":"davidmoneil/AIfred/project-lifecycle","name":"project-lifecycle","description":{"en":"The project-lifecycle skill provides a unified approach to project management, from creation to consolidation and archival, benefiting developers and project managers.","zh":"AIfred的项目生命周期技能提供了从创建到存档的完整项目管理工作流，包括注册、同步和更新","ja":"AIfredのプロジェクトライフサイクルスキルは、作成からアーカイブまでの完全なプロジェクト管理ワークフローを提供します","ko":"AIfred의 프로젝트 生命周期 관리 스킬은 생성에서 보관까지의 완전한 프로젝트 관리 워크플로우를 제공합니다","es":"AIfred es una herramienta de gestión de proyectos basada en IA que automatiza el ciclo de vida del proyecto, desde la creación hasta la consolidación y archivo","fr":"AIfred est un outil de gestion de projet basé sur l''IA qui automatise le cycle de vie du projet, de la création à la consolidation et à l''archivage","de":"AIfred ist ein IA-basiertes Projektmanagement-Tool, das den Lebenszyklus eines Projekts automatisiert, von der Erstellung bis zur Konsolidierung und Archivierung","pt":"A skill de ciclo de vida do projeto fornece uma abordagem unificada para gerenciar projetos, desde a criação até a consolidação e arquivamento","ru":"Навык жизненного цикла проекта обеспечивает унифицированный подход к управлению проектами, от создания до консолидации и архивации","ar":"توفير مهارة دورة حياة المشروع نهجًا موحدًا لإدارة المشاريع، من الإنشاء إلى الدمج والأرشفة"},"seo":{"title":{"en":"project-lifecycle: Unified Project Management Workflow | ...","zh":"项目生命周期管理Setup Guide - AIエージェント","ja":"プロジェクトライフサイクル管理Best Practices - AIエージェント","ko":"프로젝트 生命周期 관리Setup Guide - AI 에이전트","es":"Guía de configuración del ciclo de vida del proyecto con ...","fr":"Guide de mise en place du cycle de vie de projet avec AIfred","de":"Einrichtungsleitfaden für das Projekt-Lebenszyklus-Tool A...","pt":"Guia de Configuração do Ciclo de Vida do Projeto com Ferr...","ru":"ИИ Агенты для Управления Жизненным Циклом Проекта: Руково...","ar":"دليل إعداد دورة حياة المشروع مع أدوات الإنسان الآلي"},"description":{"en":"Streamline your project lifecycle with AIfred''s AI-enabled command deck. Learn how to register, consolidate, and manage projects efficiently.","zh":"使用AIfred的项目生命周期技能来管理代码项目，从创建到存档，包括注册、同步和更新","ja":"AIfredのプロジェクトライフサイクルスキルを使用して、コードプロジェクトを管理します。作成からアーカイブまで、登録、同期、更新など","ko":"AIfred의 프로젝트 生命周期 관리 스킬을 사용하여 코드 프로젝트를 관리하십시오. 생성에서 보관까지 등록, 동기화, 업데이트를 포함","es":"Automatice el ciclo de vida de sus proyectos con AIfred, la herramienta de gestión de proyectos basada en IA para desarrolladores","fr":"Automatisez le cycle de vie de vos projets avec AIfred, l''outil de gestion de projet basé sur l''IA pour les développeurs","de":"Automatisieren Sie den Lebenszyklus Ihrer Projekte mit AIfred, dem IA-basierten Projektmanagement-Tool für Entwickler","pt":"Aprenda a gerenciar o ciclo de vida do projeto com a skill de ciclo de vida do projeto, incluindo criação, registro, consolidação e gerenciamento","ru":"Узнайте, как управлять жизненным циклом проекта с помощью навыка жизненного цикла проекта, включая создание, регистрацию, консолидацию и управление","ar":"تعرف على كيفية إدارة دورة حياة المشروع باستخدام مهارة دورة حياة المشروع، بما في ذلك الإنشاء والتسجيل والدمج والإدارة"},"definition":{"en":"project-lifecycle is a comprehensive project management workflow that consolidates creation, registration, consolidation, and management operations.","zh":"项目生命周期管理是指从创建到存档的整个项目管理过程","ja":"プロジェクトライフサイクル管理とは、作成からアーカイブまでのプロジェクト管理の全过程","ko":"프로젝트 生命周期 관리란 생성에서 보관까지의 프로젝트 관리의 전체 과정","es":"El ciclo de vida del proyecto es el proceso de creación, registro, consolidación y gestión de proyectos en un entorno de desarrollo","fr":"Le cycle de vie du projet est le processus de création, d''enregistrement, de consolidation et de gestion de projets dans un environnement de développement","de":"Der Lebenszyklus eines Projekts ist der Prozess der Erstellung, Registrierung, Konsolidierung und Verwaltung von Projekten in einer Entwicklungsumgebung","pt":"O que é a skill de ciclo de vida do projeto? É uma ferramenta de IA que gerencia projetos desde a criação até a consolidação","ru":"Что такое навык жизненного цикла проекта? Это инструмент ИИ, который управляет проектами от создания до консолидации","ar":"ما هي مهارة دورة حياة المشروع؟ هي أداة إنسان آلي تدير المشاريع من الإنشاء إلى الدمج"},"features":{"en":["Registers existing projects with AIfred tracking","Syncs knowledge and updates documentation","Creates commits and tracks priorities","Updates context files for efficient project management","Supports new code projects in ~/Code and internal projects in .claude/projects"],"zh":["支持代码项目的创建和注册","提供同步和更新功能","包括注册、同步和更新等功能","支持项目的管理和跟踪","提供代码项目的创建和管理功能"],"ja":["コードプロジェクトの作成と登録をサポート","同期と更新機能を提供","登録、同期、更新などの機能を含む","プロジェクトの管理と追跡をサポート","コードプロジェクトの作成と管理機能を提供"],"ko":["코드 프로젝트의 생성과 등록을 지원","동기화와 업데이트를 제공","등록, 동기화, 업데이트등의 기능을 포함","프로젝트의 관리와 추적을 지원","코드 프로젝트의 생성과 관리 기능을 제공"],"es":["Creación de nuevos proyectos en ~/Code o proyectos internos en .claude/projects","Registro de proyectos existentes con seguimiento de AIfred","Consolidación de conocimientos, actualización de documentación y creación de commits","Gestión de prioridades y actualización de archivos de contexto","Ejecución segura de runbooks para solucionar problemas comunes"],"fr":["Création de nouveaux projets dans ~/Code ou projets internes dans .claude/projects","Enregistrement de projets existants avec suivi AIfred","Consolidation des connaissances, mise à jour de la documentation et création de commits","Gestion des priorités et mise à jour des fichiers de contexte","Exécution sécurisée de runbooks pour résoudre des problèmes courants"],"de":["Erstellung neuer Projekte in ~/Code oder interner Projekte in .claude/projects","Registrierung bestehender Projekte mit AIfred-Verfolgung","Konsolidierung von Wissen, Aktualisierung von Dokumentation und Erstellung von Commits","Verwaltung von Prioritäten und Aktualisierung von Kontextdateien","Sichere Ausführung von Runbooks zur Lösung häufiger Probleme"],"pt":["Criação de novos projetos em ~/Code ou projetos internos em .claude/projects","Registro de projetos existentes com acompanhamento do AIfred","Consolidação de conhecimento, atualização de docs e criação de commits","Gerenciamento de prioridades e atualização de arquivos de contexto"],"ru":["Создание новых проектов в ~/Code или внутренних проектов в .claude/projects","Регистрация существующих проектов с отслеживанием AIfred","Консолидация знаний, обновление документации и создание коммитов","Управление приоритетами и обновление контекстных файлов"],"ar":["إنشاء مشاريع جديدة في ~/Code أو مشاريع داخلية في .claude/projects","تسجيل المشاريع الحالية مع تتبع AIfred","دمج المعرفة وتحديث الوثائق وإنشاء التزامات","إدارة الأولويات وتحديث ملفات السياق"]},"keywords":{"en":["how to use project-lifecycle","project-lifecycle setup guide","project-lifecycle alternative","project-lifecycle vs Jira","project-lifecycle install","what is project-lifecycle","project-lifecycle workflow management","AIfred project-lifecycle integration"],"zh":["项目生命周期管理","AIエージェント","代码项目管理","项目注册","项目同步","项目更新","项目管理工具","项目跟踪","代码管理"],"ja":["プロジェクトライフサイクル管理","AIエージェント","コードプロジェクト管理","プロジェクト登録","プロジェクト同期","プロジェクト更新","プロジェクト管理ツール","プロジェクト追跡","コード管理"],"ko":["프로젝트 生命周期 관리","AI 에이전트","코드 프로젝트 관리","프로젝트 등록","프로젝트 동기화","프로젝트 업데이트","프로젝트 관리 도구","프로젝트 추적","코드 관리"],"es":["ciclo de vida del proyecto","gestión de proyectos","herramientas de desarrollo","IA para desarrolladores","automatización de proyectos","runbooks","commits","gestión de prioridades"],"fr":["cycle de vie du projet","gestion de projet","outils de développement","IA pour les développeurs","automatisation de projet","runbooks","commits","gestion des priorités"],"de":["Lebenszyklus eines Projekts","Projektmanagement","Entwicklungstools","IA für Entwickler","Automatisierung von Projekten","Runbooks","Commits","Prioritätenverwaltung"],"pt":["ferramentas de ia para gerenciamento de projetos","ciclo de vida do projeto","gerenciamento de projetos","criação de projetos","registro de projetos","consolidação de conhecimento"],"ru":["инструменты ии для управления проектами","жизненный цикл проекта","управление проектами","создание проектов","регистрация проектов","консолидация знаний"],"ar":["أدوات إنسان آلي لإدارة المشاريع","دورة حياة المشروع","إدارة المشاريع","إنشاء مشاريع","تسجيل المشاريع","دمج المعرفة"]}},"owner":"davidmoneil","repo":"AIfred","repoPath":"davidmoneil/AIfred","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.414Z","topics":[],"category":"community","skillMd":{"name":"project-lifecycle","description":"End-to-end project management from creation through consolidation and archival","version":"1.0.0","tags":["projects","lifecycle","creation","registration","consolidation"],"bodyPreview":"# Project Lifecycle Skill\n\nComplete project management workflow from creation through consolidation and archival.\n\n---\n\n## Overview\n\nThis skill consolidates all project lifecycle operations:\n- **Creation**: New code projects in ~/Code or internal projects in .claude/projects\n- **Registration**: Register existing projects with AIfred tracking\n- **Consolidation**: Sync knowledge, update docs, create commits\n- **Management**: Track priorities, update context files\n\n**Value**: Unified approach to pr","body":"# Project Lifecycle Skill\n\nComplete project management workflow from creation through consolidation and archival.\n\n---\n\n## Overview\n\nThis skill consolidates all project lifecycle operations:\n- **Creation**: New code projects in ~/Code or internal projects in .claude/projects\n- **Registration**: Register existing projects with AIfred tracking\n- **Consolidation**: Sync knowledge, update docs, create commits\n- **Management**: Track priorities, update context files\n\n**Value**: Unified approach to project management with consistent patterns and documentation.\n\n---\n\n## Quick Actions\n\n| Need | Action | Reference |\n|------|--------|---------|\n| Create new code project | `/new-code-project <name>` | @.claude/commands/new-code-project.md |\n| Register existing project | `/register-project <path-or-url>` | @.claude/commands/register-project.md |\n| Create internal project | `/create-project <name>` | @.claude/commands/create-project.md |\n| Consolidate project knowledge | `/consolidate-project <name>` | @.claude/commands/consolidate-project.md |\n\n---\n\n## Project Lifecycle Workflow\n\n```\nPROJECT LIFECYCLE\n=================\n\nCREATE (new projects)\n  /new-code-project <name>\n    - Creates in ~/Code/<name>\n    - Initializes git, README, .claude/CLAUDE.md\n    - Registers in paths-registry.yaml\n    - Creates context file at .claude/context/projects/<name>.md\n\n  /create-project <name>\n    - Creates internal project in .claude/projects/<name>\n    - For non-code projects (writing, research, planning)\n    - Creates project structure with config.yaml\n\nREGISTER (existing projects)\n  /register-project <path-or-url>\n    - Clones GitHub URL to ~/Code/ if needed\n    - Auto-detects language/type\n    - Adds to paths-registry.yaml\n    - Creates context file\n\nCONSOLIDATE (ongoing maintenance)\n  /consolidate-project <name>\n    - Updates context file with current state\n    - Syncs documentation with code\n    - Creates git commit with changes\n    - Options: --infrastructure, --analyze, --all\n\nARCHIVE (completed projects)\n  - Move context to .claude/context/archive/\n  - Update paths-registry.yaml status\n  - Optional: Remove from ~/Code/\n```\n\n---\n\n## Project Locations\n\nUnderstanding where projects live:\n\n| Project Type | Location | Registration |\n|--------------|----------|--------------|\n| Code projects | `~/Code/<project>/` | `paths-registry.yaml` → `coding.projects` |\n| Internal projects | `.claude/projects/<project>/` | Direct in AIfred |\n| Context/notes | `.claude/context/projects/<project>.md` | Always in AIfred |\n| External sources | `external-sources/<category>/` | Symlinks to external data |\n\n---\n\n## Context File Template\n\nWhen creating project context files, use this structure:\n\n```markdown\n# Project: <name>\n\n**Type**: web-app | api | cli | library | docker | internal\n**Language**: typescript | python | go | rust | N/A\n**Location**: ~/Code/<name> or .claude/projects/<name>\n**Status**: active | maintenance | archived\n**Created**: YYYY-MM-DD\n\n## Overview\n\nBrief description of project purpose.\n\n## Key Files\n\n- `src/` - Main source code\n- `README.md` - Project documentation\n\n## Current State\n\nWhat''s working, what''s in progress.\n\n## Integration Points\n\nHow this connects to AIfred infrastructure.\n```\n\n---\n\n## Registration Patterns\n\n### GitHub URL Detection\n\nWhen user mentions a GitHub URL:\n1. Check if already registered in `paths-registry.yaml`\n2. If not, clone to `~/Code/<repo-name>`\n3. Auto-detect language from file extensions\n4. Add to registry under `coding.projects`\n5. Create context file\n\n### Existing Local Project\n\nWhen registering an existing local project:\n1. Verify path exists\n2. Detect project type and language\n3. Add to `paths-registry.yaml`\n4. Create context file\n5. Optionally initialize `.claude/CLAUDE.md` in project\n\n---\n\n## Integration Points\n\n### With Session Management\n- New projects can be noted in session-state.md\n- Project work tracked via current-priorities.md\n\n### With Orchestration\n- Complex project setup may trigger orchestration\n- Use `/orchestration:plan \"setup [project]\"` for multi-phase setup\n\n### With Memory MCP\n- Store project metadata as Memory entities\n- Track project relationships and dependencies\n\n### With paths-registry.yaml\n- Source of truth for all project locations\n- Check before assuming any path\n\n---\n\n## Common Workflows\n\n### Starting a New Feature Project\n\n```\n1. /new-code-project my-feature --type api --lang typescript\n2. Review generated structure in ~/Code/my-feature\n3. Update context file with specific requirements\n4. Begin development\n```\n\n### Onboarding Existing Project\n\n```\n1. /register-project https://github.com/user/repo\n2. Review auto-detected settings\n3. Update context file with domain knowledge\n4. Add any custom CLAUDE.md to the project\n```\n\n### Project Knowledge Sync\n\n```\n1. /consolidate-project my-project\n2. Review documentation updates\n3. Commit changes\n4. Update session-state.md if needed\n```\n\n---\n\n## Troubleshooting\n\n### Project not appearing in registry?\n- Check `paths-registry.yaml` directly\n- Verify path exists: `ls ~/Code/<project>`\n- Re-run `/register-project <path>`\n\n### Context file out of date?\n- Run `/consolidate-project <name>`\n- Review changes before committing\n- Update manually if consolidation misses details\n\n### Git clone failing?\n- Check SSH key: `ssh -T git@github.com`\n- Verify URL format\n- Check network connectivity\n\n---\n\n## Related Documentation\n\n### Commands\n- @.claude/commands/new-code-project.md - New code project creation\n- @.claude/commands/register-project.md - Project registration\n- @.claude/commands/create-project.md - Internal project creation\n- @.claude/commands/consolidate-project.md - Project consolidation\n\n### Context Files\n- @paths-registry.yaml - Project registration source of truth\n- @.claude/context/projects/ - All project context files\n- @.claude/templates/project-template/ - Project template structure\n\n### Patterns\n- @.claude/context/patterns/memory-storage-pattern.md - When to store in Memory\n- @.claude/context/standards/documentation-location.md - Where to document\n"},"lastSynced":"2026-03-08T02:07:09.948Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring comprehensive project management capabilities from creation to archival.","zh":"适合需要从创建到存档的综合项目管理功能的开发代理","ja":"開発エージェントがプロジェクトの作成からアーカイブまで、包括的なプロジェクト管理機能を必要とする場合に最適","ko":"개발 에이전트가 생성에서 보관까지 포괄적인 프로젝트 관리 기능을 필요로 할 경우 적합","es":"Ideal para Agentes de Desarrollo que requieren capacidades de gestión de proyectos integrales desde la creación hasta el archivo.","fr":"Idéal pour les agents de développement nécessitant des capacités de gestion de projet complètes de la création à l''archivage.","de":"Ideal für Entwicklungsmittel, die umfassende Projektmanagementfunktionen von der Erstellung bis zum Archiv benötigen.","pt":"Ideal para Agentes de Desenvolvimento que requerem capacidades de gerenciamento de projeto abrangentes, desde a criação até o arquivamento.","ru":"Идеально для агентов разработки, требующих комплексных возможностей управления проектами от создания до архивации.","ar":"مثالية للوكلاء النمطية الذين يحتاجون إلى إمكانيات إدارة المشروع الشاملة من الإنشاء إلى الأرشفة."},"recommendation":{"en":"Empowers agents to manage project lifecycles seamlessly, including creation, registration, consolidation, and archival, leveraging AIfred tracking and context file updates to streamline project workflows.","zh":"赋予代理管理项目生命周期的能力，包括创建、注册、整合和存档，利用AIfred 跟踪和上下文文件更新来简化项目工作流程","ja":"エージェントがプロジェクトライフサイクルを管理する能力を提供し、AIfred トラッキングとコンテキストファイルの更新を利用して、作成、登録、統合、アーカイブなどのプロジェクトワークフローをスムーズにします","ko":"에이전트가 프로젝트 라이프사이클을 관리할 수 있는 능력을 제공하여 AIfred 트래킹과 컨텍스트 파일 업데이트를 활용하여 프로젝트 워크플로우를 원활하게 함","es":"Habilita a los agentes a gestionar los ciclos de vida de los proyectos de manera fluida, incluyendo la creación, el registro, la consolidación y el archivo, aprovechando el seguimiento de AIfred y las actualizaciones de archivos de contexto para optimizar los flujos de trabajo de los proyectos.","fr":"Permet aux agents de gérer les cycles de vie des projets de manière transparente, notamment la création, l''enregistrement, la consolidation et l''archivage, en exploitant le suivi AIfred et les mises à jour des fichiers de contexte pour rationaliser les flux de travail des projets.","de":"Ermöglicht es den Agenten, die Projekt-Lebenszyklen nahtlos zu verwalten, einschließlich Erstellung, Registrierung, Konsolidierung und Archivierung, und nutzt dabei AIfred-Verfolgung und Kontextdatei-Aktualisierungen, um Projekt-Workflows zu optimieren.","pt":"Habilita os agentes a gerenciar ciclos de vida de projetos de forma transparente, incluindo criação, registro, consolidação e arquivamento, utilizando o rastreamento do AIfred e atualizações de arquivos de contexto para otimizar os fluxos de trabalho do projeto.","ru":"Наделяет агентов возможностью управлять жизненным циклом проектов бесшовно, включая создание, регистрацию, консолидацию и архивацию, используя отслеживание AIfred и обновления контекстных файлов для оптимизации рабочих процессов проекта.","ar":"تمكّن الوكلاء من إدارة دورة حياة المشروع بسلاسة، بما في ذلك إنشاء وتسجيل وتوحيد وأرشفة، باستخدام تتبع AIfred وتحديثات ملفات السياق لتحسين سير عمل المشروع."},"useCases":{"en":["Automating project creation and registration with AIfred tracking","Consolidating project knowledge and updating documentation","Managing project priorities and context files for efficient tracking"],"zh":["使用AIfred 跟踪自动化项目创建和注册","整合项目知识并更新文档","管理项目优先级和上下文文件以实现高效跟踪"],"ja":["AIfred トラッキングを使用したプロジェクト作成と登録の自動化","プロジェクトの知識を統合し、文書を更新する","プロジェクトの優先度とコンテキストファイルを管理して効率的なトラッキングを行う"],"ko":["AIfred 트래킹을 사용한 프로젝트 생성 및 등록 자동화","프로젝트 지식 통합 및 문서 업데이트","프로젝트 우선순위 및 컨텍스트 파일 관리를 통한 효율적인 트래킹"],"es":["Automatizar la creación y el registro de proyectos con seguimiento de AIfred","Consolidar el conocimiento del proyecto y actualizar la documentación","Gestionar las prioridades y archivos de contexto del proyecto para un seguimiento eficiente"],"fr":["Automatiser la création et l''enregistrement de projets avec le suivi AIfred","Consolider les connaissances du projet et mettre à jour la documentation","Gérer les priorités et les fichiers de contexte du projet pour un suivi efficace"],"de":["Automatisieren der Projekt-Erstellung und -Registrierung mit AIfred-Verfolgung","Konsolidieren des Projekt-Wissens und Aktualisieren der Dokumentation","Verwalten der Projekt-Prioritäten und Kontextdateien für eine effiziente Verfolgung"],"pt":["Automatizar a criação e registro de projetos com o rastreamento do AIfred","Consolidar o conhecimento do projeto e atualizar a documentação","Gerenciar prioridades de projeto e arquivos de contexto para acompanhamento eficiente"],"ru":["Автоматизировать создание и регистрацию проектов с помощью отслеживания AIfred","Консолидировать знания проекта и обновлять документацию","Управлять приоритетами проекта и контекстными файлами для эффективного отслеживания"],"ar":["أتمتة إنشاء وتسجيل المشروع مع تتبع AIfred","توحيد معرفة المشروع وتحديث الوثائق","إدارة أولويات المشروع وملفات السياق для التتبع الفعال"]},"limitations":{"en":["Requires access to ~/Code and .claude/projects directories","Dependent on AIfred tracking for project registration"],"zh":["需要访问 ~/Code 和 .claude/projects 目录","依赖于AIfred 跟踪进行项目注册"],"ja":[" ~/Code および .claude/projects ディレクトリへのアクセスが必要","プロジェクト登録にはAIfred トラッキングに依存する"],"ko":[" ~/Code 및 .claude/projects 디렉토리에 액세스해야 함","프로젝트 등록에는 AIfred 트래킹에 의존"],"es":["Requiere acceso a los directorios ~/Code y .claude/projects","Dependiente del seguimiento de AIfred para el registro de proyectos"],"fr":["Nécessite un accès aux répertoires ~/Code et .claude/projects","Dépend du suivi AIfred pour l''enregistrement de projets"],"de":["Erfordert Zugriff auf die Verzeichnisse ~/Code und .claude/projects","Abhängig von der AIfred-Verfolgung für die Projekt-Registrierung"],"pt":["Requer acesso aos diretórios ~/Code e .claude/projects","Depende do rastreamento do AIfred para registro de projeto"],"ru":["Требует доступа к директориям ~/Code и .claude/projects","Зависит от отслеживания AIfred для регистрации проекта"],"ar":["يتطلب الوصول إلى الدلائل ~/Code و .claude/projects","يعتمد على تتبع AIfred لتسجيل المشروع"]},"version":4},"contentHash":"86e16d8047d9a29478b0c588228d5fae3dfaab2a67aefceedc8d21c104009fde","qualityScore":52}');
