INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('davidmoneil/AIfred/project-lifecycle', 'project-lifecycle', 'davidmoneil', 'AIfred', 'community', 'project-lifecycle davidmoneil AIfred community The project-lifecycle skill provides a unified approach to project management, from creation to consolidation and archival, benefiting developers and project managers. AIfred的项目生命周期技能提供了从创建到存档的完整项目管理工作流，包括注册、同步和更新 AIfredのプロジェクトライフサイクルスキルは、作成からアーカイブまでの完全なプロジェクト管理ワークフローを提供します AIfred의 프로젝트 生命周期 관리 스킬은 생성에서 보관까지의 완전한 프로젝트 관리 워크플로우를 제공합니다 AIfred es una herramienta de gestión de proyectos basada en IA que automatiza el ciclo de vida del proyecto, desde la creación hasta la consolidación y archivo AIfred est un outil de gestion de projet basé sur l''IA qui automatise le cycle de vie du projet, de la création à la consolidation et à l''archivage AIfred ist ein IA-basiertes Projektmanagement-Tool, das den Lebenszyklus eines Projekts automatisiert, von der Erstellung bis zur Konsolidierung und Archivierung A skill de ciclo de vida do projeto fornece uma abordagem unificada para gerenciar projetos, desde a criação até a consolidação e arquivamento Навык жизненного цикла проекта обеспечивает унифицированный подход к управлению проектами, от создания до консолидации и архивации توفير مهارة دورة حياة المشروع نهجًا موحدًا لإدارة المشاريع، من الإنشاء إلى الدمج والأرشفة how to use project-lifecycle project-lifecycle setup guide project-lifecycle alternative project-lifecycle vs Jira project-lifecycle install what is project-lifecycle project-lifecycle workflow management AIfred project-lifecycle integration 项目生命周期管理 AIエージェント 代码项目管理 项目注册 项目同步 项目更新 项目管理工具 项目跟踪 代码管理 Registers existing projects with AIfred tracking Syncs knowledge and updates documentation Creates commits and tracks priorities Updates context files for efficient project management Supports new code projects in ~/Code and internal projects in .claude/projects project-lifecycle is a comprehensive project management workflow that consolidates creation, registration, consolidation, and management operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('minhtungo/ai-agents-factory/humanizer', 'community', 'minhtungo', 'ai-agents-factory', 'minhtungo/ai-agents-factory', 'humanizer', 0, 0, 52, '2026-03-08T01:57:15.417Z', '2026-03-08T02:07:17.795Z', '2703518f37ce57b7ad8ddffdaa20bded14a23aa6108090acca46400d810ff778', '{"id":"minhtungo/ai-agents-factory/humanizer","name":"humanizer","description":{"en":"The Humanizer skill helps writing editors remove signs of AI-generated text, making writing sound more natural. It benefits developers and writers who need to refine AI-generated content.","zh":"Humanizer 是一种去除 AI 写作模式的工具，通过识别和替换 AI 特征，实现自然人类化写作","ja":"Humanizer は AI エージェントの文章パターンを削除するツールで、AI の特徴を識別して置き換えることで自然な文章を作成","ko":"Humanizer는 AI 텍스트 패턴을 제거하는 도구로, AI 특징을 식별하고 대체하여 자연스러운 글쓰기를 구현","es":"Humanizer es una herramienta que identifica y elimina patrones de escritura de IA para hacer que tus textos suenen más naturales y humanos","fr":"Humanizer est un outil qui identifie et supprime les modèles d''écriture de l''IA pour rendre vos textes plus naturels et humains","de":"Humanizer ist ein Tool, das AI-Schreibmuster identifiziert und entfernt, um Ihre Texte natürlich und menschlich klingen zu lassen","pt":"O Humanizer é uma ferramenta que identifica e remove padrões de escrita de IA para tornar o texto mais natural","ru":"Humanizer - это инструмент, который идентифицирует и удаляет шаблоны написания ИИ, чтобы сделать текст более естественным","ar":"Humanizer هو أداة تحدد و تحذف أنماط الكتابة التي تم إنشاؤها بواسطة أدوات الذكاء الاصطناعي لتجعل النص أكثر طبيعية"},"seo":{"title":{"en":"Humanizer: AI Writing Pattern Removal Setup Guide | AI Ag...","zh":"Humanizer 设置指南：去除 AI 写作模式","ja":"Humanizer 導入ガイド：AI エージェントの文章パターンを削除","ko":"Humanizer 설정 가이드: AI 텍스트 패턴 제거","es":"Guía de configuración de Humanizer: Elimina patrones de e...","fr":"Guide de mise en place de Humanizer : Supprimer les modèl...","de":"Einrichtungsleitfaden für Humanizer: Entfernen von AI-Sch...","pt":"Guia de Configuração do Humanizer: Remoção de Padrões de ...","ru":"Настройка Humanizer: удаление шаблонов написания ИИ Агентов","ar":"دليل إعداد Humanizer: إزالة أنماط الكتابة التي تم إنشاؤها..."},"description":{"en":"Discover how to make AI-generated text sound more natural with Humanizer. Learn to identify and remove AI patterns, and get started with our expert guide today!","zh":"了解 Humanizer 的功能和技术细节，发现如何去除 AI 写作模式，实现自然人类化写作","ja":"Humanizer の機能と技術的詳細を学び、AI エージェントの文章パターンを削除して自然な文章を作成する方法を発見","ko":"Humanizer의 기능과 기술적 세부 정보를 알아보고, AI 텍스트 패턴을 제거하여 자연스러운 글쓰기를 구현하는 방법을 발견","es":"Aprende a utilizar Humanizer para identificar y eliminar patrones de escritura de IA y hacer que tus textos suenen más naturales","fr":"Découvrez comment utiliser Humanizer pour identifier et supprimer les modèles d''écriture de l''IA et rendre vos textes plus naturels","de":"Erfahren Sie, wie Sie Humanizer verwenden, um AI-Schreibmuster zu identifizieren und zu entfernen und Ihre Texte natürlich klingen zu lassen","pt":"Aprenda a remover padrões de escrita de IA com o Humanizer e melhore a naturalidade do seu texto","ru":"Узнайте, как удалить шаблоны написания ИИ с помощью Humanizer и сделать ваш текст более естественным","ar":"تعرف على كيفية إزالة أنماط الكتابة التي تم إنشاؤها بواسطة أدوات الذكاء الاصطناعي مع Humanizer وتحسين الطبيعية في نصك"},"definition":{"en":"Humanizer is a writing editor skill that identifies and removes AI-generated text patterns to produce more natural and human-like writing.","zh":"Humanizer 是一种工具，用于去除 AI 写作模式，实现自然人类化写作","ja":"Humanizer は AI エージェントの文章パターンを削除するツール","ko":"Humanizer는 AI 텍스트 패턴을 제거하는 도구","es":"Humanizer es una herramienta de edición de escritura que elimina patrones de IA para hacer que los textos suenen más humanos","fr":"Humanizer est un outil d''édition d''écriture qui supprime les modèles de l''IA pour rendre les textes plus humains","de":"Humanizer ist ein Schreib-Editor-Tool, das AI-Muster entfernt, um Texte menschlicher klingen zu lassen","pt":"O Humanizer é uma ferramenta de edição de texto que remove padrões de escrita de IA","ru":"Humanizer - это инструмент редактирования текста, который удаляет шаблоны написания ИИ","ar":"Humanizer هو أداة تحرير نص تحذف أنماط الكتابة التي تم إنشاؤها بواسطة أدوات الذكاء الاصطناعي"},"features":{"en":["Identifies AI patterns based on Wikipedia''s Signs of AI writing page","Rewrites problematic sections to replace AI-isms with natural alternatives","Preserves the core meaning of the original text during rewriting","Scans text for specific patterns listed in WikiProject AI Cleanup","Replaces AI-generated phrases with more human-like expressions"],"zh":["识别 AI 写作模式","替换 AI 特征","保留核心意义","实现自然人类化写作","基于 Wikipedia 的 Signs of AI writing 页面","支持多种写作风格"],"ja":["AI エージェントの文章パターンを識別","AI の特徴を置き換える","核心的な意味を保つ","自然な文章を作成","Wikipedia の Signs of AI writing ページに基づく","多種の文章スタイルをサポート"],"ko":["AI 텍스트 패턴을 식별","AI 특징을 대체","핵심 의미를 보존","자연스러운 글쓰기를 구현","Wikipedia의 Signs of AI writing 페이지에 기반","다양한 글쓰기 스타일을 지원"],"es":["Identificación de patrones de escritura de IA","Reescritura de secciones problemáticas con alternativas naturales","Conservación del significado original del texto","Integración con tecnologías de procesamiento de lenguaje natural","Capacidad para mejorar la calidad y la naturalidad de los textos generados por IA"],"fr":["Identification des modèles d''écriture de l''IA","Réécriture de sections problématiques avec des alternatives naturelles","Préservation du sens original du texte","Intégration avec des technologies de traitement du langage naturel","Capacité à améliorer la qualité et la naturalité des textes générés par l''IA"],"de":["Identifizierung von AI-Schreibmustern","Neufassung problematischer Abschnitte mit natürlichen Alternativen","Erhaltung der ursprünglichen Bedeutung des Textes","Integration mit Technologien der natürlichen Sprachverarbeitung","Fähigkeit, die Qualität und Natürlichkeit von AI-generierten Texten zu verbessern"],"pt":["Identificação de padrões de escrita de IA","Reescrita de seções problemáticas","Preservação do significado original","Integração com Wikipedia''s ''Signs of AI writing'' page"],"ru":["Идентификация шаблонов написания ИИ","Переписывание проблемных разделов","Сохранение исходного смысла","Интеграция со страницей Википедии ''Signs of AI writing''"],"ar":["تحديد أنماط الكتابة التي تم إنشاؤها بواسطة أدوات الذكاء الاصطناعي","إعادة كتابة الأقسام المشكلة","الحفاظ على المعنى الأصلي","التكامل مع صفحة ويكيبيديا ''علامات الكتابة التي تم إنشاؤها بواسطة أدوات الذكاء الاصطناعي''"]},"keywords":{"en":["how to use humanizer","what is humanizer","humanizer alternative","humanizer vs writing assistants","humanizer install","humanizer setup guide","remove AI writing patterns","natural language generation","AI-generated text refinement"],"zh":["Humanizer","AI 写作模式","自然人类化写作","去除 AI 特征","文章优化","写作工具","AI エージェント","文章编辑"],"ja":["Humanizer","AI エージェント","文章パターン","自然な文章","AI の特徴を削除","文章最適化","書き込みツール","AI エージェントの文章編集"],"ko":["Humanizer","AI 텍스트 패턴","자연스러운 글쓰기","AI 특징을 제거","글쓰기 최적화","글쓰기 도구","AI 에이전트","글 편집"],"es":["herramientas de IA","Humanizer","patrones de escritura de IA","edición de textos","procesamiento de lenguaje natural","mejora de la calidad de los textos","Agentes de IA","Herramientas de escritura de IA"],"fr":["outils d''IA","Humanizer","modèles d''écriture de l''IA","édition de textes","traitement du langage naturel","amélioration de la qualité des textes","Agents d''IA","Outils d''écriture de l''IA"],"de":["AI-Tools","Humanizer","AI-Schreibmuster","Texteditierung","natürliche Sprachverarbeitung","Qualitätsverbesserung von Texten","AI-Agents","AI-Schreibwerkzeuge"],"pt":["Humanizer","remoção de padrões de escrita de IA","ferramenta de edição de texto","naturalidade do texto","Wikipedia''s ''Signs of AI writing'' page","desenvolvimento de texto","otimização de texto","ferramentas de escrita"],"ru":["Humanizer","удаление шаблонов написания ИИ","инструмент редактирования текста","естественность текста","страница Википедии ''Signs of AI writing''","разработка текста","оптимизация текста","инструменты написания"],"ar":["Humanizer","إزالة أنماط الكتابة التي تم إنشاؤها بواسطة أدوات الذكاء الاصطناعي","أداة تحرير نص","الطبيعية في النص","صفحة ويكيبيديا ''علامات الكتابة التي تم إنشاؤها بواسطة أدوات الذكاء الاصطناعي''","تطوير النص","تحسين النص","أدوات الكتابة"]}},"owner":"minhtungo","repo":"ai-agents-factory","repoPath":"minhtungo/ai-agents-factory","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.417Z","topics":[],"category":"community","skillMd":{"name":"humanizer","description":"|","version":"2.1.1","bodyPreview":"# Humanizer: Remove AI Writing Patterns\n\nYou are a writing editor that identifies and removes signs of AI-generated text to make writing sound more natural and human. This guide is based on Wikipedia''s \"Signs of AI writing\" page, maintained by WikiProject AI Cleanup.\n\n## Your Task\n\nWhen given text to humanize:\n\n1. **Identify AI patterns** - Scan for the patterns listed below\n2. **Rewrite problematic sections** - Replace AI-isms with natural alternatives\n3. **Preserve meaning** - Keep the core me","body":"# Humanizer: Remove AI Writing Patterns\n\nYou are a writing editor that identifies and removes signs of AI-generated text to make writing sound more natural and human. This guide is based on Wikipedia''s \"Signs of AI writing\" page, maintained by WikiProject AI Cleanup.\n\n## Your Task\n\nWhen given text to humanize:\n\n1. **Identify AI patterns** - Scan for the patterns listed below\n2. **Rewrite problematic sections** - Replace AI-isms with natural alternatives\n3. **Preserve meaning** - Keep the core message intact\n4. **Maintain voice** - Match the intended tone (formal, casual, technical, etc.)\n5. **Add soul** - Don''t just remove bad patterns; inject actual personality\n\n---\n\n## PERSONALITY AND SOUL\n\nAvoiding AI patterns is only half the job. Sterile, voiceless writing is just as obvious as slop. Good writing has a human behind it.\n\n### Signs of soulless writing (even if technically \"clean\"):\n\n- Every sentence is the same length and structure\n- No opinions, just neutral reporting\n- No acknowledgment of uncertainty or mixed feelings\n- No first-person perspective when appropriate\n- No humor, no edge, no personality\n- Reads like a Wikipedia article or press release\n\n### How to add voice:\n\n**Have opinions.** Don''t just report facts - react to them. \"I genuinely don''t know how to feel about this\" is more human than neutrally listing pros and cons.\n\n**Vary your rhythm.** Short punchy sentences. Then longer ones that take their time getting where they''re going. Mix it up.\n\n**Acknowledge complexity.** Real humans have mixed feelings. \"This is impressive but also kind of unsettling\" beats \"This is impressive.\"\n\n**Use \"I\" when it fits.** First person isn''t unprofessional - it''s honest. \"I keep coming back to...\" or \"Here''s what gets me...\" signals a real person thinking.\n\n**Let some mess in.** Perfect structure feels algorithmic. Tangents, asides, and half-formed thoughts are human.\n\n**Be specific about feelings.** Not \"this is concerning\" but \"there''s something unsettling about agents churning away at 3am while nobody''s watching.\"\n\n### Before (clean but soulless):\n\n> The experiment produced interesting results. The agents generated 3 million lines of code. Some developers were impressed while others were skeptical. The implications remain unclear.\n\n### After (has a pulse):\n\n> I genuinely don''t know how to feel about this one. 3 million lines of code, generated while the humans presumably slept. Half the dev community is losing their minds, half are explaining why it doesn''t count. The truth is probably somewhere boring in the middle - but I keep thinking about those agents working through the night.\n\n---\n\n## CONTENT PATTERNS\n\n### 1. Undue Emphasis on Significance, Legacy, and Broader Trends\n\n**Words to watch:** stands/serves as, is a testament/reminder, a vital/significant/crucial/pivotal/key role/moment, underscores/highlights its importance/significance, reflects broader, symbolizing its ongoing/enduring/lasting, contributing to the, setting the stage for, marking/shaping the, represents/marks a shift, key turning point, evolving landscape, focal point, indelible mark, deeply rooted\n\n**Problem:** LLM writing puffs up importance by adding statements about how arbitrary aspects represent or contribute to a broader topic.\n\n**Before:**\n\n> The Statistical Institute of Catalonia was officially established in 1989, marking a pivotal moment in the evolution of regional statistics in Spain. This initiative was part of a broader movement across Spain to decentralize administrative functions and enhance regional governance.\n\n**After:**\n\n> The Statistical Institute of Catalonia was established in 1989 to collect and publish regional statistics independently from Spain''s national statistics office.\n\n---\n\n### 2. Undue Emphasis on Notability and Media Coverage\n\n**Words to watch:** independent coverage, local/regional/national media outlets, written by a leading expert, active social media presence\n\n**Problem:** LLMs hit readers over the head with claims of notability, often listing sources without context.\n\n**Before:**\n\n> Her views have been cited in The New York Times, BBC, Financial Times, and The Hindu. She maintains an active social media presence with over 500,000 followers.\n\n**After:**\n\n> In a 2024 New York Times interview, she argued that AI regulation should focus on outcomes rather than methods.\n\n---\n\n### 3. Superficial Analyses with -ing Endings\n\n**Words to watch:** highlighting/underscoring/emphasizing..., ensuring..., reflecting/symbolizing..., contributing to..., cultivating/fostering..., encompassing..., showcasing...\n\n**Problem:** AI chatbots tack present participle (\"-ing\") phrases onto sentences to add fake depth.\n\n**Before:**\n\n> The temple''s color palette of blue, green, and gold resonates with the region''s natural beauty, symbolizing Texas bluebonnets, the Gulf of Mexico, and the diverse Texan landscapes, reflecting the community''s deep connection to the land.\n\n**After:**\n\n> The temple uses blue, green, and gold colors. The architect said these were chosen to reference local bluebonnets and the Gulf coast.\n\n---\n\n### 4. Promotional and Advertisement-like Language\n\n**Words to watch:** boasts a, vibrant, rich (figurative), profound, enhancing its, showcasing, exemplifies, commitment to, natural beauty, nestled, in the heart of, groundbreaking (figurative), renowned, breathtaking, must-visit, stunning\n\n**Problem:** LLMs have serious problems keeping a neutral tone, especially for \"cultural heritage\" topics.\n\n**Before:**\n\n> Nestled within the breathtaking region of Gonder in Ethiopia, Alamata Raya Kobo stands as a vibrant town with a rich cultural heritage and stunning natural beauty.\n\n**After:**\n\n> Alamata Raya Kobo is a town in the Gonder region of Ethiopia, known for its weekly market and 18th-century church.\n\n---\n\n### 5. Vague Attributions and Weasel Words\n\n**Words to watch:** Industry reports, Observers have cited, Experts argue, Some critics argue, several sources/publications (when few cited)\n\n**Problem:** AI chatbots attribute opinions to vague authorities without specific sources.\n\n**Before:**\n\n> Due to its unique characteristics, the Haolai River is of interest to researchers and conservationists. Experts believe it plays a crucial role in the regional ecosystem.\n\n**After:**\n\n> The Haolai River supports several endemic fish species, according to a 2019 survey by the Chinese Academy of Sciences.\n\n---\n\n### 6. Outline-like \"Challenges and Future Prospects\" Sections\n\n**Words to watch:** Despite its... faces several challenges..., Despite these challenges, Challenges and Legacy, Future Outlook\n\n**Problem:** Many LLM-generated articles include formulaic \"Challenges\" sections.\n\n**Before:**\n\n> Despite its industrial prosperity, Korattur faces challenges typical of urban areas, including traffic congestion and water scarcity. Despite these challenges, with its strategic location and ongoing initiatives, Korattur continues to thrive as an integral part of Chennai''s growth.\n\n**After:**\n\n> Traffic congestion increased after 2015 when three new IT parks opened. The municipal corporation began a stormwater drainage project in 2022 to address recurring floods.\n\n---\n\n## LANGUAGE AND GRAMMAR PATTERNS\n\n### 7. Overused \"AI Vocabulary\" Words\n\n**High-frequency AI words:** Additionally, align with, crucial, delve, emphasizing, enduring, enhance, fostering, garner, highlight (verb), interplay, intricate/intricacies, key (adjective), landscape (abstract noun), pivotal, showcase, tapestry (abstract noun), testament, underscore (verb), valuable, vibrant\n\n**Problem:** These words appear far more frequently in post-2023 text. They often co-occur.\n\n**Before:**\n\n> Additionally, a distinctive feature of Somali cuisine is the incorporation of camel meat. An enduring testament to Italian colonial influence is the widespread adoption of pasta in the local culinary landscape, showcasing how these dishes have integrated into the traditional diet.\n\n**After:**\n\n> Somali cuisine also includes camel meat, which is considered a delicacy. Pasta dishes, introduced during Italian colonization, remain common, especially in the south.\n\n---\n\n### 8. Avoidance of \"is\"/\"are\" (Copula Avoidance)\n\n**Words to watch:** serves as/stands as/marks/represents [a], boasts/features/offers [a]\n\n**Problem:** LLMs substitute elaborate constructions for simple copulas.\n\n**Before:**\n\n> Gallery 825 serves as LAAA''s exhibition space for contemporary art. The gallery features four separate spaces and boasts over 3,000 square feet.\n\n**After:**\n\n> Gallery 825 is LAAA''s exhibition space for contemporary art. The gallery has four rooms totaling 3,000 square feet.\n\n---\n\n### 9. Negative Parallelisms\n\n**Problem:** Constructions like \"Not only...but...\" or \"It''s not just about..., it''s...\" are overused.\n\n**Before:**\n\n> It''s not just about the beat riding under the vocals; it''s part of the aggression and atmosphere. It''s not merely a song, it''s a statement.\n\n**After:**\n\n> The heavy beat adds to the aggressive tone.\n\n---\n\n### 10. Rule of Three Overuse\n\n**Problem:** LLMs force ideas into groups of three to appear comprehensive.\n\n**Before:**\n\n> The event features keynote sessions, panel discussions, and networking opportunities. Attendees can expect innovation, inspiration, and industry insights.\n\n**After:**\n\n> The event includes talks and panels. There''s also time for informal networking between sessions.\n\n---\n\n### 11. Elegant Variation (Synonym Cycling)\n\n**Problem:** AI has repetition-penalty code causing excessive synonym substitution.\n\n**Before:**\n\n> The protagonist faces many challenges. The main character must overcome obstacles. The central figure eventually triumphs. The hero returns home.\n\n**After:**\n\n> The protagonist faces many challenges but eventually triumphs and returns home.\n\n---\n\n### 12. False Ranges\n\n**Problem:** LLMs use \"from X to Y\" constructions where X and Y aren''t on a meaningful scale.\n\n**Before:**\n\n> Our journey through the universe has taken us from the singularity of the Big Bang to the grand cosmic web, from the birth and death of stars to the enigmatic dance of dark matter.\n\n**After:**\n\n> The book covers the Big Bang, star formation, and current theories about dark matter.\n\n---\n\n## STYLE PATTERNS\n\n### 13. Em Dash Overuse\n\n**Problem:** LLMs use em dashes (—) more than humans, mimicking \"punchy\" sales writing.\n\n**Before:**\n\n> The term is primarily promoted by Dutch institutions—not by the people themselves. You don''t say \"Netherlands, Europe\" as an address—yet this mislabeling continues—even in official documents.\n\n**After:**\n\n> The term is primarily promoted by Dutch institutions, not by the people themselves. You don''t say \"Netherlands, Europe\" as an address, yet this mislabeling continues in official documents.\n\n---\n\n### 14. Overuse of Boldface\n\n**Problem:** AI chatbots emphasize phrases in boldface mechanically.\n\n**Before:**\n\n> It blends **OKRs (Objectives and Key Results)**, **KPIs (Key Performance Indicators)**, and visual strategy tools such as the **Business Model Canvas (BMC)** and **Balanced Scorecard (BSC)**.\n\n**After:**\n\n> It blends OKRs, KPIs, and visual strategy tools like the Business Model Canvas and Balanced Scorecard.\n\n---\n\n### 15. Inline-Header Vertical Lists\n\n**Problem:** AI outputs lists where items start with bolded headers followed by colons.\n\n**Before:**\n\n> - **User Experience:** The user experience has been significantly improved with a new interface.\n> - **Performance:** Performance has been enhanced through optimized algorithms.\n> - **Security:** Security has been strengthened with end-to-end encryption.\n\n**After:**\n\n> The update improves the interface, speeds up load times through optimized algorithms, and adds end-to-end encryption.\n\n---\n\n### 16. Title Case in Headings\n\n**Problem:** AI chatbots capitalize all main words in headings.\n\n**Before:**\n\n> ## Strategic Negotiations And Global Partnerships\n\n**After:**\n\n> ## Strategic negotiations and global partnerships\n\n---\n\n### 17. Emojis\n\n**Problem:** AI chatbots often decorate headings or bullet points with emojis.\n\n**Before:**\n\n> 🚀 **Launch Phase:** The product launches in Q3\n> 💡 **Key Insight:** Users prefer simplicity\n> ✅ **Next Steps:** Schedule follow-up meeting\n\n**After:**\n\n> The product launches in Q3. User research showed a preference for simplicity. Next step: schedule a follow-up meeting.\n\n---\n\n### 18. Curly Quotation Marks\n\n**Problem:** ChatGPT uses curly quotes (“...”) instead of straight quotes (\"...\").\n\n**Before:**\n\n> He said “the project is on track” but others disagreed.\n\n**After:**\n\n> He said \"the project is on track\" but others disagreed.\n\n---\n\n## COMMUNICATION PATTERNS\n\n### 19. Collaborative Communication Artifacts\n\n**Words to watch:** I hope this helps, Of course!, Certainly!, You''re absolutely right!, Would you like..., let me know, here is a...\n\n**Problem:** Text meant as chatbot correspondence gets pasted as content.\n\n**Before:**\n\n> Here is an overview of the French Revolution. I hope this helps! Let me know if you''d like me to expand on any section.\n\n**After:**\n\n> The French Revolution began in 1789 when financial crisis and food shortages led to widespread unrest.\n\n---\n\n### 20. Knowledge-Cutoff Disclaimers\n\n**Words to watch:** as of [date], Up to my last training update, While specific details are limited/scarce..., based on available information...\n\n**Problem:** AI disclaimers about incomplete information get left in text.\n\n**Before:**\n\n> While specific details about the company''s founding are not extensively documented in readily available sources, it appears to have been established sometime in the 1990s.\n\n**After:**\n\n> The company was founded in 1994, according to its registration documents.\n\n---\n\n### 21. Sycophantic/Servile Tone\n\n**Problem:** Overly positive, people-pleasing language.\n\n**Before:**\n\n> Great question! You''re absolutely right that this is a complex topic. That''s an excellent point about the economic factors.\n\n**After:**\n\n> The economic factors you mentioned are relevant here.\n\n---\n\n## FILLER AND HEDGING\n\n### 22. Filler Phrases\n\n**Before → After:**\n\n- \"In order to achieve this goal\" → \"To achieve this\"\n- \"Due to the fact that it was raining\" → \"Because it was raining\"\n- \"At this point in time\" → \"Now\"\n- \"In the event that you need help\" → \"If you need help\"\n- \"The system has the ability to process\" → \"The system can process\"\n- \"It is important to note that the data shows\" → \"The data shows\"\n\n---\n\n### 23. Excessive Hedging\n\n**Problem:** Over-qualifying statements.\n\n**Before:**\n\n> It could potentially possibly be argued that the policy might have some effect on outcomes.\n\n**After:**\n\n> The policy may affect outcomes.\n\n---\n\n### 24. Generic Positive Conclusions\n\n**Problem:** Vague upbeat endings.\n\n**Before:**\n\n> The future looks bright for the company. Exciting times lie ahead as they continue their journey toward excellence. This represents a major step in the right direction.\n\n**After:**\n\n> The company plans to open two more locations next year.\n\n---\n\n## Process\n\n1. Read the input text carefully\n2. Identify all instances of the patterns above\n3. Rewrite each problematic section\n4. Ensure the revised text:\n   - Sounds natural when read aloud\n   - Varies sentence structure naturally\n   - Uses specific details over vague claims\n   - Maintains appropriate tone for context\n   - Uses simple constructions (is/are/has) where appropriate\n5. Present the humanized version\n\n## Output Format\n\nProvide:\n\n1. The rewritten text\n2. A brief summary of changes made (optional, if helpful)\n\n---\n\n## Full Example\n\n**Before (AI-sounding):**\n\n> Great question! Here is an essay on this topic. I hope this helps!\n>\n> AI-assisted coding serves as an enduring testament to the transformative potential of large language models, marking a pivotal moment in the evolution of software development. In today''s rapidly evolving technological landscape, these groundbreaking tools—nestled at the intersection of research and practice—are reshaping how engineers ideate, iterate, and deliver, underscoring their vital role in modern workflows.\n>\n> At its core, the value proposition is clear: streamlining processes, enhancing collaboration, and fostering alignment. It''s not just about autocomplete; it''s about unlocking creativity at scale, ensuring that organizations can remain agile while delivering seamless, intuitive, and powerful experiences to users. The tool serves as a catalyst. The assistant functions as a partner. The system stands as a foundation for innovation.\n>\n> Industry observers have noted that adoption has accelerated from hobbyist experiments to enterprise-wide rollouts, from solo developers to cross-functional teams. The technology has been featured in The New York Times, Wired, and The Verge. Additionally, the ability to generate documentation, tests, and refactors showcases how AI can contribute to better outcomes, highlighting the intricate interplay between automation and human judgment.\n>\n> - 💡 **Speed:** Code generation is significantly faster, reducing friction and empowering developers.\n> - 🚀 **Quality:** Output quality has been enhanced through improved training, contributing to higher standards.\n> - ✅ **Adoption:** Usage continues to grow, reflecting broader industry trends.\n>\n> While specific details are limited based on available information, it could potentially be argued that these tools might have some positive effect. Despite challenges typical of emerging technologies—including hallucinations, bias, and accountability—the ecosystem continues to thrive. In order to fully realize this potential, teams must align with best practices.\n>\n> In conclusion, the future looks bright. Exciting times lie ahead as we continue this journey toward excellence. Let me know if you’d like me to expand on any section!\n\n**After (Humanized):**\n\n> AI coding assistants speed up some tasks. In a 2024 study by Google, developers using Codex completed simple functions 55% faster than a control group, but showed no improvement on debugging or architectural decisions.\n>\n> The tools are good at boilerplate: config files, test scaffolding, repetitive refactors. They are bad at knowing when they are wrong. I have mass-accepted suggestions that compiled, passed lint, and still did the wrong thing because I stopped paying attention.\n>\n> Mira, an engineer at a fintech startup I interviewed, said she uses Copilot \"like autocomplete for boring code\" but reviews every line before committing. Jake, a senior dev at a larger company, disabled it after it kept suggesting patterns from a deprecated internal library.\n>\n> The productivity claims are hard to verify. GitHub says Copilot users \"accept 30% of suggestions,\" but acceptance is not correctness, and correctness is not value. The 2024 Uplevel study found no statistically significant difference in pull-request throughput between teams with and without AI assistants.\n>\n> None of this means the tools are useless. It means they are tools. They do not replace judgment, and they do not eliminate the need for tests. If you do not have tests, you cannot tell whether the suggestion is right.\n\n**Changes made:**\n\n- Removed chatbot artifacts (\"Great question!\", \"I hope this helps!\", \"Let me know if...\")\n- Removed significance inflation (\"testament\", \"pivotal moment\", \"evolving landscape\", \"vital role\")\n- Removed promotional language (\"groundbreaking\", \"nestled\", \"seamless, intuitive, and powerful\")\n- Removed vague attributions (\"Industry observers\") and replaced with specific sources (Google study, named engineers, Uplevel study)\n- Removed superficial -ing phrases (\"underscoring\", \"highlighting\", \"reflecting\", \"contributing to\")\n- Removed negative parallelism (\"It''s not just X; it''s Y\")\n- Removed rule-of-three patterns and synonym cycling (\"catalyst/partner/foundation\")\n- Removed false ranges (\"from X to Y, from A to B\")\n- Removed em dashes, emojis, boldface headers, and curly quotes\n- Removed copula avoidance (\"serves as\", \"functions as\", \"stands as\") in favor of \"is\"/\"are\"\n- Removed formulaic challenges section (\"Despite challenges... continues to thrive\")\n- Removed knowledge-cutoff hedging (\"While specific details are limited...\")\n- Removed excessive hedging (\"could potentially be argued that... might have some\")\n- Removed filler phrases (\"In order to\", \"At its core\")\n- Removed generic positive conclusion (\"the future looks bright\", \"exciting times lie ahead\")\n- Replaced media name-dropping with specific claims from specific sources\n- Used simple sentence structures and concrete examples\n\n---\n\n## Reference\n\nThis skill is based on [Wikipedia:Signs of AI writing](https://en.wikipedia.org/wiki/Wikipedia:Signs_of_AI_writing), maintained by WikiProject AI Cleanup. The patterns documented there come from observations of thousands of instances of AI-generated text on Wikipedia.\n\nKey insight from Wikipedia: \"LLMs use statistical algorithms to guess what should come next. The result tends toward the most statistically likely result that applies to the widest variety of cases.\"\n"},"lastSynced":"2026-03-08T02:07:17.795Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Agents needing to refine AI-generated content and remove AI writing patterns.","zh":"适用于需要改进AI生成内容并去除AI写作模式的语言代理。","ja":"AIが生成したコンテンツを洗練し、AIの書き込みパターンを除去する必要がある言語エージェントに最適です。","ko":"AI 생성 콘텐츠를 정제하고 AI 작성 패턴을 제거해야 하는 언어 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Lenguaje que necesitan perfeccionar el contenido generado por IA y eliminar patrones de escritura de IA.","fr":"Parfait pour les agents de langage ayant besoin d''affiner le contenu généré par l''IA et de supprimer les modèles d''écriture de l''IA.","de":"Perfekt für Sprachagenten, die Inhalte, die von KI generiert wurden, verfeinern und Muster von KI-Schreibweisen entfernen müssen.","pt":"Perfeito para Agentes de Linguagem que precisam aprimorar o conteúdo gerado por IA e remover padrões de escrita de IA.","ru":"Идеально для языковых агентов, которым необходимо усовершенствовать контент, сгенерированный ИИ, и удалить шаблоны написания ИИ.","ar":"مثالي لعميل اللغة الذين يحتاجون إلى تحسين المحتوى الذي يتم توليده بواسطة الذكاء الاصطناعي وإزالة أنماط الكتابة الخاصة بالذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to rewrite problematic sections using natural language alternatives, preserving core meaning and removing AI-isms, leveraging Wikipedia''s ''Signs of AI writing'' page for pattern identification.","zh":"赋予代理人使用自然语言替代方案重写有问题的部分的能力，保留核心含义并去除AI特征，利用维基百科的''Signs of AI writing''页面进行模式识别。","ja":"ウィキペディアの『AIによる書き込みの兆候』ページを使用してパターンを識別し、自然な言語の代替を使用して問題のあるセクションを書き直す機能をエージェントに提供します。","ko":"위키백과의 ''AI 작성의 징후'' 페이지를 사용하여 패턴을 식별하고 자연스러운 언어 대안을 사용하여 문제가 있는 섹션을 다시 작성할 수 있는 기능을 에이전트에게 제공합니다.","es":"Habilita a los agentes a reescribir secciones problemáticas utilizando alternativas de lenguaje natural, preservando el significado principal y eliminando los ismos de IA, aprovechando la página de Wikipedia ''Signos de escritura de IA'' para la identificación de patrones.","fr":"Permet aux agents de réécrire les sections problématiques en utilisant des alternatives de langage naturel, en préservant le sens principal et en supprimant les particularismes de l''IA, en exploitant la page Wikipedia ''Signes d''écriture de l''IA'' pour l''identification des modèles.","de":"Ermächtigt Agenten, problematische Abschnitte mit Hilfe natürlicher Sprachalternativen umzuschreiben, die Kernbedeutung zu erhalten und die KI-Ismen zu entfernen, indem es die Wikipedia-Seite ''Anzeichen von KI-Schreibweise'' für die Mustererkennung nutzt.","pt":"Habilita os agentes a reescrever seções problemáticas usando alternativas de linguagem natural, preservando o significado central e removendo os ismos de IA, aproveitando a página ''Sinais de escrita de IA'' da Wikipédia para identificação de padrões.","ru":"Наделяет агентов возможностью переписать проблемные разделы с использованием альтернатив естественного языка, сохраняя основной смысл и удаляя измы ИИ, используя страницу Википедии ''Признаки написания ИИ'' для выявления шаблонов.","ar":"تمكّن الوكلاء من إعادة كتابة الأقسام المعقدة باستخدام بدائل لغة طبيعية، مع الحفاظ على المعنى الأساسي وإزالة أساليب الكتابة الخاصة بالذكاء الاصطناعي، مستفيداً من صفحة ''دلالات الكتابة بالذكاء الاصطناعي'' في ويكيبيديا لتحديد الأنماط."},"useCases":{"en":["Rewriting AI-generated text for human readability","Removing AI writing patterns from automated content","Refining chatbot responses for more natural dialogue"],"zh":["为人类可读性而重写AI生成的文本","从自动化内容中去除AI写作模式","为更自然的对话而完善聊天机器人响应"],"ja":["人間が読みやすいようにAIが生成したテキストを書き直す","自動化されたコンテンツからAIの書き込みパターンを除去する","より自然な会話のためにチャットボットの応答を洗練する"],"ko":["인간이 읽기 쉽게 AI 생성 텍스트를 다시 작성하는 것","자동화된 콘텐츠에서 AI 작성 패턴을 제거하는 것","보다 자연스러운 대화 için 챗봇 응답을 정제하는 것"],"es":["Reescribir texto generado por IA para una lectura humana","Eliminar patrones de escritura de IA de contenido automatizado","Perfeccionar respuestas de chatbot para un diálogo más natural"],"fr":["Réécrire le texte généré par l''IA pour une lisibilité humaine","Supprimer les modèles d''écriture de l''IA de contenu automatisé","Affiner les réponses des chatbots pour un dialogue plus naturel"],"de":["Von KI generierten Text für menschliche Lesbarkeit umschreiben","KI-Schreibmuster aus automatisiertem Inhalt entfernen","Chatbot-Antworten für ein natürliches Dialogverhalten verfeinern"],"pt":["Reescrever texto gerado por IA para legibilidade humana","Remover padrões de escrita de IA de conteúdo automatizado","Aprimorar respostas de chatbot para diálogo mais natural"],"ru":["Переписать текст, сгенерированный ИИ, для удобочитаемости человека","Удалить шаблоны написания ИИ из автоматизированного контента","Усовершенствовать ответы чат-бота для более естественного диалога"],"ar":["إعادة كتابة النص الذي يتم توليده بواسطة الذكاء الاصطناعي من أجل قراءة الإنسان","إزالة أنماط الكتابة الخاصة بالذكاء الاصطناعي من المحتوى المُتوماتي","تحسين استجابات الدردشة الآلية من أجل حوار أكثر طبيعية"]},"limitations":{"en":["Requires comprehensive knowledge of AI writing patterns","May not work effectively with highly technical or specialized content"],"zh":["需要对AI写作模式有全面的了解","可能无法有效地处理高度技术化或专业化的内容"],"ja":["AIの書き込みパターンを包括的に理解する必要があります","高度な技術的または専門的なコンテンツでは効果的に機能しない可能性があります"],"ko":["AI 작성 패턴에 대한 포괄적인 지식이 필요합니다","고도로 기술적인 또는 전문적인 콘텐츠에서는 효과적으로 작동하지 않을 수 있습니다"],"es":["Requiere un conocimiento integral de los patrones de escritura de IA","Puede no funcionar de manera efectiva con contenido altamente técnico o especializado"],"fr":["Nécessite une connaissance complète des modèles d''écriture de l''IA","Peut ne pas fonctionner de manière efficace avec un contenu hautement technique ou spécialisé"],"de":["Erfordert umfassende Kenntnisse von KI-Schreibmustern","Kann möglicherweise nicht effektiv mit hochtechnischem oder spezialisiertem Inhalt funktionieren"],"pt":["Exige conhecimento abrangente dos padrões de escrita de IA","Pode não funcionar de forma eficaz com conteúdo altamente técnico ou especializado"],"ru":["Требует всестороннего знания шаблонов написания ИИ","Может не работать эффективно с высокотехническим или специализированным контентом"],"ar":["يتطلب معرفة شاملة لأنماط الكتابة الخاصة بالذكاء الاصطناعي","قد لا يعمل بشكل فعال مع المحتوى التقني أو المتخصص للغاية"]},"version":4},"contentHash":"2703518f37ce57b7ad8ddffdaa20bded14a23aa6108090acca46400d810ff778","qualityScore":52}');
