INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('minhtungo/ai-agents-factory/humanizer', 'humanizer', 'minhtungo', 'ai-agents-factory', 'community', 'humanizer minhtungo ai-agents-factory community The Humanizer skill helps writing editors remove signs of AI-generated text, making writing sound more natural. It benefits developers and writers who need to refine AI-generated content. Humanizer 是一种去除 AI 写作模式的工具，通过识别和替换 AI 特征，实现自然人类化写作 Humanizer は AI エージェントの文章パターンを削除するツールで、AI の特徴を識別して置き換えることで自然な文章を作成 Humanizer는 AI 텍스트 패턴을 제거하는 도구로, AI 특징을 식별하고 대체하여 자연스러운 글쓰기를 구현 Humanizer es una herramienta que identifica y elimina patrones de escritura de IA para hacer que tus textos suenen más naturales y humanos Humanizer est un outil qui identifie et supprime les modèles d''écriture de l''IA pour rendre vos textes plus naturels et humains Humanizer ist ein Tool, das AI-Schreibmuster identifiziert und entfernt, um Ihre Texte natürlich und menschlich klingen zu lassen O Humanizer é uma ferramenta que identifica e remove padrões de escrita de IA para tornar o texto mais natural Humanizer - это инструмент, который идентифицирует и удаляет шаблоны написания ИИ, чтобы сделать текст более естественным Humanizer هو أداة تحدد و تحذف أنماط الكتابة التي تم إنشاؤها بواسطة أدوات الذكاء الاصطناعي لتجعل النص أكثر طبيعية how to use humanizer what is humanizer humanizer alternative humanizer vs writing assistants humanizer install humanizer setup guide remove AI writing patterns natural language generation AI-generated text refinement Humanizer AI 写作模式 自然人类化写作 去除 AI 特征 文章优化 写作工具 AI エージェント 文章编辑 Identifies AI patterns based on Wikipedia''s Signs of AI writing page Rewrites problematic sections to replace AI-isms with natural alternatives Preserves the core meaning of the original text during rewriting Scans text for specific patterns listed in WikiProject AI Cleanup Replaces AI-generated phrases with more human-like expressions Humanizer is a writing editor skill that identifies and removes AI-generated text patterns to produce more natural and human-like writing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cdalsoniii/brightpath-coder/Authorization Matrix', 'community', 'cdalsoniii', 'brightpath-coder', 'cdalsoniii/brightpath-coder', 'Authorization Matrix', 0, 0, 52, '2026-03-08T01:57:15.473Z', '2026-03-08T02:09:40.923Z', '16075f97fb8929b0ba92cfb89062e0dae778d2d084fe64bf3855ccd536a175f1', '{"id":"cdalsoniii/brightpath-coder/Authorization Matrix","name":"Authorization Matrix","description":{"en":"The Authorization Matrix skill builds a complete authorization matrix from the codebase, verifying every endpoint has appropriate authentication, authorization, and ownership checks, benefiting AI agent developers and DevOps teams.","zh":"Authorization Matrix 通过 BrightPath CLI 构建完整的授权矩阵，验证每个端点的身份验证、授权和所有权检查。支持多提供商 AI 代理编排","ja":"Authorization Matrix は、BrightPath CLI を使用して完全な認可マトリックスを構築し、各エンドポイントの認証、認可、および所有権チェックを確認します。マルチプロバイダー AI エージェントのオーケストレーションをサポートします","ko":"Authorization Matrix는 BrightPath CLI를 사용하여 완전한 인증 매트릭스를 구축하고 각 엔드 포인트의 인증, 인가 및 소유권 확인을 확인합니다. 멀티 프로바이더 AI 에이전트 오케스트레이션을 지원합니다","es":"La matriz de autorización es una habilidad que crea una matriz completa de autorización a partir del código base y verifica que cada endpoint tenga comprobaciones de autenticación, autorización y propiedad adecuadas.","fr":"La matrice d''autorisation est une fonctionnalité qui crée une matrice complète d''autorisation à partir de la base de code et vérifie que chaque point de terminaison ait des vérifications d''authentification, d''autorisation et de propriété appropriées.","de":"Die Autorisierungsmatrix ist eine Fähigkeit, die eine vollständige Autorisierungsmatrix aus dem Codebase erstellt und überprüft, ob jeder Endpunkt über geeignete Authentifizierungs-, Autorisierungs- und Eigentumsprüfungen verfügt.","pt":"A matriz de autorização é uma ferramenta de segurança que verifica a autenticação e autorização de endpoints. O BrightPath CLI é um orchestrador de agentes de IA que ajuda a configurar essa matriz.","ru":"Матрица авторизации - это инструмент безопасности, который проверяет аутентификацию и авторизацию конечных точек. BrightPath CLI - это orchestrator ИИ агентов, который помогает настроить эту матрицу","ar":"مصفوفة الصلاحيات هي أداة أمان تحقق من صلاحية التحقق من الهوية والنقاط النهاية. BrightPath CLI هو منظم لعميل الذكاء الاصطناعي الذي يساعد في إعداد هذه المصفوفة"},"seo":{"title":{"en":"Authorization Matrix: Setup Guide for AI Agents | AI Agen...","zh":"Authorization Matrix 设置指南 - 通过 BrightPath CLI 实现多提供商 AI 代理编排","ja":"Authorization Matrix のベストプラクティス - BrightPath CLI を使用したマルチ...","ko":"Authorization Matrix 설정 가이드 - BrightPath CLI를 사용한 멀티 프로바이...","es":"Guía de configuración de Authorization Matrix para agente...","fr":"Configurer l''Authorization Matrix pour les outils d''intel...","de":"Einrichtungsleitfaden für Authorization Matrix in KI-Agents","pt":"Guia de Configuração da Matriz de Autorização com Ferrame...","ru":"Настройка Матрицы Авторизации с помощью ИИ Агентов","ar":"دليل إعداد مصفوفة الصلاحيات مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to implement a robust authorization system with the Authorization Matrix skill. Learn how to verify endpoint authentication and authorization wi...","zh":"了解如何使用 Authorization Matrix 通过 BrightPath CLI 构建完整的授权矩阵，并验证每个端点的身份验证、授权和所有权检查","ja":"Authorization Matrix を使用して BrightPath CLI で完全な認可マトリックスを構築し、各エンドポイントの認証、認可、および所有権チェックを確認する方法について学びます","ko":"Authorization Matrix를 사용하여 BrightPath CLI에서 완전한 인증 매트릭스를 구축하고 각 엔드 포인트의 인증, 인가 및 소유권 확인을 확인하는 방법에 대해 알아보십시오","es":"Aprende a implementar la matriz de autorización para asegurar endpoints con autenticación y autorización adecuadas en tu proyecto de inteligencia artificial","fr":"Découvrez comment mettre en place la matrice d''autorisation pour sécuriser vos points de terminaison avec une authentification et une autorisation appropriée...","de":"Erfahren Sie, wie Sie die Autorisierungsmatrix implementieren, um Endpunkte mit geeigneter Authentifizierung und Autorisierung in Ihren KI-Projekten zu sichern","pt":"Aprenda a configurar a matriz de autorização com o BrightPath CLI e garanta a segurança dos endpoints com autenticação e autorização adequadas","ru":"Узнайте, как настроить матрицу авторизации с помощью BrightPath CLI и обеспечить безопасность конечных точек с помощью аутентификации и авторизации","ar":"تعرف على كيفية إعداد مصفوفة الصلاحيات مع BrightPath CLI وضمان أمان النقاط النهاية مع التحقق من الصلاحية والتحقق من الهوية"},"definition":{"en":"Authorization Matrix is a technical skill that generates a comprehensive authorization matrix to ensure secure endpoint authentication and authorization in AI agent-based systems.","zh":"Authorization Matrix 是一种通过代码库构建完整的授权矩阵并验证每个端点的身份验证、授权和所有权检查的技术","ja":"Authorization Matrix は、コードベースから完全な認可マトリックスを構築し、各エンドポイントの認証、認可、および所有権チェックを確認する技術です","ko":"Authorization Matrix는 코드베이스에서 완전한 인증 매트릭스를 구축하고 각 엔드 포인트의 인증, 인가 및 소유권 확인을 확인하는 기술입니다","es":"La matriz de autorización es una función que permite crear y verificar la autorización de endpoints en proyectos de inteligencia artificial","fr":"La matrice d''autorisation est une fonction qui permet de créer et de vérifier l''autorisation des points de terminaison dans les outils d''intelligence artificielle","de":"Die Autorisierungsmatrix ist eine Funktion, die die Erstellung und Überprüfung der Autorisierung von Endpunkten in KI-Projekten ermöglicht","pt":"Matriz de autorização é uma tabela que define as permissões de acesso a recursos e endpoints","ru":"Матрица авторизации - это таблица, определяющая разрешения доступа к ресурсам и конечным точкам","ar":"مصفوفة الصلاحيات هي جدول يحدد صلاحيات الوصول إلى الموارد والنقاط النهاية"},"features":{"en":["Triggers on route configuration changes, auth middleware changes, and new handler additions","Supports invocation with ''auth matrix'' or ''authorization-matrix'' commands","Requires path to route configuration (main.go or router files) and middleware directory","Optionally accepts path to additional configuration files","Verifies every endpoint for appropriate authentication, authorization, and ownership checks","Integrates with BrightPath CLI for multi-provider AI agent orchestration"],"zh":["通过 BrightPath CLI 构建完整的授权矩阵","验证每个端点的身份验证、授权和所有权检查","支持多提供商 AI 代理编排","自动检测路由配置变化","自动检测认证中间件变化"],"ja":["BrightPath CLI を使用して完全な認可マトリックスを構築","各エンドポイントの認証、認可、および所有権チェックを確認","マルチプロバイダー AI エージェントのオーケストレーションをサポート","ルート構成の変更を自動的に検出","認証ミドルウェアの変更を自動的に検出"],"ko":["BrightPath CLI를 사용하여 완전한 인증 매트릭스를 구축","각 엔드 포인트의 인증, 인가 및 소유권 확인을 확인","멀티 프로바이더 AI 에이전트 오케스트레이션을 지원","루트 구성 변경을 자동으로 감지","인증 미들웨어 변경을 자동으로 감지"],"es":["Verificación de autenticación y autorización para cada endpoint","Comprobación de propiedad para endpoints","Compatible con cambios en la configuración de rutas y middleware de autenticación","Soporte para nuevos controladores y comandos de usuario","Integración con el CLI de BrightPath"],"fr":["Vérification de l''authentification et de l''autorisation pour chaque point de terminaison","Vérification de propriété pour les points de terminaison","Compatibilité avec les modifications de la configuration des routes et du middleware d''authentification","Prise en charge de nouveaux gestionnaires et de commandes utilisateur","Intégration avec le CLI de BrightPath"],"de":["Überprüfung der Authentifizierung und Autorisierung für jeden Endpunkt","Überprüfung des Eigentums für Endpunkte","Kompatibilität mit Änderungen an der Routenkonfiguration und Authentifizierungsmiddleware","Unterstützung für neue Handler und Benutzerbefehle","Integration mit dem BrightPath-CLI"],"pt":["Verificação de autenticação e autorização de endpoints","Configuração de rotas e middleware de autenticação","Suporte ao BrightPath CLI para orquestração de agentes de IA","Verificação de propriedade e permissões de acesso","Integração com arquivos de configuração de rotas e middleware"],"ru":["Проверка аутентификации и авторизации конечных точек","Настройка маршрутов и middleware аутентификации","Поддержка BrightPath CLI для оркестрации ИИ агентов","Проверка собственности и разрешений доступа","Интеграция с файлами конфигурации маршрутов и middleware"],"ar":["التحقق من صلاحية التحقق من الهوية والنقاط النهاية","إعداد مسارات والبرامج الوسيطة للتحقق من الهوية","دعم BrightPath CLI لتنظيم عميل الذكاء الاصطناعي","التحقق من ملكية وتصريح الوصول","التكامل مع ملفات تكوين المسارات والبرامج الوسيطة"]},"keywords":{"en":["how to use Authorization Matrix","Authorization Matrix setup guide","what is Authorization Matrix","Authorization Matrix alternative","Authorization Matrix vs OAuth","Authorization Matrix install","BrightPath CLI authorization","AI agent security","endpoint authentication and authorization","authorization matrix for DevOps"],"zh":["Authorization Matrix","BrightPath CLI","AI 代理编排","授权矩阵","身份验证","认可","所有权检查","多提供商 AI 代理"],"ja":["Authorization Matrix","BrightPath CLI","AI エージェントのオーケストレーション","認可マトリックス","認証","認可","所有権チェック","マルチプロバイダー AI エージェント"],"ko":["Authorization Matrix","BrightPath CLI","AI 에이전트 오케스트레이션","인증 매트릭스","인증","인가","소유권 확인","멀티 프로바이더 AI 에이전트"],"es":["matriz de autorización","agentes de inteligencia artificial","autenticación y autorización","seguridad de endpoints","BrightPath CLI","configuración de rutas","middleware de autenticación"],"fr":["matrice d''autorisation","outils d''intelligence artificielle","authentification et autorisation","sécurité des points de terminaison","BrightPath CLI","configuration des routes","middleware d''authentification"],"de":["Autorisierungsmatrix","KI-Agents","Authentifizierung und Autorisierung","Sicherheit von Endpunkten","BrightPath-CLI","Routenkonfiguration","Authentifizierungsmiddleware"],"pt":["matriz de autorização","autenticação e autorização","BrightPath CLI","agentes de IA","orquestração de agentes","segurança de endpoints","configuração de rotas","middleware de autenticação"],"ru":["матрица авторизации","аутентификация и авторизация","BrightPath CLI","ИИ агенты","оркестрация агентов","безопасность конечных точек","настройка маршрутов","middleware аутентификации"],"ar":["مصفوفة الصلاحيات","التحقق من الهوية والصلاحية","BrightPath CLI","أدوات الذكاء الاصطناعي","تنظيم عميل الذكاء الاصطناعي","أمان النقاط النهاية","إعداد مسارات","البرامج الوسيطة للتحقق من الهوية"]}},"owner":"cdalsoniii","repo":"brightpath-coder","repoPath":"cdalsoniii/brightpath-coder","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.473Z","topics":[],"category":"community","skillMd":{"name":"Authorization Matrix","description":"Build and verify an authorization matrix mapping roles to endpoints — detect unprotected routes, missing ownership checks, and scope misconfigurations","version":"1.0.0","bodyPreview":"# Authorization Matrix Skill\n\nBuild a complete authorization matrix from the codebase and verify every endpoint has appropriate authentication, authorization, and ownership checks.\n\n## Trigger Conditions\n- Route configuration changes\n- Auth middleware changes\n- New handlers are added\n- User invokes with \"auth matrix\" or \"authorization-matrix\"\n\n## Input Contract\n- **Required:** Path to route configuration (main.go or router files)\n- **Required:** Path to middleware directory\n- **Optional:** Path","body":"# Authorization Matrix Skill\n\nBuild a complete authorization matrix from the codebase and verify every endpoint has appropriate authentication, authorization, and ownership checks.\n\n## Trigger Conditions\n- Route configuration changes\n- Auth middleware changes\n- New handlers are added\n- User invokes with \"auth matrix\" or \"authorization-matrix\"\n\n## Input Contract\n- **Required:** Path to route configuration (main.go or router files)\n- **Required:** Path to middleware directory\n- **Optional:** Path to handler files for ownership check verification\n\n## Output Contract\n- Complete route → auth requirement matrix\n- List of unprotected routes (missing auth middleware)\n- List of routes missing account ownership verification\n- Comparison against the whitelist in rule 121\n\n## Tool Permissions\n- **Read:** Route config, middleware, handler files\n- **Write:** None (read-only analysis)\n- **Search:** Grep for `Use(middleware.Auth`, `GetUserID`, `RequireScope`, `AccountOwnership`\n\n## Execution Steps\n\n1. **Extract all routes**: Parse route registration to build complete endpoint list with HTTP method and path\n2. **Identify auth middleware**: Find which route groups use auth middleware\n3. **Check whitelist**: Compare unauthenticated routes against the whitelist in rule 121\n4. **Verify ownership**: For account-scoped routes (`/accounts/:id/*`), verify ownership middleware is applied\n6. **Report**: Produce authorization matrix with pass/fail per check\n\n## Success Criteria\n- All routes outside the whitelist are authenticated\n- All account-scoped routes verify ownership\n- All financial endpoints require appropriate scopes\n- No route bypasses auth through misconfiguration\n\n## References\n- `.cursor/rules/121-route-auth-enforcement.mdc`\n- `.cursor/rules/042-security-authorization.mdc`\n"},"lastSynced":"2026-03-08T02:09:40.923Z","agentAnalysis":{"suitability":{"en":"Perfect for Security-focused AI Agents needing comprehensive authorization and authentication checks in their codebase.","zh":"非常适合需要在代码库中进行全面授权和身份验证检查的安全性专注的AI代理。","ja":"セキュリティに焦点を当てたAIエージェントがコードベースで包括的な認可と認証チェックを必要とする場合に最適です。","ko":"코드베이스에서 포괄적인 인증 및 인가 확인이 필요한 보안 중심 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de IA con enfoque en Seguridad que necesitan controles de autorización y autenticación completos en su base de código.","fr":"Parfait pour les Agents d''IA axés sur la Sécurité nécessitant des vérifications d''autorisation et d''authentification complètes dans leur base de code.","de":"Perfekt für Sicherheitsorientierte KI-Agents, die umfassende Autorisierungs- und Authentifizierungsprüfungen in ihrem Codebasis benötigen.","pt":"Perfeito para Agentes de IA com foco em Segurança que necessitam de verificações de autorização e autenticação abrangentes no seu código.","ru":"Идеально подходит для агентов ИИ, ориентированных на безопасность, которым требуются всесторонние проверки авторизации и аутентификации в их кодовой базе.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يركزون على الأمن وهم بحاجة إلى عمليات فحص شاملة للتصريح والتحقق من الصحة في قاعدة التعليمات البرمجية الخاصة بهم."},"recommendation":{"en":"Empowers agents to verify endpoint authentication, authorization, and ownership checks using route configuration and middleware analysis, ensuring secure interactions with RESTful APIs and protecting against unauthorized access.","zh":"赋予代理验证端点身份验证、授权和所有权检查的能力，使用路由配置和中间件分析，确保与RESTful API的安全交互并防止未经授权的访问。","ja":"ルーティング構成とミドルウェア分析を使用してエンドポイントの認証、認可、所有権チェックを検証するエージェントを可能にし、RESTful APIとの安全なやり取りを保証し、未認証アクセスから保護します。","ko":"경로 구성 및 미들웨어 분석을 사용하여 엔드ポイント의 인증, 인가 및 소유권 확인을 확인할 수 있는 에이전트를 가능하게 하여 RESTful API와의 보안 상호 작용을 보장하고 未認証 접근으로부터 보호합니다.","es":"Habilita a los agentes a verificar la autenticación de puntos finales, controles de autorización y propietarios utilizando la configuración de rutas y el análisis de middleware, garantizando interacciones seguras con API RESTful y protegiendo contra el acceso no autorizado.","fr":"Permet aux agents de vérifier l''authentification des points de terminaison, les contrôles d''autorisation et les vérifications de propriété en utilisant la configuration des routes et l''analyse de middleware, garantissant des interactions sécurisées avec les API RESTful et protégeant contre l''accès non autorisé.","de":"Ermächtigt Agents, Endpunkt-Authentifizierung, Autorisierungs- und Eigentumsprüfungen unter Verwendung von Routenkonfiguration und Middleware-Analyse zu überprüfen, um sichere Interaktionen mit RESTful-APIs sicherzustellen und vor unbefugtem Zugriff zu schützen.","pt":"Habilita os agentes a verificar a autenticação de endpoint, autorização e verificações de propriedade usando configuração de rota e análise de middleware, garantindo interações seguras com APIs RESTful e protegendo contra acessos não autorizados.","ru":"Наделяет агентов возможностью проверять аутентификацию конечных точек, авторизацию и проверки владения с помощью конфигурации маршрута и анализа middleware, обеспечивая безопасное взаимодействие с RESTful API и защищая от несанкционированного доступа.","ar":"يتمكن الوكلاء من التحقق من عمليات التحقق من صحة النقطة النهائية والتصريح والفحص الملكية باستخدام تكوين الطريق وتحليل البرامج الوسيطة، مما يضمن التفاعلات الآمنة مع واجهات برمجة التطبيقات RESTful وحماية ضد الوصول غير المصرح به."},"useCases":{"en":["Validating authentication middleware changes","Generating complete authorization matrices from codebases","Debugging endpoint ownership checks"],"zh":["验证身份验证中间件更改","从代码库生成完整的授权矩阵","调试端点所有权检查"],"ja":["認証ミドルウェアの変更を検証する","コードベースから完全な認可マトリックスを生成する","エンドポイントの所有権チェックをデバッグする"],"ko":["인증 미들웨어 변경 사항을 검증하는 것","코드베이스에서 완전한 인가 행렬을 생성하는 것","엔드포인트 소유권 확인을 디버깅하는 것"],"es":["Validar cambios en el middleware de autenticación","Generar matrices de autorización completas a partir de bases de código","Depurar controles de propiedad de puntos finales"],"fr":["Valider les modifications du middleware d''authentification","Générer des matrices d''autorisation complètes à partir de bases de code","Déboguer les contrôles de propriété des points de terminaison"],"de":["Änderungen an der Authentifizierungs-Middleware überprüfen","Vollständige Autorisierungsmatrizen aus Codebasen generieren","Eigentumsprüfungen von Endpunkten debuggen"],"pt":["Validar alterações no middleware de autenticação","Gerar matrizes de autorização completas a partir de código","Depurar verificações de propriedade de endpoint"],"ru":["Проверка изменений в middleware аутентификации","Генерация полных матриц авторизации из кода","Отладка проверок владения конечной точкой"],"ar":["التحقق من صحة التغييرات في البرامج الوسيطة للتحقق من الصحة","генерация مصفوفات صلاحية كاملة من التعليمات البرمجية","تصحيح أخطاء فحص ملكية النقطة النهائية"]},"limitations":{"en":["Requires access to route configuration files","Needs path to middleware directory","Limited to codebases with explicit authentication and authorization implementations"],"zh":["需要访问路由配置文件","需要中间件目录路径","仅限于具有明确身份验证和授权实现的代码库"],"ja":["ルーティング構成ファイルへのアクセスが必要","ミドルウェアディレクトリへのパスが必要","明示的な認証と認可の実装を持つコードベースに限定される"],"ko":["경로 구성 파일에 대한 액세스가 필요합니다.","미들웨어 디렉토리 경로가 필요합니다.","명시적인 인증 및 인가 구현이 있는 코드베이스로 제한됩니다."],"es":["Requiere acceso a archivos de configuración de rutas","Necesita ruta al directorio de middleware","Limitado a bases de código con implementaciones de autenticación y autorización explícitas"],"fr":["Nécessite un accès aux fichiers de configuration des routes","A besoin du chemin d''accès au répertoire de middleware","Limité aux bases de code avec des implémentations d''authentification et d''autorisation explicites"],"de":["Benötigt Zugriff auf Routenkonfigurationsdateien","Benötigt Pfad zum Middleware-Verzeichnis","Begrenzt auf Codebasen mit expliziten Authentifizierungs- und Autorisierungsimplementierungen"],"pt":["Requer acesso a arquivos de configuração de rota","Necessita do caminho para o diretório de middleware","Limitado a código com implementações de autenticação e autorização explícitas"],"ru":["Требует доступа к файлам конфигурации маршрута","Требует пути к каталогу middleware","Ограничен кодом с явными реализациями аутентификации и авторизации"],"ar":["يتطلب الوصول إلى ملفات تكوين الطريق","يحتاج إلى مسار إلى دليل البرامج الوسيطة","محدود بالكود الذي يحتوي على عمليات تنفيذ صريحة للتحقق من الصحة والتصريح"]},"version":4},"contentHash":"16075f97fb8929b0ba92cfb89062e0dae778d2d084fe64bf3855ccd536a175f1","qualityScore":52}');
