INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cdalsoniii/brightpath-coder/Authorization Matrix', 'Authorization Matrix', 'cdalsoniii', 'brightpath-coder', 'community', 'Authorization Matrix cdalsoniii brightpath-coder community The Authorization Matrix skill builds a complete authorization matrix from the codebase, verifying every endpoint has appropriate authentication, authorization, and ownership checks, benefiting AI agent developers and DevOps teams. Authorization Matrix 通过 BrightPath CLI 构建完整的授权矩阵，验证每个端点的身份验证、授权和所有权检查。支持多提供商 AI 代理编排 Authorization Matrix は、BrightPath CLI を使用して完全な認可マトリックスを構築し、各エンドポイントの認証、認可、および所有権チェックを確認します。マルチプロバイダー AI エージェントのオーケストレーションをサポートします Authorization Matrix는 BrightPath CLI를 사용하여 완전한 인증 매트릭스를 구축하고 각 엔드 포인트의 인증, 인가 및 소유권 확인을 확인합니다. 멀티 프로바이더 AI 에이전트 오케스트레이션을 지원합니다 La matriz de autorización es una habilidad que crea una matriz completa de autorización a partir del código base y verifica que cada endpoint tenga comprobaciones de autenticación, autorización y propiedad adecuadas. La matrice d''autorisation est une fonctionnalité qui crée une matrice complète d''autorisation à partir de la base de code et vérifie que chaque point de terminaison ait des vérifications d''authentification, d''autorisation et de propriété appropriées. Die Autorisierungsmatrix ist eine Fähigkeit, die eine vollständige Autorisierungsmatrix aus dem Codebase erstellt und überprüft, ob jeder Endpunkt über geeignete Authentifizierungs-, Autorisierungs- und Eigentumsprüfungen verfügt. A matriz de autorização é uma ferramenta de segurança que verifica a autenticação e autorização de endpoints. O BrightPath CLI é um orchestrador de agentes de IA que ajuda a configurar essa matriz. Матрица авторизации - это инструмент безопасности, который проверяет аутентификацию и авторизацию конечных точек. BrightPath CLI - это orchestrator ИИ агентов, который помогает настроить эту матрицу مصفوفة الصلاحيات هي أداة أمان تحقق من صلاحية التحقق من الهوية والنقاط النهاية. BrightPath CLI هو منظم لعميل الذكاء الاصطناعي الذي يساعد في إعداد هذه المصفوفة how to use Authorization Matrix Authorization Matrix setup guide what is Authorization Matrix Authorization Matrix alternative Authorization Matrix vs OAuth Authorization Matrix install BrightPath CLI authorization AI agent security endpoint authentication and authorization authorization matrix for DevOps Authorization Matrix BrightPath CLI AI 代理编排 授权矩阵 身份验证 认可 所有权检查 多提供商 AI 代理 Triggers on route configuration changes, auth middleware changes, and new handler additions Supports invocation with ''auth matrix'' or ''authorization-matrix'' commands Requires path to route configuration (main.go or router files) and middleware directory Optionally accepts path to additional configuration files Verifies every endpoint for appropriate authentication, authorization, and ownership checks Integrates with BrightPath CLI for multi-provider AI agent orchestration Authorization Matrix is a technical skill that generates a comprehensive authorization matrix to ensure secure endpoint authentication and authorization in AI agent-based systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tebjan/vvvv-skills/vvvv-editor-extensions', 'community', 'tebjan', 'vvvv-skills', 'tebjan/vvvv-skills', 'vvvv-editor-extensions', 0, 0, 52, '2026-03-08T01:57:15.661Z', '2026-03-08T02:14:06.231Z', '27e0e4337eddf89988842c8dd7fa7ce34fe527d0ea53353e4a738673b6f3f4bd', '{"id":"tebjan/vvvv-skills/vvvv-editor-extensions","name":"vvvv-editor-extensions","description":{"en":"The vvvv-editor-extensions skill enables AI Agents to master the vvvv gamma ecosystem by creating custom extensions using VL patches and NuGet packages. This skill benefits developers working with vvvv gamma.","zh":"vvvv编辑器扩展技能提供了一种使用VL patches和NuGet引用的方式来增强AIエージェント的能力","ja":"vvvvエディターエクステンションは、VL patchesとNuGet参照を使用してAIエージェントの機能を拡張します","ko":"vvvv 편집기 확장 기능은 VL 패치와 NuGet 참조를 사용하여 AI Tools의 기능을 확장합니다","es":"Las extensiones de editor vvvv permiten a los agentes de inteligencia artificial mejorar la productividad en el ecosistema vvvv gamma. Aprende a crear y utilizar estas extensiones.","fr":"Les extensions d''édition vvvv permettent aux agents d''intelligence artificielle d''améliorer la productivité dans l''écosystème vvvv gamma. Découvrez comment créer et utiliser ces extensions.","de":"Die Editor-Erweiterungen von vvvv ermöglichen es KI-Agents, die Produktivität im vvvv-Gamma-Ökosystem zu verbessern. Erfahren Sie, wie Sie diese Erweiterungen erstellen und verwenden.","pt":"As extensões do editor vvvv são patches VL padrão salvos com sufixo .HDE.vl, que executam automaticamente ao serem abertos no editor.","ru":"Расширения редактора vvvv являются стандартными патчами VL, сохраненными с суффиксом .HDE.vl, которые запускаются автоматически при открытии в редакторе.","ar":"ملحقات محرر vvvv هي باتشات VL قياسية محفوظة بسuffix .HDE.vl، والتي تعمل تلقائيًا عند فتحها في المحرر."},"seo":{"title":{"en":"vvvv-editor-extensions: Mastering vvvv Gamma Ecosystem | ...","zh":"vvvv编辑器扩展Setup Guide","ja":"vvvvエディターエクステンションBest Practices","ko":"vvvv 편집기 확장 기능 설정 가이드","es":"Guía de configuración de extensiones de editor vvvv","fr":"Guide de mise en place des extensions d''édition vvvv","de":"Einrichtungsleitfaden für vvvv-Editor-Erweiterungen","pt":"Guia de Configuração de Extensões do Editor vvvv","ru":"Руководство по настройке расширений редактора vvvv для ИИ...","ar":"دليل إعداد ملحقات محرر vvvv للأدوات الذكية"},"description":{"en":"Unlock the full potential of vvvv gamma with expert extensions. Learn how to create and deploy custom .HDE.vl patches and NuGet packages for AI Agents.","zh":"了解如何使用vvvv编辑器扩展技能，通过VL patches和NuGet引用来增强AIエージェント的能力","ja":"vvvvエディターエクステンションを使用してAIエージェントの機能を拡張する方法を学ぶ","ko":"AI Tools를 위한 vvvv 편집기 확장 기능을 사용하여 기능을 확장하는 방법을 알아보세요","es":"Aprende a dominar el ecosistema vvvv gamma con habilidades de extensiones de editor para agentes de inteligencia artificial","fr":"Découvrez comment maîtriser l''écosystème vvvv gamma avec des compétences en extensions d''édition pour les agents d''intelligence artificielle","de":"Erfahren Sie, wie Sie das vvvv-Gamma-Ökosystem mit Fähigkeiten in Editor-Erweiterungen für KI-Agents meistern","pt":"Aprenda a criar e configurar extensões do editor vvvv para melhorar a produtividade dos desenvolvedores","ru":"Узнайте, как создавать и настраивать расширения редактора vvvv для повышения производительности ИИ Агентов","ar":"تعرف على كيفية إنشاء وتكوين ملحقات محرر vvvv لتحسين أداء الأدوات الذكية"},"definition":{"en":"vvvv-editor-extensions is a set of skills for AI Agents to create and manage custom extensions for the vvvv gamma ecosystem using .HDE.vl patches and NuGet packages.","zh":"vvvv编辑器扩展是一种使用VL patches和NuGet引用的方式来增强AIエージェント的能力","ja":"vvvvエディターエクステンションは、AIエージェントの機能を拡張するためのVL patchesとNuGet参照の仕組み","ko":"vvvv 편집기 확장 기능은 AI Tools의 기능을 확장하기 위한 VL 패치와 NuGet 참조의 방법","es":"Extensiones de editor vvvv son parches VL estándar guardados con sufijo .HDE.vl","fr":"Les extensions d''édition vvvv sont des patches VL standard enregistrés avec le suffixe .HDE.vl","de":"vvvv-Editor-Erweiterungen sind Standard-VL-Patches, die mit der Erweiterung .HDE.vl gespeichert werden","pt":"Extensões do editor vvvv são patches VL que melhoram a funcionalidade do editor","ru":"Расширения редактора vvvv являются патчами VL, которые улучшают функциональность редактора","ar":"ملحقات محرر vvvv هي باتشات VL التي تحسن من وظيفة المحرر"},"features":{"en":["Creates custom extensions using VL patches saved with a .HDE.vl suffix","Automatically runs extensions when opened in the editor","Supports standalone extensions and NuGet packages with specific naming conventions","Utilizes VL.HDE NuGet reference for Command node and window types","Enables creation of mixed NuGet packages with main and extension documents"],"zh":["使用VL patches创建扩展","通过NuGet引用VL.HDE","支持Standalone扩展和NuGet扩展","文件命名规范：VL.MyExtension.HDE.vl","自动运行扩展","提供Command节点和WindowFactory"],"ja":["VL patchesを使用してエクステンションを作成","NuGet参照を使用してVL.HDEをインストール","StandaloneエクステンションとNuGetエクステンションをサポート","ファイル命名規則：VL.MyExtension.HDE.vl","エクステンションを自動的に実行","CommandノードとWindowFactoryを提供"],"ko":["VL 패치를 사용하여 확장 기능을 생성","NuGet 참조를 사용하여 VL.HDE를 설치","독립형 확장 기능과 NuGet 확장 기능을 지원","파일 이름 규칙：VL.MyExtension.HDE.vl","확장 기능을 자동으로 실행","Command 노드와 WindowFactory를 제공"],"es":["Creación de extensiones de editor con parches VL","Uso de la referencia NuGet VL.HDE","Compatibilidad con nombres de archivo personalizados","Integración con el ecosistema vvvv gamma","Automatización de tareas con comandos de ventana","Soporte para paquetes NuGet mixtos"],"fr":["Création d''extensions d''édition avec des patches VL","Utilisation de la référence NuGet VL.HDE","Compatibilité avec des noms de fichiers personnalisés","Intégration avec l''écosystème vvvv gamma","Automatisation de tâches avec des commandes de fenêtre","Prise en charge de packages NuGet mixtes"],"de":["Erstellung von Editor-Erweiterungen mit VL-Patches","Verwendung der NuGet-Referenz VL.HDE","Kompatibilität mit benutzerdefinierten Dateinamen","Integration in das vvvv-Gamma-Ökosystem","Automatisierung von Aufgaben mit Fensterbefehlen","Unterstützung für gemischte NuGet-Pakete"],"pt":["Criação de extensões com sufixo .HDE.vl","Execução automática das extensões no editor","Requisitos de referência NuGet, incluindo VL.HDE","Compatibilidade com pacotes NuGet","Nomenclatura de arquivos específica para contextos diferentes"],"ru":["Создание расширений с суффиксом .HDE.vl","Автоматический запуск расширений в редакторе","Требования к ссылкам NuGet, включая VL.HDE","Совместимость с пакетами NuGet","Специфическая номенклатура файлов для разных контекстов"],"ar":["إنشاء ملحقات بسuffix .HDE.vl","تشغيل تلقائي للملحقات في المحرر","متطلبات مرجعية NuGet، بما في ذلك VL.HDE","توافق مع حزم NuGet","تسمية الملفات النوعية لمختلف السياقات"]},"keywords":{"en":["how to use vvvv-editor-extensions","vvvv-editor-extensions setup guide","what is vvvv-editor-extensions","vvvv-editor-extensions alternative","vvvv-editor-extensions vs VL","installing vvvv-editor-extensions","mastering vvvv gamma ecosystem","creating custom .HDE.vl patches","NuGet packages for vvvv gamma"],"zh":["vvvv编辑器扩展","AIエージェント","VL patches","NuGet","VL.HDE","Command节点","WindowFactory","Standalone扩展","NuGet扩展"],"ja":["vvvvエディターエクステンション","AIエージェント","VL patches","NuGet","VL.HDE","Commandノード","WindowFactory","Standaloneエクステンション","NuGetエクステンション"],"ko":["vvvv 편집기 확장 기능","AI Tools","VL 패치","NuGet","VL.HDE","Command 노드","WindowFactory","독립형 확장 기능","NuGet 확장 기능"],"es":["extensiones de editor vvvv","agentes de inteligencia artificial","ecosistema vvvv gamma","parches VL","NuGet VL.HDE","automatización de tareas","integración con vvvv gamma","desarrollo de extensiones de editor"],"fr":["extensions d''édition vvvv","agents d''intelligence artificielle","écosystème vvvv gamma","patches VL","NuGet VL.HDE","automatisation de tâches","intégration avec vvvv gamma","développement d''extensions d''édition"],"de":["Editor-Erweiterungen von vvvv","KI-Agents","vvvv-Gamma-Ökosystem","VL-Patches","NuGet VL.HDE","Automatisierung von Aufgaben","Integration in das vvvv-Gamma-Ökosystem","Entwicklung von Editor-Erweiterungen"],"pt":["vvvv editor extensions","extensões do editor vvvv","VL patches","NuGet references","desenvolvimento de extensões","guias de configuração"],"ru":["расширения редактора vvvv","ИИ Агенты","VL патчи","ссылки NuGet","разработка расширений","руководства по настройке"],"ar":["ملحقات محرر vvvv","الأدوات الذكية","باتشات VL","مراجع NuGet","تطوير الملحقات","دليل إعداد الملحقات"]}},"owner":"tebjan","repo":"vvvv-skills","repoPath":"tebjan/vvvv-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.661Z","topics":[],"category":"community","skillMd":{"name":"vvvv-editor-extensions","description":"Helps create vvvv gamma editor extensions — .HDE.vl file naming, Command node registration with keyboard shortcuts, SkiaWindow/SkiaWindowTopMost window types, docking with WindowFactory, and API access to hovered/selected nodes via VL.Lang Session nodes. Use when building editor plugins, custom tooling windows, or automating editor workflows.","version":"1.0","bodyPreview":"# Editor Extensions\n\nExtensions are standard VL patches saved with a `.HDE.vl` suffix. They run automatically when open in the editor.\n\n## File Naming\n\n| Context | Required Name |\n|---|---|\n| Standalone extension | `VL.MyExtension.HDE.vl` |\n| Extension-only NuGet | `VL.MyExtension.HDE` (package ID) |\n| Mixed NuGet main doc | `VL.MyPackage.vl` |\n| Mixed NuGet extension doc | `VL.MyPackage.HDE.vl` |\n\n## Required NuGet References\n\n- **VL.HDE** — provides `Command` node, window types, `WindowFactory","body":"# Editor Extensions\n\nExtensions are standard VL patches saved with a `.HDE.vl` suffix. They run automatically when open in the editor.\n\n## File Naming\n\n| Context | Required Name |\n|---|---|\n| Standalone extension | `VL.MyExtension.HDE.vl` |\n| Extension-only NuGet | `VL.MyExtension.HDE` (package ID) |\n| Mixed NuGet main doc | `VL.MyPackage.vl` |\n| Mixed NuGet extension doc | `VL.MyPackage.HDE.vl` |\n\n## Required NuGet References\n\n- **VL.HDE** — provides `Command` node, window types, `WindowFactory`\n- **VL.Lang** — provides API nodes under the `Session` category\n\n## Command Node\n\nRegisters a command in the editor menu:\n\n| Pin | Purpose |\n|---|---|\n| `Label` | Menu text |\n| `Visible` | Show/hide the command |\n| `Shortcut` | Keyboard binding |\n| Output | Triggers (bang) on activation |\n\nMultiple `Command` nodes can live in one `.HDE.vl` document.\n\n**Warning**: A runtime error in one command may affect all others in the same document.\n\n## Window Types\n\n| Type | Behavior |\n|---|---|\n| `SkiaWindow` | Slimmed-down Skia renderer window |\n| `SkiaWindowTopMost` | Always-on-top, no focus steal |\n\n## Docking\n\nWrap window with `WindowFactory` node. Connect `WindowContext` and `Window` pins.\n\nTemplate: `VL.HDE/Template.HDE.vl`\n\n## API Access\n\nAccess hovered/selected nodes, read/write pins via `VL.Lang` `Session` category nodes. Browse available API in the HelpBrowser''s `API` section.\n\n## Developer Shortcuts\n\n- **Shift+F9** — restarts all extensions simultaneously\n\n## Limitations\n\n- Settings panel integration is not yet possible\n- Extensions only run in the editor, not in exported applications\n"},"lastSynced":"2026-03-08T02:14:06.231Z","agentAnalysis":{"suitability":{"en":"Perfect for Visual Programming Agents needing custom vvvv gamma ecosystem extensions","zh":"非常适合需要自定义 vvvv gamma 生态系统扩展的视觉编程代理","ja":"カスタムの vvvv gamma エコシステム拡張を必要とするビジュアルプログラミングエージェントに最適","ko":"사용자 지정 vvvv gamma 생태계 확장을 필요로 하는 시각적 프로그래밍 에이전트에 적합","es":"Perfecto para agentes de programación visual que necesitan extensiones personalizadas del ecosistema vvvv gamma","fr":"Parfait pour les agents de programmation visuelle ayant besoin d''extensions d''écosystème vvvv gamma personnalisées","de":"Perfekt für visuelle Programmierungsagenten, die benutzerdefinierte vvvv gamma-Ökosystemerweiterungen benötigen","pt":"Perfeito para Agentes de Programação Visual que necessitam de extensões personalizadas do ecossistema vvvv gamma","ru":"Идеально для Визуальных Программных Агентов, требующих пользовательских расширений экосистемы vvvv gamma","ar":"مثالي لعميل البرمجة البصرية الذين يحتاجون إلى امتدادات مخصصة لمحيط نظام vvvv gamma"},"recommendation":{"en":"Empowers agents to create custom extensions using VL patches and NuGet packages, leveraging the VL.HDE library and .HDE.vl file format for seamless integration with the vvvv gamma editor","zh":"赋予代理使用 VL 补丁和 NuGet 包创建自定义扩展的能力，利用 VL.HDE 库和 .HDE.vl 文件格式实现与 vvvv gamma 编辑器的无缝集成","ja":"VL パッチと NuGet パッケージを使用してカスタム拡張を作成するエージェントを可能にし、VL.HDE ライブラリと .HDE.vl ファイル形式を使用して vvvv gamma エディターとのシームレスな統合を実現","ko":"VL 패치와 NuGet 패키지를 사용하여 사용자 지정 확장을 생성할 수 있는 에이전트를 강화하여 VL.HDE 라이브러리와 .HDE.vl 파일 형식을 사용하여 vvvv gamma 편집기와의 無縫な統合을 제공","es":"Habilita a los agentes a crear extensiones personalizadas utilizando parches VL y paquetes NuGet, aprovechando la biblioteca VL.HDE y el formato de archivo .HDE.vl para una integración sin problemas con el editor vvvv gamma","fr":"Permet aux agents de créer des extensions personnalisées à l''aide de correctifs VL et de packages NuGet, en exploitant la bibliothèque VL.HDE et le format de fichier .HDE.vl pour une intégration transparente avec l''éditeur vvvv gamma","de":"Ermächtigt die Agenten, benutzerdefinierte Erweiterungen mithilfe von VL-Patches und NuGet-Paketen zu erstellen, die VL.HDE-Bibliothek und das .HDE.vl-Dateiformat für eine nahtlose Integration mit dem vvvv gamma-Editor nutzend","pt":"Habilita os agentes a criar extensões personalizadas usando patches VL e pacotes NuGet, aproveitando a biblioteca VL.HDE e o formato de arquivo .HDE.vl para integração perfeita com o editor vvvv gamma","ru":"Наделяет агентов возможностью создавать пользовательские расширения с помощью патчей VL и пакетов NuGet, используя библиотеку VL.HDE и формат файла .HDE.vl для бесшовной интеграции с редактором vvvv gamma","ar":"يمكن للعميل من إنشاء امتدادات مخصصة باستخدامVL patches و NuGet packages، واستخدام مكتبة VL.HDE وتنسيق الملف .HDE.vl من أجل التكامل السلس مع محرر vvvv gamma"},"useCases":{"en":["Automating vvvv gamma workflow optimizations using custom VL patches","Generating reusable extensions for the vvvv gamma ecosystem","Debugging VL patches with the VL.HDE Command node and window types"],"zh":["使用自定义 VL 补丁自动优化 vvvv gamma 工作流","为 vvvv gamma 生态系统生成可重用扩展","使用 VL.HDE 命令节点和窗口类型调试 VL 补丁"],"ja":["カスタム VL パッチを使用して vvvv gamma ワークフローを自動最適化","vvvv gamma エコシステム用の再利用可能な拡張を生成","VL.HDE コマンド ノードとウィンドウ タイプを使用して VL パッチをデバッグ"],"ko":["사용자 지정 VL 패치를 사용하여 vvvv gamma 워크플로우를 자동 최적화","vvvv gamma 생태계를 위한 재사용 가능한 확장을 생성","VL.HDE 명령 노드와 창 유형을 사용하여 VL 패치를 디버깅"],"es":["Automatización de optimizaciones de flujo de trabajo de vvvv gamma utilizando parches VL personalizados","Generación de extensiones reutilizables para el ecosistema vvvv gamma","Depuración de parches VL con el nodo de comando VL.HDE y los tipos de ventana"],"fr":["Automatisation de l''optimisation du flux de travail vvvv gamma à l''aide de correctifs VL personnalisés","Génération d''extensions réutilisables pour l''écosystème vvvv gamma","Débogage de correctifs VL avec le nœud de commande VL.HDE et les types de fenêtres"],"de":["Automatisierung der Optimierung des vvvv gamma-Arbeitsablaufs mithilfe benutzerdefinierter VL-Patches","Erzeugung wiederverwendbarer Erweiterungen für das vvvv gamma-Ökosystem","Fehlerbehebung von VL-Patches mit dem VL.HDE-Befehlsknoten und Fenstertypen"],"pt":["Automatizar otimizações de fluxo de trabalho do vvvv gamma usando patches VL personalizados","Gerar extensões reutilizáveis para o ecossistema vvvv gamma","Depurar patches VL com o nó de comando VL.HDE e tipos de janela"],"ru":["Автоматизация оптимизаций рабочего процесса vvvv gamma с помощью пользовательских патчей VL","Генерация повторно используемых расширений для экосистемы vvvv gamma","Отладка патчей VL с помощью узла команды VL.HDE и типов окон"],"ar":["التحكم الآلي لتحسينات تدفق العمل في نظام vvvv gamma باستخدامVL patches مخصصة","إنشاء امتدادات قابلة لإعادة الاستخدام لمحيط نظام vvvv gamma","تصحيح أخطاء VL patches باستخدام노 VL.HDE و أنواع النوافذ"]},"limitations":{"en":["Requires vvvv gamma ecosystem setup","Limited to .HDE.vl file format for extensions","Dependent on VL.HDE NuGet package for functionality"],"zh":["需要 vvvv gamma 生态系统设置","仅限于 .HDE.vl 文件格式用于扩展","依赖于 VL.HDE NuGet 包用于功能"],"ja":["vvvv gamma エコシステムの設定が必要","拡張には .HDE.vl ファイル形式のみが使用できる","機能には VL.HDE NuGet パッケージに依存"],"ko":["vvvv gamma 생태계 설정이 필요","확장에는 .HDE.vl 파일 형식만 사용할 수 있음","기능에는 VL.HDE NuGet 패키지에 의존"],"es":["Requiere configuración del ecosistema vvvv gamma","Limitado al formato de archivo .HDE.vl para extensiones","Dependiente del paquete NuGet VL.HDE para la funcionalidad"],"fr":["Nécessite la configuration de l''écosystème vvvv gamma","Limité au format de fichier .HDE.vl pour les extensions","Dépendant du package NuGet VL.HDE pour la fonctionnalité"],"de":["Benötigt die Einrichtung des vvvv gamma-Ökosystems","Begrenzt auf das .HDE.vl-Dateiformat für Erweiterungen","Abhängig vom VL.HDE-NuGet-Paket für die Funktionalität"],"pt":["Requer configuração do ecossistema vvvv gamma","Limitado ao formato de arquivo .HDE.vl para extensões","Dependente do pacote NuGet VL.HDE para funcionalidade"],"ru":["Требует настройки экосистемы vvvv gamma","Ограничен форматом файла .HDE.vl для расширений","Зависит от пакета NuGet VL.HDE для функциональности"],"ar":["يتطلب إعداد محيط نظام vvvv gamma","محدود بتنسيق الملف .HDE.vl للأمتدادات","يعتمد على حزمة NuGet VL.HDE للوظائف"]},"version":4},"contentHash":"27e0e4337eddf89988842c8dd7fa7ce34fe527d0ea53353e4a738673b6f3f4bd","qualityScore":52}');
