INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tebjan/vvvv-skills/vvvv-editor-extensions', 'vvvv-editor-extensions', 'tebjan', 'vvvv-skills', 'community', 'vvvv-editor-extensions tebjan vvvv-skills community The vvvv-editor-extensions skill enables AI Agents to master the vvvv gamma ecosystem by creating custom extensions using VL patches and NuGet packages. This skill benefits developers working with vvvv gamma. vvvv编辑器扩展技能提供了一种使用VL patches和NuGet引用的方式来增强AIエージェント的能力 vvvvエディターエクステンションは、VL patchesとNuGet参照を使用してAIエージェントの機能を拡張します vvvv 편집기 확장 기능은 VL 패치와 NuGet 참조를 사용하여 AI Tools의 기능을 확장합니다 Las extensiones de editor vvvv permiten a los agentes de inteligencia artificial mejorar la productividad en el ecosistema vvvv gamma. Aprende a crear y utilizar estas extensiones. Les extensions d''édition vvvv permettent aux agents d''intelligence artificielle d''améliorer la productivité dans l''écosystème vvvv gamma. Découvrez comment créer et utiliser ces extensions. Die Editor-Erweiterungen von vvvv ermöglichen es KI-Agents, die Produktivität im vvvv-Gamma-Ökosystem zu verbessern. Erfahren Sie, wie Sie diese Erweiterungen erstellen und verwenden. As extensões do editor vvvv são patches VL padrão salvos com sufixo .HDE.vl, que executam automaticamente ao serem abertos no editor. Расширения редактора vvvv являются стандартными патчами VL, сохраненными с суффиксом .HDE.vl, которые запускаются автоматически при открытии в редакторе. ملحقات محرر vvvv هي باتشات VL قياسية محفوظة بسuffix .HDE.vl، والتي تعمل تلقائيًا عند فتحها في المحرر. how to use vvvv-editor-extensions vvvv-editor-extensions setup guide what is vvvv-editor-extensions vvvv-editor-extensions alternative vvvv-editor-extensions vs VL installing vvvv-editor-extensions mastering vvvv gamma ecosystem creating custom .HDE.vl patches NuGet packages for vvvv gamma vvvv编辑器扩展 AIエージェント VL patches NuGet VL.HDE Command节点 WindowFactory Standalone扩展 NuGet扩展 Creates custom extensions using VL patches saved with a .HDE.vl suffix Automatically runs extensions when opened in the editor Supports standalone extensions and NuGet packages with specific naming conventions Utilizes VL.HDE NuGet reference for Command node and window types Enables creation of mixed NuGet packages with main and extension documents vvvv-editor-extensions is a set of skills for AI Agents to create and manage custom extensions for the vvvv gamma ecosystem using .HDE.vl patches and NuGet packages.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('konecty/Konecty/codigo-limpo', 'community', 'konecty', 'Konecty', 'konecty/Konecty', 'codigo-limpo', 0, 0, 52, '2026-02-27T01:51:08.565Z', '2026-02-27T03:09:33.447Z', '5002907717d17cbad37fc1af01f7e4a02bf0424ec49980a4bbc39abd44735ed2', '{"id":"konecty/Konecty/codigo-limpo","name":"codigo-limpo","description":{"zh":"Konecty 开源技术商业平台提供代码清洁 AI代理，帮助开发者优化代码质量和提高开发效率。该平台支持多种编程语言，包括 Python、Node.js 和 React","ja":"Konecty オープンソーステクノロジービジネスプラットフォームの AIエージェントは、開発者がコードのクオリティーを向上させ、開発効率を高めるのに役立ちます。サポートされるプログラミング言語には、Python、Node.js、React が含まれます","ko":"Konecty 오픈소스 기술 비즈니스 플랫폼의 코드 클린 AI 에이전트는 개발자가 코드 품질을 개선하고 개발 효율을 높이는 데 도움을 주는 도구입니다. 지원하는 프로그래밍 언어로는 Python, Node.js, React 등이 있습니다","es":"Konecty es una plataforma de tecnología de código abierto que ayuda a los desarrolladores a crear un código limpio y eficiente","fr":"Konecty est une plateforme de technologie open source qui aide les développeurs à créer un code propre et efficace","de":"Konecty ist eine Open-Source-Technologieplattform, die Entwicklern hilft, einen sauberen und effizienten Code zu erstellen","pt":"Konecty é uma plataforma de tecnologia de código aberto para negócios, focada em desenvolvimento de código limpo","ru":"Konecty - открытая технологическая платформа для бизнеса, ориентированная на разработку чистого кода","ar":"كونيكتي هي منصة تقنية مفتوحة للمشاريع التجارية، تركز على تطوير كود نظيف","en":"Konecty Open source Tech Business Platform"},"seo":{"title":{"zh":"代码清洁 AI代理 - Konecty 开源技术商业平台","ja":"AIエージェント - コードクリーニング Konecty オープンソーステクノロジービジネスプラットフォーム","ko":"코드 클린 AI 에이전트 - Konecty 오픈소스 기술 비즈니스 플랫폼","es":"Herramientas de código limpio para desarrolladores","fr":"Outils de code propre pour les développeurs","de":"Tools für sauberen Code für Entwickler","pt":"Ferramentas de código limpo: Konecty Open Source","ru":"ИИ Агенты для чистого кода: Konecty Op