INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('konecty/Konecty/codigo-limpo', 'codigo-limpo', 'konecty', 'Konecty', 'community', 'codigo-limpo konecty Konecty community Konecty 开源技术商业平台提供代码清洁 AI代理，帮助开发者优化代码质量和提高开发效率。该平台支持多种编程语言，包括 Python、Node.js 和 React Konecty オープンソーステクノロジービジネスプラットフォームの AIエージェントは、開発者がコードのクオリティーを向上させ、開発効率を高めるのに役立ちます。サポートされるプログラミング言語には、Python、Node.js、React が含まれます Konecty 오픈소스 기술 비즈니스 플랫폼의 코드 클린 AI 에이전트는 개발자가 코드 품질을 개선하고 개발 효율을 높이는 데 도움을 주는 도구입니다. 지원하는 프로그래밍 언어로는 Python, Node.js, React 등이 있습니다 Konecty es una plataforma de tecnología de código abierto que ayuda a los desarrolladores a crear un código limpio y eficiente Konecty est une plateforme de technologie open source qui aide les développeurs à créer un code propre et efficace Konecty ist eine Open-Source-Technologieplattform, die Entwicklern hilft, einen sauberen und effizienten Code zu erstellen Konecty é uma plataforma de tecnologia de código aberto para negócios, focada em desenvolvimento de código limpo Konecty - открытая технологическая платформа для бизнеса, ориентированная на разработку чистого кода كونيكتي هي منصة تقنية مفتوحة للمشاريع التجارية، تركز على تطوير كود نظيف Konecty Open source Tech Business Platform 代码清洁 AI代理 Konecty 开源技术商业平台 代码质量优化 开发效率提高 人工智能技术 Python 开发 Node.js 开发 React 开发 Konecty Open source Tech Business Platform');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('microbus-io/fabric/Modifying a Feature of a Microservice', 'community', 'microbus-io', 'fabric', 'microbus-io/fabric', 'Modifying a Feature of a Microservice', 170, 5, 52, '2026-03-01T04:56:15Z', '2026-03-05T06:21:06.984Z', '2efebc46bb315d5e4c8c19740308353a9eb751ae9dea5ce66376de0c7b1e8f70', '{"id":"microbus-io/fabric/Modifying a Feature of a Microservice","name":"Modifying a Feature of a Microservice","description":{"zh":"Microbus教会AI智能代理修改微服务功能，掌握分布式系统和企业级微服务开发","ja":"MicrobusはAIエージェントにマイクロサービス機能の修正を教え、分布式システムとエンタープライズグレードのマイクロサービス開発をマスターさせる","ko":"Microbus는 AI 에이전트를 교육하여 마이크로 서비스 기능을 수정하고 분산 시스템 및 엔터프라이즈급 마이크로 서비스 개발을 마스터합니다","es":"Microbus enseña a los agentes de codificación a dominar el dominio complejo de los sistemas distribuidos y produce microservicios de nivel empresarial","fr":"Microbus enseigne aux agents de codage à maîtriser le domaine complexe des systèmes distribués et produit des microservices de niveau entreprise","de":"Microbus lehrt Codieragenten, das komplexe Gebiet der verteilten Systeme zu meistern und produziert Unternehmens-microservices","pt":"Desenvolva microsserviços de nível empresarial com agentes de IA. Aprenda a modificar recursos e dominar sistemas distribuídos","ru":"Производите микросервисы уровня предприятия с помощью ИИ Агентов. Изучите изменение функций и овладейте распределенными системами","ar":"انتج خدمات مايكروية على مستوى الشركات مع وكلاء الذكاء الاصطناعي. تعلم تعديل الميزات وتحكم في الأنظمة الموزعة","en":"Your coding agent can already code. Microbus teaches it to master the complex domain of distributed systems — the architecture, the patterns, the operational discipline — and produce enterprise-grade microservices, every time."},"seo":{"title":{"zh":"AI智能代理修改微服务功能","ja":"AIエージェントによるマイクロサービス機能の修正","ko":"AI 에이전트를 이용한 마이크로 서비스 기능 수정","es":"Herramientas de AI Agent: Modificar Características de Mi...","fr":"Outils d''Agents IA: Modifier les Fonctionnalités de Micro...","de":"AI Agent Tools: Modifizieren von Microservice-Funktionen","pt":"Agentes de IA: Modifique Recursos de Microsserviços","ru":"ИИ Агенты: Изменение Функций Микросервисов","ar":"وكلاء الذكاء الاصطناعي: تعديل ميزات الخدمات المايكروية","en":"Modifying a Feature of a Microservice"},"description":{"zh":"Microbus教会AI智能代理修改微服务功能，掌握分布式系统和企业级微服务开发","ja":"MicrobusはAIエージェントにマイクロサービス機能の修正を教え、分布式システムとエンタープライズグレードのマイクロサービス開発をマスターさせる","ko":"Microbus는 AI 에이전트를 교육하여 마이크로 서비스 기능을 수정하고 분산 시스템 및 엔터프라이즈급 마이크로 서비스 개발을 마스터합니다","es":"Microbus enseña a los agentes de codificación a dominar el dominio complejo de los sistemas distribuidos y produce microservicios de nivel empresarial","fr":"Microbus enseigne aux agents de codage à maîtriser le domaine complexe des systèmes distribués et produit des microservices de niveau entreprise","de":"Microbus lehrt Codieragenten, das komplexe Gebiet der verteilten Systeme zu meistern und produziert Unternehmens-microservices","pt":"Desenvolva microsserviços de nível empresarial com agentes de IA. Aprenda a modificar recursos e dominar sistemas distribuídos","ru":"Производите микросервисы уровня предприятия с помощью ИИ Агентов. Изучите изменение функций и овладейте распределенными системами","ar":"انتج خدمات مايكروية على مستوى الشركات مع وكلاء الذكاء الاصطناعي. تعلم تعديل الميزات وتحكم في الأنظمة الموزعة","en":"Your coding agent can already code. Microbus teaches it to master the complex domain of distributed systems — the architecture, the patterns, the operational..."},"definition":{"en":"Your coding agent can already code. Microbus teaches it to master the complex domain of distributed systems — the architecture, the patterns, the operational discipline — and produce enterprise-grade microservices, every time."},"features":{"zh":["分布式系统的架构和设计","企业级微服务开发","AI智能代理的教育和训练","微服务功能的修改和优化","MessageBus和框架的支持"],"ja":["分布式システムのアーキテクチャと設計","エンタープライズグレードのマイクロサービス開発","AIエージェントの教育とトレーニング","マイクロサービス機能の修正と最適化","MessageBusとフレームワークのサポート"],"ko":["분산 시스템의 아키텍처와 설계","엔터프라이즈급 마이크로 서비스 개발","AI 에이전트의 교육과 훈련","마이크로 서비스 기능의 수정과 최적화","MessageBus와 프레임워크의 지원"],"es":["Arquitectura de sistemas distribuidos","Patrones de diseño de microservicios","Disciplina operativa para microservicios","Creación de microservicios de nivel empresarial","Integración con frameworks de mensajería","Soporte para código abierto"],"fr":["Architecture de systèmes distribués","Modèles de conception de microservices","Discipline opérationnelle pour les microservices","Création de microservices de niveau entreprise","Intégration avec des frameworks de messagerie","Support pour le code ouvert"],"de":["Architektur von verteilten Systemen","Entwurfsmuster für Microservices","Betriebsdisziplin für Microservices","Erstellung von Unternehmens-microservices","Integration mit Messaging-Frameworks","Unterstützung für Open-Source-Code"],"pt":["Desenvolvimento de microsserviços de nível empresarial","Modificação de recursos de microsserviços","Domínio de sistemas distribuídos","Integração com frameworks e message bus","Código de nível empresarial","Operacionalização de microsserviços"],"ru":["Производство микросервисов уровня предприятия","Изменение функций микросервисов","Овладение распределенными системами","Интеграция с фреймворками и message bus","Код уровня предприятия","Операционализация микросервисов"],"ar":["إنتاج خدمات مايكروية على مستوى الشركات","تعديل ميزات الخدمات المايكروية","تطوير مهارات في الأنظمة الموزعة","التكامل مع الإطارات والباص الرسائل","كود على مستوى الشركات","التشغيل الخدمات المايكروية"]},"keywords":{"zh":["AI智能代理","微服务功能修改","分布式系统","企业级微服务开发","MessageBus","框架","如何使用AI智能代理","什么是微服务","AI智能代理安装","微服务功能设置指南"],"ja":["AIエージェント","マイクロサービス機能の修正","分布式システム","エンタープライズグレードのマイクロサービス開発","MessageBus","フレームワーク","AIエージェントの使用方法","マイクロサービスの定義","AIエージェントのインストール","マイクロサービス機能の設定ガイド"],"ko":["AI 에이전트","마이크로 서비스 기능 수정","분산 시스템","엔터프라이즈급 마이크로 서비스 개발","MessageBus","프레임워크","AI 에이전트의 사용 방법","마이크로 서비스의 정의","AI 에이전트의 설치","마이크로 서비스 기능의 설정 가이드"],"es":["cómo usar herramientas de AI Agent","qué es un microservicio","alternative a Microbus","Microbus vs otros frameworks","instalación de Microbus","guía de configuración de Microbus","desarrollo de microservicios con AI Agent","patrones de diseño de microservicios","sistemas distribuidos con AI Agent"],"fr":["comment utiliser des outils d''Agents IA","qu''est-ce qu''un microservice","alternative à Microbus","Microbus vs d''autres frameworks","installation de Microbus","guide de configuration de Microbus","développement de microservices avec des Agents IA","modèles de conception de microservices","systèmes distribués avec des Agents IA"],"de":["wie man AI Agent-Tools verwendet","was ist ein Microservice","Alternative zu Microbus","Microbus vs andere Frameworks","Installation von Microbus","Konfigurationsanleitung für Microbus","Entwicklung von Microservices mit AI-Agents","Entwurfsmuster für Microservices","verteilte Systeme mit AI-Agents"],"pt":["agentes de IA","microsserviços","sistemas distribuídos","frameworks","message bus","desenvolvimento de microsserviços","modificação de recursos","código de nível empresarial","operacionalização de microsserviços","guia de instalação de microsserviços"],"ru":["ИИ Агенты","микросервисы","распределенные системы","фреймворки","message bus","производство микросервисов","изменение функций","код уровня предприятия","операционализация микросервисов","руководство по установке микросервисов"],"ar":["وكلاء الذكاء الاصطناعي","خدمات مايكروية","أنظمة موزعة","الإطارات","باص الرسائل","إنتاج خدمات مايكروية","تعديل الميزات","كود على مستوى الشركات","التشغيل الخدمات المايكروية","دليل تثبيت الخدمات المايكروية"]}},"owner":"microbus-io","repo":"fabric","repoPath":"microbus-io/fabric","stars":170,"forks":5,"updatedAt":"2026-03-01T04:56:15Z","topics":["framework","messagebus","microservices","opensource"],"category":"community","skillMd":{"name":"Modifying a Feature of a Microservice","description":"Modifies an existing functional endpoint, web handler endpoint, event source, event sink, configuration property, ticker or metric of a microservice. Use when explicitly asked by the user to modify a feature of a microservice.","bodyPreview":"**CRITICAL**: Read and analyze this microservice before starting. Do NOT explore or analyze other microservices. The instructions in this skill are self-contained to this microservice.\n\n**CRITICAL**: Do not omit the `MARKER` comments when generating code. They are intended as waypoints for future edits.\n\n## Workflow\n\nCopy this checklist and track your progress:\n\n```\nModifying a feature of a microservice:\n- [ ] Step 1: Read local AGENTS.md file\n- [ ] Step 2: Identify the feature\n- [ ] Step 3: Con","body":"**CRITICAL**: Read and analyze this microservice before starting. Do NOT explore or analyze other microservices. The instructions in this skill are self-contained to this microservice.\n\n**CRITICAL**: Do not omit the `MARKER` comments when generating code. They are intended as waypoints for future edits.\n\n## Workflow\n\nCopy this checklist and track your progress:\n\n```\nModifying a feature of a microservice:\n- [ ] Step 1: Read local AGENTS.md file\n- [ ] Step 2: Identify the feature\n- [ ] Step 3: Consult the corresponding \"add\" skill\n- [ ] Step 4: Locate the feature''s code\n- [ ] Step 5: Determine the scope of the change\n- [ ] Step 6: Apply the modifications\n- [ ] Step 7: Housekeeping\n```\n\n#### Step 1: Read Local `AGENTS.md` File\n\nRead the local `AGENTS.md` file in the microservice''s directory. It contains microservice-specific instructions that should take precedence over global instructions.\n\n#### Step 2: Identify the Feature\n\nDetermine the feature''s name and type by reading the microservice''s `manifest.yaml`. The feature type corresponds to its manifest section:\n\n| Manifest section | Feature type | Corresponding skill |\n|---|---|---|\n| `functions` | Functional endpoint | `microbus/add-function` |\n| `webs` | Web handler | `microbus/add-web` |\n| `configs` | Configuration property | `microbus/add-config` |\n| `tickers` | Ticker | `microbus/add-ticker` |\n| `metrics` | Metric | `microbus/add-metric` |\n| `outboundEvents` | Outbound event | `microbus/add-outbound-event` |\n| `inboundEvents` | Inbound event | `microbus/add-inbound-event` |\n\n#### Step 3: Consult the Corresponding \"Add\" Skill\n\nRead the `SKILL.md` of the corresponding \"add\" skill identified in the previous step (e.g., `.claude/skills/microbus/add-function/SKILL.md`). The templates in that skill define what the code should look like after modification. Use it as your reference throughout the remaining steps.\n\n#### Step 4: Locate the Feature''s Code\n\nSearch for `MARKER: FeatureName` within the microservice''s directory and its subdirectories to find all code locations related to the feature. This gives you the complete set of places that may need editing.\n\n#### Step 5: Determine the Scope of the Change\n\nCategorize the requested change to understand its blast radius:\n\n- **Implementation only** — Changes to the handler body in `service.go`. Tests in `service_test.go` may also need to be updated to reflect the new behavior.\n- **Property change** — Changes to the route, method, required claims, description, config default or validation, ticker interval, or metric buckets. Affects a subset of the marked locations, typically `intermediate.go`, `myserviceapi/client.go`, and `manifest.yaml`.\n- **Signature change** — Arguments added, removed, renamed, or retyped. This has a wide blast radius: every file with the feature''s marker must be updated. See the detailed list below.\n- **Rename** — The feature''s name changes. This has the widest blast radius: all markers, identifiers, struct names, and references must be renamed across every file.\n\nThese scopes can overlap. For example, a rename combined with a signature change should be treated as a single pass: rename all identifiers and markers while simultaneously updating the signature at each location.\n\n#### Step 6: Apply the Modifications\n\nEdit each affected location, using the \"add\" skill''s templates as the reference for what the updated code should look like.\n\nFor **implementation-only** changes, edit the handler in `service.go` and update tests in `service_test.go` if the expected behavior changes.\n\nFor **property changes**, edit the relevant subset of marked locations. Common examples:\n- Route change: update the route const in `myserviceapi/client.go`, the `Subscribe` call in `intermediate.go`, and `manifest.yaml`\n- Method change: update the `Subscribe` call in `intermediate.go`, the `_method` value in client methods in `myserviceapi/client.go`, the OpenAPI registration in `intermediate.go`, and `manifest.yaml`\n- Required claims change: update the `Subscribe` call in `intermediate.go`, the OpenAPI registration in `intermediate.go`, and `manifest.yaml`\n\nFor **signature changes**, update every marked location. All of the following must be updated to reflect the new signature:\n- `intermediate.go` — `ToDo` interface method, marshaler function, OpenAPI registration (Summary, InputArgs, OutputArgs)\n- `myserviceapi/client.go` — In/Out/Response structs and their methods, Client method, MulticastClient method\n- `myserviceapi/*.go` — Add definitions for new complex types; remove definitions for types no longer used\n- `service.go` — Handler function signature\n- `mock.go` — Mock field type, MockX setter signature, X executor signature, mock test case\n- `service_test.go` — Test cases that call the function with the old signature\n\nFor **renames**, update every marked location with the new feature name. This includes all identifiers derived from the feature name (e.g., `MyFunction` becomes `NewName`, `doMyFunction` becomes `doNewName`, `MockMyFunction` becomes `MockNewName`, `MyFunctionIn` becomes `NewNameIn`, `RouteOfMyFunction` becomes `RouteOfNewName`, etc.) and all `MARKER` comments. In `service_test.go`, also rename the test function (e.g., `TestMyService_MyFunction` becomes `TestMyService_NewName`) and the mock subtest name.\n\n#### Step 7: Housekeeping\n\nFollow the `microbus/housekeeping` skill.\n"},"lastSynced":"2026-03-05T06:21:06.984Z","agentAnalysis":{"suitability":{"en":"Perfect for Distributed System Agents needing to master microservice architecture and operational discipline.","zh":"适合于需要掌握微服务架构和运维纪律的分布式系统代理。","ja":"マイクロサービスのアーキテクチャと運用規律をマスターする必要がある分散システムエージェントに最適です。","ko":"마이크로 서비스 아키텍처와 운영 규율을 마스터해야 하는 분산 시스템 에이전트에 적합합니다.","es":"Perfecto para Agentes de Sistemas Distribuidos que necesitan dominar la arquitectura de microservicios y la disciplina operativa.","fr":"Parfait pour les Agents de Systèmes Distribués ayant besoin de maîtriser l''architecture de microservices et la discipline opérationnelle.","de":"Perfekt für Distributed System Agents, die die Mikroservices-Architektur und die betriebliche Disziplin meistern müssen.","pt":"Perfeito para Agentes de Sistemas Distribuídos que precisam dominar a arquitetura de microsserviços e disciplina operacional.","ru":"Идеально подходит для агентов распределенных систем, которым необходимо освоить микросервисную архитектуру и операционную дисциплину.","ar":"مثالي لعميل نظام موزع يحتاج إلى التسلط على هندسة الخدمات الدقيقة وتأديب التشغيل."},"recommendation":{"en":"Empowers agents to produce enterprise-grade microservices by modifying features, utilizing MARKER comments for future edits, and adhering to self-contained microservice instructions, leveraging distributed system patterns and operational discipline.","zh":"使代理能够通过修改功能、利用MARKER注释进行未来编辑以及遵循自包含的微服务指令，利用分布式系统模式和运维纪律，生成企业级的微服务。","ja":"MARKERコメントを使用して将来の編集を行い、自己完結型のマイクロサービス指令に従い、分散システムパターンと運用規律を活用して、エンタープライズグレードのマイクロサービスを生成できるようにエージェントをエンパワーメントします。","ko":"MARKER 주석을 사용하여 미래의 편집을 수행하고, 자체 포함된 마이크로 서비스 지침을 따르며, 분산 시스템 패턴 및 운영 규율을 활용하여, 기업급 마이크로 서비스를 생성 할 수 있는 에이전트를 에ンパ워합니다.","es":"Habilita a los agentes a producir microservicios de nivel empresarial modificando características, utilizando comentarios MARKER para futuras ediciones y siguiendo instrucciones de microservicios autocontenidos, aprovechando patrones de sistemas distribuidos y disciplina operativa.","fr":"Permet aux agents de produire des microservices de niveau entreprise en modifiant les fonctionnalités, en utilisant des commentaires MARKER pour les éditions futures et en suivant les instructions de microservices autocontenues, en exploitant les modèles de systèmes distribués et la discipline opérationnelle.","de":"Ermächtigt die Agenten, Unternehmensgrade-Mikroservices zu produzieren, indem sie Funktionen modifizieren, MARKER-Kommentare für zukünftige Bearbeitungen verwenden und selbstenthaltene Mikroservice-Anweisungen befolgen, wobei sie auf verteilte Systemmuster und betriebliche Disziplin zurückgreifen.","pt":"Habilita os agentes a produzir microsserviços de classe empresarial, modificando recursos, utilizando comentários MARKER para edições futuras e aderindo a instruções de microsserviços autossuficientes, aproveitando padrões de sistemas distribuídos e disciplina operacional.","ru":"Наделяет агентов возможностью создавать корпоративный уровень микросервисов, изменяя функции, используя комментарии MARKER для будущих правок и придерживаясь самодостаточных инструкций микросервисов, используя шаблоны распределенных систем и операционную дисциплину.","ar":"يمنح العميل القدرة على إنتاج خدمات دقيقة من فئة الشركات عن طريق تعديل الميزات وتحويل تعليقات MARKER للتعديلات المستقبلية والالتزام بإرشادات الخدمات الدقيقة المستقلة واستخدام أنماط النظام الموزع وتأديب التشغيل."},"useCases":{"en":["Modifying existing microservice features","Generating enterprise-grade microservices","Debugging microservice architectures"],"zh":["修改现有的微服务功能","生成企业级的微服务","调试微服务架构"],"ja":["既存のマイクロサービスの機能を変更する","エンタープライズグレードのマイクロサービスを生成する","マイクロサービスのアーキテクチャをデバッグする"],"ko":["기존의 마이크로 서비스 기능을 수정합니다","기업급 마이크로 서비스를 생성합니다","마이크로 서비스 아키텍처를 디버깅합니다"],"es":["Modificar características de microservicios existentes","Generar microservicios de nivel empresarial","Depurar arquitecturas de microservicios"],"fr":["Modifier les fonctionnalités de microservices existants","Générer des microservices de niveau entreprise","Déboguer les architectures de microservices"],"de":["Vorhandene Mikroservice-Funktionen modifizieren","Unternehmensgrade-Mikroservices generieren","Mikroservice-Architekturen debuggen"],"pt":["Modificar recursos de microsserviço existentes","Gerar microsserviços de classe empresarial","Depurar arquiteturas de microsserviço"],"ru":["Модифицировать существующие функции микросервиса","Генерировать корпоративный уровень микросервисов","Отлаживать архитектуру микросервиса"],"ar":["تعديل ميزات الخدمات الدقيقة الحالية","توليد خدمات دقيقة من فئة الشركات","تصحيح أخطاء هندسة الخدمات الدقيقة"]},"limitations":{"en":["Requires analysis of local AGENTS.md file","Limited to self-contained microservice instructions","Must include MARKER comments in generated code"],"zh":["需要分析本地的AGENTS.md文件","仅限于自包含的微服务指令","必须在生成的代码中包含MARKER注释"],"ja":["ローカルのAGENTS.mdファイルを分析する必要がある","自己完結型のマイクロサービス指令のみに限定される","生成されたコードにMARKERコメントを含める必要がある"],"ko":["로컬의 AGENTS.md 파일을 분석해야 합니다","자체 포함된 마이크로 서비스 지침만 제한됩니다","생성된 코드에 MARKER 주석을 포함해야 합니다"],"es":["Requiere análisis del archivo AGENTS.md local","Limitado a instrucciones de microservicios autocontenidos","Debe incluir comentarios MARKER en el código generado"],"fr":["Nécessite l''analyse du fichier AGENTS.md local","Limité aux instructions de microservices autocontenues","Doit inclure des commentaires MARKER dans le code généré"],"de":["Erfordert Analyse der lokalen AGENTS.md-Datei","Begrenzt auf selbstenthaltene Mikroservice-Anweisungen","Muss MARKER-Kommentare im generierten Code enthalten"],"pt":["Exige análise do arquivo local AGENTS.md","Limitado a instruções de microsserviços autossuficientes","Deve incluir comentários MARKER no código gerado"],"ru":["Требует анализа локального файла AGENTS.md","Ограничен самодостаточными инструкциями микросервисов","Должен включать комментарии MARKER в сгенерированном коде"],"ar":["يتطلب تحليل ملف AGENTS.md المحلي","محدود بإرشادات الخدمات الدقيقة المستقلة","يجب أن يتضمن تعليقات MARKER في الكود المولّد"]},"version":3},"contentHash":"2efebc46bb315d5e4c8c19740308353a9eb751ae9dea5ce66376de0c7b1e8f70","qualityScore":52}');
