INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Jackiexiao/jackie-skills-starter/baoyu-cover-image', 'baoyu-cover-image', 'Jackiexiao', 'jackie-skills-starter', 'community', 'baoyu-cover-image Jackiexiao jackie-skills-starter community baoyu-cover-image是一款为开发者打造的AI智能工具，提供一键式OpenClaw技能包，简化开发流程 baoyu-cover-imageは開発者向けのAIエージェントで、OpenClawスキルパックを一括で提供します baoyu-cover-image는 개발자를 위한 AI 에이전트로 OpenClaw 스킬 팩을 한 번에 제공합니다 baoyu-cover-image es un paquete de habilidades de OpenClaw curado para desarrolladores baoyu-cover-image est un pack de compétences OpenClaw créé pour les développeurs baoyu-cover-image ist ein kuratiertes OpenClaw-Skills-Paket für Entwickler O baoyu-cover-image é um pacote de habilidades OpenClaw curado de uma linha de comando para desenvolvedores baoyu-cover-image - это набор навыков OpenClaw из одной командной строки для разработчиков baoyu-cover-image هو حزمة مهارات OpenClaw من سطر أوامر واحد لالمطورين Curated one-command OpenClaw skills pack AI智能工具 OpenClaw技能包 开发者工具 CLI工具 如何使用baoyu-cover-image baoyu-cover-image安装 baoyu-cover-image文档 Curated one-command OpenClaw skills pack');
